test('post-commit auto-roll callback rolls back independently and never turns a finished source into false-after-commit', () => {
  const e=loadEngine(),actor=hero('post-commit-rollback',{hp:10,hpMax:20}),next=hero('post-commit-next',{hp:10,hpMax:20});
  e.setState({chars:[actor,next],activeCharId:actor.id});
  const preflight={ok:true,noop:true,kind:'bg3-interrupt-composite-preflight',plans:[],results:[],carriers:[]},permit=e.bg3InterruptCastBegin(preflight),seen=[];
  assert.equal(permit.ok,true);e.setAutoRolls([1,2]);
  e.askRolls({title:'failing post-commit callback',rows:[{key:'d',label:'d'}],apply:()=>{actor.hp=1;throw new Error('injected post-commit callback failure');}});
  e.askRolls({title:'next post-commit callback',rows:[{key:'d',label:'d'}],apply:function(v){next.hp-=v.d;seen.push(v.d);assert.equal(this.title,'next post-commit callback');}});
  let finished;assert.doesNotThrow(()=>{finished=e.bg3InterruptCastFinish(permit);});assert.equal(finished.ok,true);assert.equal(finished.noop,true);
  assert.equal(permit.locked,false,'the source permit remains successfully finished');assert.equal(actor.hp,10,'only the failed callback world mutation rolls back');
  assert.equal(next.hp,8,'the next committed prompt still runs after the failed callback');assert.deepEqual(seen,[2]);assert.equal(e.pendingRollSpec(),null);assert.equal(e.rollPromptState().queue.length,0);
  assert.match(e.elementText('saveStatus'),/post-commit roll consequence rolled back/);
});

test('production spell remains committed when its deferred healing auto-roll callback throws', () => {
  const e=loadEngine(),caster=hero('post-commit-spell-caster',{slots:{1:{max:1,cur:1}}}),target=hero('post-commit-spell-target',{hp:1,hpMax:20}),
    spell={id:'post-commit-heal',n:'Post-commit heal',l:1,cm:'В, С',d:'Мгновенная',conc:false,x:'Касание восстанавливает 1к8 + модификатор базовой характеристики хитов.'};
  e.setState({chars:[caster,target],spells:[spell],activeCharId:caster.id});e.setAutoRolls([1]);
  let storedHp=target.hp,writes=0;Object.defineProperty(target,'hp',{configurable:true,enumerable:true,get:()=>storedHp,set:value=>{if(++writes===1)throw new Error('injected healing callback failure');storedHp=value;}});
  assert.equal(e.castSpellApply(spell.id,caster.id,`ally:${target.id}`,'',undefined,'1'),true,'a post-commit callback failure cannot falsify the source result');
  assert.equal(caster.slots[1].cur,0,'the successfully committed source keeps its slot spend');assert.equal(target.hp,1,'the failed healing consequence is independently rolled back');
  assert.match(e.elementText('saveStatus'),/post-commit roll consequence rolled back/);assert.equal(e.pendingRollSpec(),null);
});

