test('святая вода проверяет тип цели, а малое восстановление проверяет состояние до расхода', () => {
  const e = loadEngine(), items = e.seedItemsDB(), spells = e.seedSpellsDB(), foes = e.seedFoesDB();
  const holy = items.find(it => it.id === 'it_holy_water');
  const thrower = hero('thrower', {inventory: [{id: 'holy', itemId: holy.id, qty: 2}]});
  const goblin = foes.find(f => f.id === 'foe_goblin_scout'), zombie = foes.find(f => f.id === 'foe_zombie');
  zombie.hp = zombie.hpMax = 30;
  e.setState({chars: [thrower], items, spells, foes: [goblin, zombie]});
  const hit = {hit: true, attackMade: true, saveOk: null, dmgRaw: 7, dmgTotal: 7, dmgType: 'сияние',
    damageParts: [{type: 'сияние', raw: 7, total: 7}], effectAllowed: true, verdict: [], notes: []};
  assert.equal(e.useItemApply('holy', thrower.id, `foe:${goblin.id}`, hit, 'throw', {distanceM: 6}), false);
  assert.equal(thrower.inventory[0].qty, 2);
  assert.equal(e.useItemApply('holy', thrower.id, `foe:${zombie.id}`, hit, 'throw', {distanceM: 6}), true);
  assert.equal(thrower.inventory[0].qty, 1);
  assert.equal(zombie.hp, 23);

  const restoration = items.find(it => it.id === 'it_scroll_lesser_restoration');
  const cleric = hero('restorer', {cls: 'Жрец', level: 3, inventory: [{id: 'restoration', itemId: restoration.id, qty: 2}]});
  const patient = hero('patient');
  e.setState({chars: [cleric, patient], items, spells});
  assert.equal(e.useItemApply('restoration', cleric.id, `ally:${patient.id}`, null, 'cast', {choice: 'Отравленный', distanceM: 1}), false);
  assert.equal(cleric.inventory[0].qty, 2);
  patient.cond.push('Отравленный');
  assert.equal(e.useItemApply('restoration', cleric.id, `ally:${patient.id}`, null, 'cast', {choice: 'Отравленный', distanceM: 1}), true);
  assert.equal(cleric.inventory[0].qty, 1);
  assert.equal(e.effectiveConditions(patient).includes('Отравленный'), false);
  patient.diseases = ['Канализационная чума'];
  e.setState({chars: [cleric, patient], items, spells, activeCharId: patient.id});
  assert.ok(e.renderSheetPanel('stats').includes('Канализационная чума'), 'болезнь редактируется и видна на листе');
  assert.equal(e.useItemApply('restoration', cleric.id, `ally:${patient.id}`, null, 'cast', {choice: 'disease:Канализационная чума', distanceM: 1}), true);
  assert.equal(cleric.inventory.length, 0);
  assert.deepEqual(plain(patient.diseases), []);
});

test('один Алмаз хранит цену у экземпляра и покрывает все заклинания по их собственным правилам', () => {
  const e = loadEngine(), items = e.seedItemsDB(), spells = e.seedSpellsDB();
  const cases = [
    ['sp_chromatic_orb', 50, 0],
    ['sp_оживление', 300, 1],
    ['sp_воскрешение_мертвого', 500, 1],
    ['sp_воскрешение', 1000, 1],
    ['sp_врата', 5000, 0],
    ['sp_истинное_воскрешение', 25000, 1],
  ];
  const diamond = items.find(it => it.id === 'it_diamond'), dust = items.find(it => it.id === 'it_diamond_dust');
  assert.ok(diamond && dust);
  assert.equal(items.filter(it => e.itemIdentityKey(it.n) === 'алмаз').length, 1);
  assert.equal(items.some(it => /^it_component_diamond/.test(it.id) || /^it_component_diamonds/.test(it.id) || it.id === 'it_diamond_torg'), false);
  assert.deepEqual(plain(e.itemProfile(diamond).roles), ['treasure', 'trade', 'jewelry', 'crafting', 'spellComponent']);

  const holyWater = items.find(it => it.id === 'it_holy_water');
  assert.ok(holyWater);
  const caster = hero('component-caster', {inventory: cases.map(([, value], i) => ({id: `component-${i}`, itemId: diamond.id, qty: 2, valueGp: value}))
    .concat([{id: 'unknown-value', itemId: diamond.id, qty: 1}, {id: 'dust', itemId: dust.id, qty: 2},
      {id: 'true-resurrection-water', itemId: holyWater.id, qty: 1}])});
  e.setState({chars: [caster], items, spells});

  for (let i = 0; i < cases.length; i++) {
    const [spellId, value, consume] = cases[i], spell = spells.find(sp => sp.id === spellId);
    assert.ok(spell, `${spellId}: заклинание есть в базе`);
    const comp = e.parseComponents(spell);
    assert.equal(e.materialPlanFor(caster, spell, comp, {substitute: true}).ok, false, 'стоимостный компонент нельзя заменить фокусировкой');
    const plan = e.materialPlanFor(caster, spell, comp, {entryId: `component-${i}`, use: consume});
    assert.equal(plan.ok, true, `${spellId}: ${plan.reason || ''}`);
    assert.equal(plan.valueGp, value);
    assert.equal(e.commitMaterialPlan(caster, plan).ok, true);
    assert.equal(caster.inventory.find(x => x.id === `component-${i}`).qty, 2 - consume);
  }
  assert.equal(caster.inventory.some(x => x.id === 'true-resurrection-water'), false,
    'Истинное воскрешение расходует святую воду вместе с алмазами');

  const orb = spells.find(sp => sp.id === 'sp_chromatic_orb');
  assert.match(e.materialPlanFor(caster, orb, e.parseComponents(orb), {entryId: 'unknown-value', use: 0}).reason, /не указана оценочная стоимость/);
  const stoneskin = spells.find(sp => sp.id === 'sp_каменная_кожа');
  assert.ok(stoneskin);
  const wholeOnly=hero('whole-only',{inventory:[{id:'whole',itemId:diamond.id,qty:1,valueGp:1000}]});
  e.setState({chars:[wholeOnly],items,spells});
  assert.equal(e.materialPlanFor(wholeOnly, stoneskin, e.parseComponents(stoneskin), {aggregate:true}).ok, false, 'целый алмаз не является алмазной пылью');
  e.setState({chars:[caster],items,spells});
  const dustPlan = e.materialPlanFor(caster, stoneskin, e.parseComponents(stoneskin), {entryId: 'dust', use: 1});
  assert.equal(dustPlan.ok, true, dustPlan.reason || 'алмазная пыль подходит');
  assert.equal(e.commitMaterialPlan(caster, dustPlan).ok, true);
  assert.equal(caster.inventory.find(x => x.id === 'dust').qty, 1);

  const labels=e.itemActions(caster,caster.inventory[0],diamond).map(x=>x.label);
  assert.ok(labels.includes('Связи и свойства') && labels.includes('Продать'), 'алмаз остается материалом и самостоятельной ценностью');

  const revivify=spells.find(sp=>sp.id==='sp_оживление'),raiseDead=spells.find(sp=>sp.id==='sp_воскрешение_мертвого');
  const many=hero('many-diamonds',{inventory:[{id:'hundreds',itemId:diamond.id,qty:3,valueGp:100}]});
  e.setState({chars:[many],items,spells});
  const manyPlan=e.materialPlanFor(many,revivify,e.parseComponents(revivify),{aggregate:true});
  assert.equal(manyPlan.ok,true,manyPlan.reason||'три алмаза по 100 зм покрывают общую цену');
  assert.deepEqual(plain(manyPlan.deductions),[{entryId:'hundreds',itemId:'it_diamond',qty:3,label:'Алмаз',unitValueGp:100}]);
  assert.equal(e.commitMaterialPlan(many,manyPlan).ok,true);
  assert.equal(many.inventory.length,0);

  const tooSmall=hero('small-diamonds',{inventory:[{id:'small',itemId:diamond.id,qty:5,valueGp:100}]});
  e.setState({chars:[tooSmall],items,spells});
  assert.equal(e.materialPlanFor(tooSmall,raiseDead,e.parseComponents(raiseDead),{entryId:'small',use:1}).ok,false,
    'пять мелких камней не заменяют один алмаз ценой 500 зм там, где правило требует один камень');
});

test('aggregate material cost: a known zero stays matched without becoming one copper', () => {
  const e = loadEngine(), items = e.seedItemsDB(), spells = e.seedSpellsDB(), diamond = items.find(it => it.id === 'it_diamond'),
    revivify = spells.find(sp => sp.id === 'sp_оживление'), caster = hero('zero-value-diamonds', {inventory: [{id: 'free-diamonds', itemId: diamond.id, qty: 4, valueGp: 0}]});
  e.setState({chars: [caster], items, spells});
  const plan = e.materialPlanFor(caster, revivify, e.parseComponents(revivify), {aggregate: true});
  assert.equal(plan.ok, false);
  assert.match(plan.reason, /Подтвержденная общая стоимость — 0 зм, требуется не менее 300 зм/);
  assert.doesNotMatch(plan.reason, /не указана оценка|не найден/);
  assert.deepEqual(plain(caster.inventory), [{id: 'free-diamonds', itemId: diamond.id, qty: 4, valueGp: 0}], 'failed all-zero aggregate is a pure preflight');

  const subCopper = hero('sub-copper-diamonds', {inventory: [{id: 'rounded-diamonds', itemId: diamond.id, qty: 3, valueGp: 99.999}]});
  e.setState({chars: [subCopper], items, spells});
  const subCopperBefore=plain(subCopper.inventory),subCopperPlan=e.materialPlanFor(subCopper, revivify, e.parseComponents(revivify), {aggregate: true});
  assert.equal(subCopperPlan.ok, false);assert.match(subCopperPlan.reason, /точностью до медной монеты/);
  assert.deepEqual(plain(subCopper.inventory), subCopperBefore, 'three 99.999 gp components cannot round up to a 300 gp aggregate');
});

test('миграция склеивает все опубликованные дубли и переводит прежние алмазы без потери цены и вложений', () => {
  const e = loadEngine(), items = e.seedItemsDB();
  const spellingAliases = [
    ['it_верёвка_пеньковая_15_м','it_веревка_пеньковая_15_м'],
    ['it_верёвка_шёлковая_15_м','it_веревка_шелковая_15_м'],
    ['it_верёвочная_лестница_3_м','it_веревочная_лестница_3_м'],
    ['it_длинное_копьё_пика','it_длинное_копье_пика'],
    ['it_кавалерийское_копьё','it_кавалерийское_копье'],
    ['it_копьё','it_копье'],
    ['it_лёгкий_арбалет','it_легкий_арбалет'],
    ['it_лёгкий_молот','it_легкий_молот'],
    ['it_метательное_копьё','it_метательное_копье'],
    ['it_проклёпанная_кожа_arm','it_проклепанная_кожа_arm'],
    ['it_стёганый_arm','it_стеганый_arm'],
    ['it_тяжёлый_арбалет','it_тяжелый_арбалет'],
  ];
  const legacyPairs = spellingAliases.concat([
    ['it_зелье_лечения_2к4_2','it_зелье_лечения_2d4_2'],
    ['it_набор_целителя_10_исп','it_healer_kit_t'],
  ]);
  for (const [oldId,targetId] of legacyPairs) {
    const target=items.find(it=>it.id===targetId);
    assert.ok(target, targetId);
    const old=plain(target); old.id=oldId;
    if(oldId.includes('2к4')) old.n='Зелье лечения (2к4+2)';
    if(oldId.includes('набор_целителя')) old.n='Набор целителя (10 исп.)';
    items.push(old);
  }
  const diamondAliases = [
    ['it_diamond_torg',100],['it_component_diamond_50',50],['it_component_diamonds_300',300],
    ['it_component_diamond_500',500],['it_component_diamond_1000',1000],['it_component_diamonds_25000',25000],
  ];
  const diamond=items.find(it=>it.id==='it_diamond');
  diamondAliases.forEach(([id,value])=>items.push({id,n:'Старая запись алмаза '+value,type:'equipment',tags:['gem'],cost:value+' зм',desc:''}));

  const inventory=legacyPairs.map(([oldId],i)=>({id:'legacy-'+i,itemId:oldId,qty:1}));
  diamondAliases.forEach(([oldId],i)=>inventory.push({id:'diamond-'+i,itemId:oldId,qty:1}));
  inventory.push({id:'holder',itemId:'it_gem_pouch',qty:1,inside:[{id:'inner-diamond',itemId:'it_component_diamond_50',qty:1}]});
  const party=[hero('migrated',{inventory})],before=items.length;
  e.setState({chars:party,items});
  const result=e.canonicalizeItemDatabase(items,party,{});

  assert.equal(before-items.length,20);
  assert.equal(result.removed.length,20);
  assert.equal(result.remapped,21);
  assert.equal(result.valued,7);
  for (const [oldId,targetId] of legacyPairs) {
    assert.equal(items.some(it=>it.id===oldId),false,oldId+' удален');
    assert.ok(party[0].inventory.some(x=>x.itemId===targetId),targetId+' получил ссылку');
  }
  diamondAliases.forEach(([oldId,value],i)=>{
    const entry=party[0].inventory.find(x=>x.id==='diamond-'+i);
    assert.equal(entry.itemId,diamond.id);
    assert.equal(entry.valueGp,value);
    assert.equal(items.some(it=>it.id===oldId),false);
  });
  const inside=party[0].inventory.find(x=>x.id==='holder').inside[0];
  assert.deepEqual(plain({itemId:inside.itemId,valueGp:inside.valueGp}),{itemId:'it_diamond',valueGp:50});
  const names=items.map(it=>e.itemIdentityKey(it.n));
  assert.equal(new Set(names).size,names.length,'после миграции нет повторных сущностей по имени');
});

test('матрица всей базы не допускает урон при промахе и длительный эффект после успешного спасброска', () => {
  const e = loadEngine();
  const spells = e.seedSpellsDB(), abilities = e.seedAbilitiesDB(), foes = e.seedFoesDB();
  const allSaves = {str: true, dex: true, con: true, int: true, wis: true, cha: true};
  const maxAb = {str: 30, dex: 30, con: 30, int: 30, wis: 30, cha: 30};
  const caster = hero('caster', {level: 20, ab: {str: 18, dex: 18, con: 18, int: 18, wis: 20, cha: 18}});
  const defender = hero('defender', {level: 20, acOverride: 30, ab: maxAb, saves: allSaves, hp: 1000, hpMax: 1000});
  const target = {id: 'matrix-target', n: 'Матричная цель', kind: 'monster', ac: 30, hp: 1000, hpMax: 1000, hpTemp: 0,
    abil: maxAb, saveP: allSaves, profB: 6, resist: [], vuln: [], immune: [], condImmune: [], cond: [], activeFx: [], combatActions: []};
  e.setState({chars: [caster, defender], spells, abilities, foes: foes.concat(target)});

  const valuesFor = (spec, attackNatural, saveNatural) => {
    const v = {};
    spec.rows.forEach(row => {
      if(row.type === 'atk'){
        v[row.key] = attackNatural;
        if(row.adv) v[row.key + '_2'] = attackNatural;
      } else if(row.type === 'save'){
        v[row.key] = saveNatural;
        if(row.adv) v[row.key + '_2'] = saveNatural;
      } else if(row.type === 'dmg') v[row.key] = row.fixed ? 0 : Math.max(0, (+row.cnt || 0) * (attackNatural === 20 ? 2 : 1));
      else if(row.type === 'heal' || row.type === 'temp' || row.type === 'sleep') v[row.key] = row.fixed ? 0 : Math.max(0, +row.cnt || 0);
      else if(row.natural){ v[row.key] = 10; if(row.adv) v[row.key + '_2'] = 10; }
      else v[row.key] = row.cnt ? +row.cnt : null;
    });
    return v;
  };
  let attackCases = 0, saveCases = 0;
  const verify = (label, spec) => {
    const hasAttack = spec.rows.some(r => r.type === 'atk');
    const hasSave = spec.rows.some(r => r.type === 'save');
    const hasDamage = spec.rows.some(r => r.type === 'dmg');
    if(hasAttack){
      const out = e.resolveOutcome(spec, valuesFor(spec, 1, 20), {});
      assert.equal(out.hit, false, `${label}: натуральная 1 должна быть промахом`);
      if(hasDamage) assert.equal(out.dmgTotal, 0, `${label}: промах провел урон`);
      assert.equal(out.effectAllowed, false, `${label}: промах разрешил длительный эффект`);
      attackCases++;
    }
    if(hasSave && !spec.rows.some(r => r.type === 'threshold')){
      const out = e.resolveOutcome(spec, valuesFor(spec, 20, 20), {});
      assert.equal(out.saveOk, true, `${label}: сильная цель не прошла контрольный спасбросок`);
      assert.equal(out.effectAllowed, false, `${label}: успешный спасбросок разрешил длительный эффект`);
      (out.damageParts || []).forEach(part => {
        if(part.saveMode === 'zero') assert.equal(part.total, 0, `${label}: отменяемый компонент пережил спасбросок`);
        if(part.saveMode === 'half') assert.ok(part.total <= Math.floor(part.raw / 2), `${label}: половинный компонент не уменьшен`);
      });
      saveCases++;
    }
  };

  spells.forEach(rec => verify(`заклинание ${rec.n}`, e.rollSpecOf(rec, {caster, kind: 'spell', slotLvl: +rec.l || 0,
    target: e.targetInfoOf(`foe:${target.id}`), within5: false})));
  abilities.forEach(rec => verify(`способность ${rec.n}`, e.rollSpecOf(rec, {caster, kind: 'ability',
    target: e.targetInfoOf(`foe:${target.id}`), within5: false})));
  foes.forEach(foe => (foe.combatActions || []).forEach(action => verify(`${foe.n}: ${action.n}`,
    e.foeActionSpecOf(foe, action, e.targetInfoOf(`ally:${defender.id}`), {within5: false}))));
  assert.ok(attackCases > 50, `проверено слишком мало атак: ${attackCases}`);
  assert.ok(saveCases > 40, `проверено слишком мало спасбросков: ${saveCases}`);
});

test('парсер различает два вида урона, формулу зелья и фиксированный урон оружия', () => {
  const e = loadEngine();
  const spells = e.seedSpellsDB(), items = e.seedItemsDB();
  const caster = hero('caster', {level: 20, cls: 'Воин', ab: {str: 18, dex: 14, con: 14, int: 10, wis: 10, cha: 10}});
  e.setState({chars: [caster], spells, items});

  const meteor = spells.find(x => x.n === 'Метеоритный дождь');
  const meteorRows = e.rollSpecOf(meteor, {caster, kind: 'spell', slotLvl: 9}).rows.filter(r => r.type === 'dmg');
  assert.deepEqual(plain(meteorRows.map(r => [r.cnt, r.sides, r.dmgType])), [[20, 6, 'огонь'], [20, 6, 'дробящий']]);

  const potion = items.find(x => /^Зелье лечения/.test(x.n));
  assert.equal(e.rollSpecOf(potion, {caster, kind: 'item'}).rows.length, 0,
    'карточка предмета не должна исполнять кости из описания');
  const heal = e.itemUseSpecOf(caster, potion, e.itemUsesOf(potion)[0], {kind: 'ally', known: true, name: caster.name, obj: caster}).rows.find(r => r.type === 'heal');
  assert.deepEqual(plain([heal.cnt, heal.sides, heal.mod]), [2, 4, 2]);

  const blowgun = items.find(x => x.n === 'Духовая трубка');
  const fixed = e.weaponSpecOf(caster, blowgun, {kind: 'none', known: false}, {}).rows.find(r => r.type === 'dmg');
  assert.equal(fixed.fixed, true);
  assert.equal(fixed.mod, 3); // 1 фиксированный + 2 Ловкости
});

