test('Непоколебимая стойкость и зелье последовательно меняют один боевой лист', () => {
  const e = loadEngine();
  const abilities = e.seedAbilitiesDB(), items = e.seedItemsDB();
  const relentless = abilities.find(x => /^Непоколебимая стойкость/.test(x.n));
  const potion = items.find(x => /^Зелье лечения/.test(x.n));
  const target = hero('target', {
    hp: 10, hpMax: 30,
    abilities: [{abilityId: relentless.id, cur: 1}],
    inventory: [{id: 'potion-entry', itemId: potion.id, qty: 1}]
  });
  e.setState({chars: [target], abilities, items});

  const hit = e.applyDamageTo(`ally:${target.id}`, 20, 'рубящий', 'Удар', {});
  assert.equal(hit.relentless, true);
  assert.equal(target.hp, 1);
  assert.equal(target.abilities[0].cur, 0);
  assert.equal(e.effectiveConditions(target).includes('Бессознательный'), false);

  const rolls={
    healTotal: 6, dmgRaw: null, dmgTotal: null, effectAllowed: true, verdict: []
  },valid=['potion-entry',target.id,`ally:${target.id}`,rolls,undefined],beforeInvalid=plain(e.state());
  for(const [label,index,value] of [
    ['entryId',0,'potion-entry'],['casterId',1,target.id],['target',2,`ally:${target.id}`],['useId',4,'drink']
  ])for(const proxy of [false,true]){
    let traps=0,invalid=Object(value);
    if(proxy)invalid=new Proxy(invalid,{
      get(){traps++;throw new Error(`${label} read`);},has(){traps++;throw new Error(`${label} queried`);},
      ownKeys(){traps++;throw new Error(`${label} enumerated`);},getOwnPropertyDescriptor(){traps++;throw new Error(`${label} reflected`);},
      getPrototypeOf(){traps++;throw new Error(`${label} prototype read`);}
    });
    const args=valid.slice();args[index]=invalid;
    assert.equal(e.useItemApply(...args),false,`${label} ${proxy?'Proxy':'boxed'} rejects`);
    assert.equal(traps,0,`${label} Proxy rejects before reflection`);
    assert.deepEqual(plain(e.state()),beforeInvalid,`${label} rejection preserves world and potion resource`);
  }

  assert.equal(e.useItemApply(...valid), true, 'omitted useId keeps selecting the legacy first item use');
  assert.equal(target.hp, 7);
  assert.equal(target.inventory.length, 0);
});

