test('областное действие A/B/C откатывает поздний сбой, удаляет ghost prompt и после retry показывает реакции FIFO', () => {
  const e=loadEngine(),items=e.seedItemsDB(),abilities=e.seedAbilitiesDB(),classes=e.seedClassesDB(),dragon=e.seedFoesDB().find(f=>f.id==='foe_young_green_dragon'),breath=e.foeActionOf(dragon,'poison_breath');
  const barrierHero=(id,hp)=>{const actor=e.buildTorgar();actor.id=id;actor.name=id;actor.hp=hp;actor.hpMax=50;const pauldron=actor.inventory.find(row=>row.itemId==='it_pauldron_mentor');pauldron.att=true;pauldron.ch={cur:1,max:1};return actor;},
    first=barrierHero('batch-A',10),second=hero('batch-B',{hp:50,hpMax:50}),third=barrierHero('batch-C',10),targets=[first,second,third].map(actor=>`ally:${actor.id}`),
    rolls=Object.fromEntries(targets.map(target=>[target,{dmgRaw:36,dmgTotal:36,dmgType:'яд',damageParts:[{type:'яд',raw:36,total:36}],attackMade:false,saveMade:true,saveOk:false,effectAllowed:true,reactionUses:[],consumeCasterFx:[],consumeTargetFx:[],verdict:[],notes:[]}])) ;
  e.setState({chars:[first,second,third],items,abilities,classes,foes:[dragon],activeCharId:first.id});assert.equal(e.combatStart([{kind:'foe',id:dragon.id,nat:20},{kind:'ally',id:first.id,nat:10},{kind:'ally',id:second.id,nat:9},{kind:'ally',id:third.id,nat:8}],'atomic A/B/C'),true);
  const ctx={kind:'foe',foeId:dragon.id,actionId:breath.id,target:targets[0],primaryTarget:targets[0],combatCost:'action',combatActorKey:`foe:${dragon.id}`,combatCommitted:false};e.setCastContext(ctx);e.setConfirmResults([true,true,true]);
  let secondHp=second.hp;Object.defineProperty(second,'hp',{configurable:true,enumerable:true,get:()=>secondHp,set:()=>{throw new Error('injected late target B failure');}});
  assert.equal(e.foeActionBatchApply(dragon.id,breath.id,targets,rolls),false,'target B failure must reject the whole area source');
  assert.deepEqual([first.hp,second.hp,third.hp],[10,50,10],'A, B and untouched C all restore to the outer checkpoint');assert.equal(e.state().combat.turn.actionsUsed,0);assert.equal(ctx.combatCommitted,false);assert.notEqual(dragon.actionState[breath.id]&&dragon.actionState[breath.id].ready,false);
  assert.equal(e.pendingRollSpec(),null,'the Last Barrier prompt produced by A is not published before Finish');assert.equal(e.rollPromptState().queue.length,0,'rollback discards every buffered prompt');
  Object.defineProperty(second,'hp',{value:secondHp,writable:true,configurable:true,enumerable:true});
  assert.equal(e.foeActionBatchApply(dragon.id,breath.id,targets,rolls),true,e.elementText('saveStatus'));assert.deepEqual([first.hp,second.hp,third.hp],[0,14,0]);assert.equal(e.state().combat.turn.actionsUsed,1);assert.equal(dragon.actionState[breath.id].ready,false);
  assert.match(e.pendingRollSpec().title,/batch-A/,'the first committed prompt stays active');assert.equal(e.rollPromptState().queue.length,1,'the second committed prompt waits instead of overwriting the first');
  e.rollCancel();assert.match(e.pendingRollSpec().title,/batch-C/,'FIFO publishes C only after A is resolved');e.rollCancel();assert.equal(e.pendingRollSpec(),null);assert.equal(e.rollPromptState().queue.length,0);
});

test('мультиатака монстра соблюдает порядок и условие попадания, сохраняя отдельные цели и d20', () => {
  const e = loadEngine();
  const target = hero('target');
  const owlbear = e.seedFoesDB().find(f => f.id === 'foe_owlbear');
  e.setState({chars: [target], foes: [owlbear]});
  e.combatStart([{kind: 'foe', id: owlbear.id, nat: 20}, {kind: 'ally', id: target.id, nat: 10}], 'Мультиатака');
  assert.equal(e.state().combat.turn.attackMax, 2);
  assert.equal(e.combatFoeAttackAllowed(owlbear, e.foeActionOf(owlbear, 'claws'), 'attack', true), false);
  assert.equal(e.combatFoeAttackAllowed(owlbear, e.foeActionOf(owlbear, 'beak'), 'attack', true), true);
  e.combatSpend('attack', 'Клюв', `foe:${owlbear.id}`);
  e.combatRecordFoeAttack(owlbear, e.foeActionOf(owlbear, 'beak'), `ally:${target.id}`, {hit: true});
  assert.equal(e.combatFoeAttackAllowed(owlbear, e.foeActionOf(owlbear, 'claws'), 'attack', true, `ally:${target.id}`), true);

  const e2 = loadEngine(), victim = hero('victim'), grick = e2.seedFoesDB().find(f => f.id === 'foe_grick');
  e2.setState({chars: [victim], foes: [grick]});
  e2.combatStart([{kind: 'foe', id: grick.id, nat: 20}, {kind: 'ally', id: victim.id, nat: 10}], 'Условная мультиатака');
  e2.combatSpend('attack', 'Щупальца', `foe:${grick.id}`);
  e2.combatRecordFoeAttack(grick, e2.foeActionOf(grick, 'tentacles'), `ally:${victim.id}`, {hit: false});
  assert.equal(e2.combatFoeAttackAllowed(grick, e2.foeActionOf(grick, 'beak'), 'attack', true, `ally:${victim.id}`), false);
  assert.equal(e2.state().combat.turn.attackMax, 1);
});

test('Парирование главаря расходует реакцию, дает +2 КД на одну входящую атаку и затем снимается', () => {
  const e = loadEngine();
  const sword = {id: 'test_sword', n: 'Тестовый меч', type: 'weapon', tags: ['melee'], dmg: '1d8', dmgType: 'рубящий'};
  const attacker = hero('attacker', {inventory: [{id: 'sword_entry', itemId: sword.id, qty: 1}], equipment: {MAIN_HAND: 'sword_entry'}});
  const captain = e.seedFoesDB().find(f => f.id === 'foe_bandit_captain');
  e.setState({chars: [attacker], items: [sword], foes: [captain]});
  e.combatStart([{kind: 'ally', id: attacker.id, nat: 20}, {kind: 'foe', id: captain.id, nat: 10}], 'Парирование главаря');
  e.combatFocus(`foe:${captain.id}`);

  assert.equal(e.combatFoeAction('parry'), true);
  assert.equal(e.targetInfoOf(`foe:${captain.id}`).ac, 17);
  assert.equal(e.state().combat.order.find(x => x.id === captain.id).reactionUsed, true);

  const confirmed=productionWeaponConfirmation(e,attacker,'sword_entry',`foe:${captain.id}`,{atk:13},{within5:true,combatCost:'attack',combatActorKey:`ally:${attacker.id}`}),spec=confirmed.spec,rolls=confirmed.rolls;
  assert.equal(rolls.hit, false, 'итог 16 должен промахнуться по КД 17');
  assert.equal(e.weaponAttackApply('sword_entry', attacker.id, `foe:${captain.id}`, rolls), true);
  assert.equal(e.targetInfoOf(`foe:${captain.id}`).ac, 15);
});

