  e.setElementValue('castTarget', `foe:${orc.id}`); e.setElementValue('castWeapon', '0'); e.castConfirm();
  e.setElementValue('cf_atk', '1'); e.setElementValue('cf_wdmg', '5'); e.setElementValue('cf_save', '1');
