  const caster = hero('fighter', {cls: 'Воин', inventory: [{id: 'weapon', itemId: weapon.id, qty: 1}, {id: 'shield', itemId: shield.id, qty: 1}],
    equipment: {MAIN_HAND: 'weapon', OFF_HAND: 'shield'}});
