test('регрессия уникальных предметов: реакции на спасбросок планируются inline и коммитятся только с d20', () => {
  const e = loadEngine(), items = e.seedItemsDB(), spells = e.seedSpellsDB(), abilities = e.seedAbilitiesDB(), classes = e.seedClassesDB(), foes = e.seedFoesDB();
  const legerem = e.buildLegerem(), caster = hero('inline-fear-caster', {cls: 'Волшебник', level: 5,
    ab: {str: 10, dex: 10, con: 10, int: 18, wis: 10, cha: 10}}), foe = foes.find(x => x.id === 'foe_eye_warden');
  const seal = legerem.inventory.find(x => x.itemId === 'it_korlinn_seal'), fear = spells.find(x => x.n === 'Страх');
  e.setState({chars: [legerem, caster], items, spells, abilities, classes, foes: [foe], activeCharId: legerem.id});
  e.combatStart([{kind: 'foe', id: foe.id, nat: 20}, {kind: 'ally', id: legerem.id, nat: 10}], 'Inline-печать');
  const sealItem = items.find(x => x.id === seal.itemId), directAction = e.itemActions(legerem, seal, sealItem).find(x => x.label === 'Стойкость рода');
  assert.ok(directAction); assert.match(directAction.fn, /itemTriggerExplain/); assert.doesNotMatch(directAction.fn, /itemCastFx/,
    'реакцию на спасбросок нельзя заранее вооружить обычной кнопкой предмета');
  assert.equal(e.useItemApply(seal.id, legerem.id, `ally:${legerem.id}`, null, 'martial_resolve'), false,
    'прямой runtime-вызов в бою тоже не обходит inline-событие и расход реакции');
  assert.equal(seal.sealResolveUsed, undefined);
  assert.equal(e.state().combat.order.find(row => row.id === legerem.id).reactionUsed, false);
  const ti = e.targetInfoOf(`ally:${legerem.id}`), spec = e.rollSpecOf(fear, {caster, kind: 'spell', slotLvl: 3, target: ti});
  const sealChoice = e.inlineSaveItemCandidates(spec, ti).find(x => x.kind === 'sealResolve');
  assert.ok(sealChoice, 'подходящая магическая угроза предлагает печать до спасброска');
  const selected = e.applyInlineSaveDecision(spec, ti, sealChoice);
  assert.equal(selected.ok, true); assert.equal(spec.rows.find(r => r.key === 'save').adv, 1);
  assert.equal(seal.sealResolveUsed, undefined, 'выбор до d20 еще не тратит ресурс');
  assert.equal(e.state().combat.order.find(row => row.id === legerem.id).reactionUsed, false);
  const p = selected.plan;
  e.applyRollsToTarget(`ally:${legerem.id}`, {reactionUses: [{kind: 'item-save', actorKey: p.actorKey, entryId: p.entryId,
    itemId: p.itemId, useId: p.useId, label: p.label, eventKey: p.eventKey}], notes: []}, 'inline save d20');
  assert.equal(seal.sealResolveUsed, true); assert.equal(e.state().combat.order.find(row => row.id === legerem.id).reactionUsed, true,
    'подтвержденный save event атомарно тратит reaction и независимый short-rest ресурс');

  e.refreshShortRestResources(legerem); e.state().combat.order.find(row => row.id === legerem.id).reactionUsed = false;
  const fresh = e.rollSpecOf(fear, {caster, kind: 'spell', slotLvl: 3, target: ti}), freshChoice = e.inlineSaveItemCandidates(fresh, ti).find(x => x.kind === 'sealResolve');
  assert.ok(freshChoice); const stale = e.applyInlineSaveDecision(fresh, ti, freshChoice);
  Object.keys(legerem.equipment).forEach(slot => { if (legerem.equipment[slot] === seal.id) delete legerem.equipment[slot]; });
  assert.equal(e.inlineSavePlanCheck(stale.plan).ok, false, 'снятая между планом и d20 печать делает план stale без расхода');
});

test('облачная синхронизация отличает штатную базу и безопасно добавляет ID-токен', () => {
  const html=fs.readFileSync(new URL('../index.html',import.meta.url),'utf8');
  assert.doesNotMatch(html,/"\.read"\s*:\s*true/);
  assert.doesNotMatch(html,/"\.write"\s*:\s*true/);
  assert.match(html,/firebase-auth\.js/);
  assert.match(html,/getIdToken/);
  const e=loadEngine();
  e.setSyncConfig({
    url:'https://best-dnd-campaign-ever-default-rtdb.firebaseio.com/',
    room:'SpeakFriendAndEnter2026',
    on:true
  });
  assert.equal(e.syncNeedsOwnerAuth(),true);
  assert.equal(
    e.syncUrlWithAuth('https://example.firebaseio.com/world.json','token +/='),
    'https://example.firebaseio.com/world.json?auth=token%20%2B%2F%3D'
  );
  assert.equal(
    e.syncUrlWithAuth('https://example.firebaseio.com/world.json?print=silent','abc'),
    'https://example.firebaseio.com/world.json?print=silent&auth=abc'
  );
  e.setSyncConfig({url:'https://another-project.firebaseio.com',room:'main',on:true});
  assert.equal(e.syncNeedsOwnerAuth(),false);
});

test('BG3 loader: pinned Standard version and concurrent shard hydration are deterministic', async () => {
  const version='bg3-111-v1', commonId='bg3:item:rt:00000000-0000-0000-0000-000000000001';
  const manifest={catalogVersion:version,contracts:{itemSchemaVersion:6},source:{profiles:{standard:{}}},
    entrypoints:{searchIndex:'search-index.json'}};
  const index={catalogVersion:version,count:1,items:[
    {id:commonId,names:{ru:'Общий',en:'Common'},type:'equipment',category:'misc',classification:'playable',tags:['bg3'],
      shard:'aa',rarity:'обычный'},
  ]};
  const shard={catalogVersion:version,shard:'aa',count:1,items:[
    {id:commonId,schemaVersion:6,rarity:'обычный',source:{profiles:['standard']}},
  ]};
  const calls=[];
  const fetcher=async (url,opts)=>{
    calls.push({url,cache:opts&&opts.cache});
    const body=url.endsWith('/manifest.json')?manifest:url.endsWith('/search-index.json')?index:url.endsWith('/items/aa.json')?shard:null;
    return body?{ok:true,json:async()=>plain(body)}:{ok:false,status:404,json:async()=>({})};
  };
  const e=loadEngine(()=>0,fetcher);
  assert.equal(e.bg3CatalogUseRefs([{id:'bg3',version,profile:'honour'}]),false,
    'a direct legacy profile activation is rejected');
  assert.equal(e.bg3CatalogUseRefs([{id:'bg3',version,profile:'standard'}]),true);
  await e.bg3CatalogEnsureIndex();
  assert.equal(calls.some(call=>call.url==='data/bg3/current.json'),false,'a pinned save must not depend on mutable current.json');
  assert.equal(e.bg3CatalogSearch('',{}).length,1);
  const [first,second]=await Promise.all([e.bg3CatalogHydrate([commonId]),e.bg3CatalogHydrate([commonId])]);
  assert.equal(first[0].rarity,'обычный'); assert.equal(second[0].rarity,'обычный');
  assert.equal(calls.filter(call=>call.url.endsWith('/items/aa.json')).length,1,'same-shard fetches share one promise');
  assert.equal(e.bg3CatalogUseRefs([]),true,'an authoritative empty campaign clears the previous pin');
  assert.equal(e.bg3CatalogSnapshot().preferredVersion,''); assert.equal(e.bg3CatalogSnapshot().index,null);
  assert.equal(e.bg3CatalogUseRefs([{id:'bg3',version:'invalid',profile:'standard'}]),false);
  assert.match(e.bg3CatalogSnapshot().refError,/Некорректная ссылка/);
});
test('BG3 loader: a fresh pointer is Standard-only and stale version work cannot overwrite a new pin', async () => {
  const makeManifest=version=>({catalogVersion:version,contracts:{itemSchemaVersion:6},source:{profiles:{standard:{}}},
    entrypoints:{searchIndex:'search-index.json'}});
  const makeIndex=version=>({catalogVersion:version,count:0,items:[]});
  const pointerCalls=[];
  const pointerEngine=loadEngine(()=>0,async (url,opts)=>{
    pointerCalls.push({url,cache:opts&&opts.cache});
    const version='bg3-222-v1',body=url==='data/bg3/current.json'?{catalogVersion:version,defaultRulesProfile:'honour'}
      :url.endsWith('/manifest.json')?makeManifest(version):makeIndex(version);
    return {ok:true,json:async()=>plain(body)};
  });
  await pointerEngine.bg3CatalogEnsureIndex();
  assert.deepEqual(pointerCalls.find(call=>call.url==='data/bg3/current.json'),{url:'data/bg3/current.json',cache:'no-cache'});
  assert.equal(pointerEngine.bg3CatalogSnapshot().preferredProfile,'standard','a fresh unpinned game ignores an Honour pointer default');

  const versionA='bg3-333-v1',versionB='bg3-444-v1';
  let releaseA;
  const deferredA=new Promise(resolve=>{releaseA=resolve;});
  const raceEngine=loadEngine(()=>0,async url=>{
    if(url===`data/bg3/${versionA}/manifest.json`)return deferredA;
    const version=url.includes(versionB)?versionB:versionA;
    const body=url.endsWith('/manifest.json')?makeManifest(version):makeIndex(version);
    return {ok:true,json:async()=>plain(body)};
  });
  raceEngine.bg3CatalogUseRefs([{id:'bg3',version:versionA,profile:'standard'}]);
  const oldLoad=raceEngine.bg3CatalogEnsureIndex();
  raceEngine.bg3CatalogUseRefs([{id:'bg3',version:versionB,profile:'standard'}]);
  await raceEngine.bg3CatalogEnsureIndex();
  releaseA({ok:true,json:async()=>plain(makeManifest(versionA))});
  await assert.rejects(oldLoad,/отменена сменой версии или профиля/);
  const state=raceEngine.bg3CatalogSnapshot();
  assert.equal(state.current.catalogVersion,versionB); assert.equal(state.preferredProfile,'standard'); assert.equal(state.error,'');
});

test('BG3 loader: a retryable shard failure does not hide the ready search index', async () => {
  const version='bg3-555-v1',id='bg3:item:rt:00000000-0000-0000-0000-000000000005';
  const manifest={catalogVersion:version,contracts:{itemSchemaVersion:6},source:{profiles:{standard:{}}},
    entrypoints:{searchIndex:'search-index.json'}};
  const index={catalogVersion:version,count:1,items:[{id,names:{ru:'Пять',en:'Five'},type:'equipment',category:'misc',classification:'playable',
    tags:['bg3'],shard:'aa',rarity:'обычный'}]};
  const shard={catalogVersion:version,shard:'aa',count:1,items:[{id,schemaVersion:6,source:{profiles:['standard']}}]};
  const malformedShard={catalogVersion:version,shard:'aa',count:0,items:[]};
  let shardAttempts=0;
  const e=loadEngine(()=>0,async url=>{
    if(url.endsWith('/manifest.json'))return {ok:true,json:async()=>plain(manifest)};
    if(url.endsWith('/search-index.json'))return {ok:true,json:async()=>plain(index)};
    if(url.endsWith('/items/aa.json')&&++shardAttempts===1)return {ok:false,status:503,json:async()=>({})};
    if(url.endsWith('/items/aa.json')&&shardAttempts===2)return {ok:true,json:async()=>plain(malformedShard)};
    return {ok:true,json:async()=>plain(shard)};
  });
  e.bg3CatalogUseRefs([{id:'bg3',version,profile:'standard'}]);
  await e.bg3CatalogEnsureIndex();
  await assert.rejects(e.bg3CatalogLoadShard('aa'),/HTTP 503/);
  assert.equal(e.bg3CatalogSnapshot().error,''); assert.equal(e.bg3CatalogSnapshot().index.count,1);
  assert.equal(e.bg3CatalogSnapshot().shardErrors.length,1);
  await assert.rejects(e.bg3CatalogHydrate([id]),/shard не содержит itemId/);
  assert.equal(e.bg3CatalogSnapshot().shardCount,0,'a shape-valid shard missing its indexed ID is evicted');
  assert.equal((await e.bg3CatalogHydrate([id]))[0].id,id,'the evicted shard is fetched again');
  assert.equal(e.bg3CatalogSnapshot().shardErrors.length,0);
});

test('BG3 immutable catalog v2 refs require and persist an exact manifest SHA-256 pin', () => {
  const e=loadEngine(),sha='a'.repeat(64);
  assert.equal(e.bg3CatalogUseRefs([{id:'bg3',version:'bg3-24532579-v2',profile:'standard'}]),false);
  assert.equal(e.bg3CatalogUseRefs([{id:'bg3',version:'bg3-24532579-v2',profile:'standard',manifestSha256:'bad'}]),false);
  assert.equal(e.bg3CatalogUseRefs([{id:'bg3',version:'bg3-24532579-v2',profile:'standard',manifestSha256:sha}]),true);
  assert.deepEqual(plain(e.bg3CatalogRefs()),[{id:'bg3',version:'bg3-24532579-v2',profile:'standard',manifestSha256:sha}]);
  assert.equal(e.bg3CatalogSelectProfile('honour'),false,'Honour mode is not selectable in the game');
  assert.deepEqual(plain(e.bg3CatalogRefs()),[{id:'bg3',version:'bg3-24532579-v2',profile:'standard',manifestSha256:sha}],
    'rejected profile switches preserve the immutable Standard pin');
  assert.equal(e.bg3CatalogUseRefs([{id:'bg3',version:'bg3-24532579-v1',profile:'standard'}]),true,'legacy v1 remains readable at its immutable URL');
});

test('BG3 fresh v2 bootstrap rejects a mutable pointer without a manifest SHA-256', async () => {
  let manifestRequests=0;
  const e=loadEngine(()=>0,async url=>{
    if(url.endsWith('/current.json'))return {ok:true,json:async()=>({catalogVersion:'bg3-24532579-v2',defaultRulesProfile:'standard'})};
    if(url.endsWith('/manifest.json'))manifestRequests++;
    return {ok:true,json:async()=>({})};
  });
  await assert.rejects(e.bg3CatalogEnsureIndex(),/pointer is missing manifest SHA-256/);
  assert.equal(manifestRequests,0,'an unpinned immutable manifest is never fetched');
});

