test('BG3 saved v1 catalog upgrades only by an explicit GM v2 plan and persists the exact immutable ref', async () => {
  const fixture=bg3CatalogUpgradeFixture(),{e}=await bg3CatalogUpgradeEngine(fixture),before=plain(e.bg3CatalogRefs());
  const gateHtml=e.renderWorld().itemsdb;assert.match(gateHtml,/Нужно обновить базу кампании/,'an available retired catalog is still gated because production publishes only v10');assert.doesNotMatch(gateHtml,/найдено/,'the retired local catalog cannot masquerade as the current unified release');
  const unconfirmed=await e.bg3CatalogUpgradePlanFor({});assert.equal(unconfirmed.ok,false);assert.match(unconfirmed.reason,/мастер/);assert.deepEqual(plain(e.bg3CatalogRefs()),before);
  const plan=await e.bg3CatalogUpgradePlanFor({gmConfirmed:true});assert.equal(plan.ok,true,plan.reason);assert.deepEqual(plain(plan.referencedIds),[fixture.itemA,fixture.itemB]);
  assert.deepEqual(plain(e.bg3CatalogRefs()),before,'preflight hydrates the candidate release without replacing the saved v1 ref');
  assert.equal(fixture.requests.filter(row=>row.url==='data/bg3/current.json').every(row=>row.cache==='no-cache'),true,'the mutable publication pointer is never cached');
  const done=await e.bg3CatalogUpgradeCommit(plan);assert.equal(done.ok,true,done.reason);
  assert.deepEqual(plain(e.bg3CatalogRefs()),[{id:'bg3',version:fixture.version,profile:'standard',manifestSha256:fixture.manifestSha256}]);
  assert.deepEqual(new Set(e.bg3CatalogSnapshot().itemIds),new Set([fixture.itemA,fixture.itemB]),'every referenced and already-hydrated exact item is installed before the ref changes');
  assert.equal((await e.bg3CatalogHydrate([fixture.itemA,fixture.itemB])).length,2,'the committed release reuses its fully verified shards');
  assert.equal(done.learnedSpellCount,1);assert.equal(e.state().chars[0].bg3LearnedSpells[0].catalogVersion,fixture.version);
  assert.equal(e.state().chars[0].bg3LearnedSpells[0].manifestSha256,fixture.manifestSha256,'saved learned spell is atomically repinned only after exact semantic verification');
  assert.equal(e.state().chars[0].bg3LearnedSpells[0].artifact,fixture.spellArtifact,'the exact rule artifact is repinned even when its shard path changed');
  assert.deepEqual(plain(e.state().chars[0].bg3LearnedSpells[0].learnedFrom),{itemId:fixture.itemA,entryId:'upgrade-a',useId:fixture.useId,
    rootProgramId:fixture.rootProgramId,rootArtifact:fixture.rootArtifact},'the historical source entry is preserved while every executable A33 binding is repinned');
  await e.runScheduledSave();assert.deepEqual(JSON.parse(e.storedValue('dndworld2:catalog-refs')),plain(e.bg3CatalogRefs()),'the existing scheduled local/cloud save path owns the new ref');
  const replay=await e.bg3CatalogUpgradeCommit(plan);assert.equal(replay.ok,false);assert.equal(replay.replay,true);assert.deepEqual(plain(e.bg3CatalogRefs()),plain(JSON.parse(e.storedValue('dndworld2:catalog-refs'))));
  const html=fs.readFileSync(new URL('../index.html',import.meta.url),'utf8');assert.match(html,/Проверить и обновить/);assert.doesNotMatch(html,/Мастеру: проверить и обновить/);assert.match(html,/Мир изменится только после явного подтверждения/);
  assert.match(html,/bg3CatalogUpgradeVersionIdentity\(bg3Catalog\.preferredVersion\)/,'the GM upgrade control is offered for every pinned catalog revision, not only v1');
});

test('BG3 same-version reissue bypasses stale HTTP bytes only after full SHA and world-reference verification', async () => {
  const version='bg3-24532579-v10',fixture=bg3CatalogUpgradeFixture({oldVersion:version,version,sameVersionReissue:true}),
    {e}=await bg3CatalogUpgradeEngine(fixture),before=plain(e.state()),done=await e.bg3CatalogMigrateSameVersionReissue();
  assert.equal(done.ok,true,done.reason);assert.equal(done.changed,true);assert.notEqual(fixture.oldManifestSha256,fixture.manifestSha256);
  assert.deepEqual(plain(e.bg3CatalogRefs()),[{id:'bg3',version,profile:'standard',manifestSha256:fixture.manifestSha256}]);
  assert.deepEqual(plain(e.state().chars[0].inventory),before.chars[0].inventory,'inventory identity and quantities survive the release repair');
  const learned=e.state().chars[0].bg3LearnedSpells[0];assert.equal(learned.catalogVersion,version);assert.equal(learned.manifestSha256,fixture.manifestSha256,'learned-spell execution pins move only after exact semantic preflight');
  assert.equal((await e.bg3CatalogHydrate([fixture.itemA,fixture.itemB])).length,2);
  for(const suffix of ['/manifest.json','/search-index.json','/items/aa.json']){
    const caches=fixture.requests.filter(row=>row.url.endsWith(suffix)).map(row=>row.cache);assert.ok(caches.includes('force-cache'),suffix+' starts with the saved cache');assert.ok(caches.includes('reload'),suffix+' retries past stale bytes only after SHA mismatch');
  }
  await e.runScheduledSave();assert.deepEqual(JSON.parse(e.storedValue('dndworld2:catalog-refs')),plain(e.bg3CatalogRefs()),'the repaired exact pin uses the normal durable world-save path');
  const html=fs.readFileSync(new URL('../index.html',import.meta.url),'utf8');assert.match(html,/const bg3ProfileMigrationNeeded=[^;]+,bg3Reissue=await bg3CatalogMigrateSameVersionReissue\([^)]*\),bg3World=await bg3CatalogHydrateWorld\(\)/,'startup repairs a reissued version before world hydration and carries legacy profile migration evidence');
});

