  const craft=await e.bg3RecipePlanFor(reader,recipeId,selections);assert.equal(craft.ok,true,craft.reason);const done=await e.bg3RecipeCommit(craft);assert.equal(done.ok,true);assert.equal(e.inventoryItemQty(reader,acorn),2);assert.equal(e.inventoryItemQty(reader,earth),2);assert.equal(e.inventoryItemQty(reader,resultId),1);
  const replay=await e.bg3RecipeCommit(craft);assert.equal(replay.ok,false);assert.equal(e.inventoryItemQty(reader,acorn),2);assert.equal(e.inventoryItemQty(reader,earth),2);assert.equal(e.inventoryItemQty(reader,resultId),1);
  for(const [label,mutate] of [['missing evidence',copy=>{delete copy.accessEvidence;}],['tampered A30',copy=>{copy.accessEvidence[0].actionType30.attributes.RecipeID='OTHER';}],['missing pair policy',copy=>{delete copy.records[1].accessPolicy;}]]){
    const copy=plain(payload);mutate(copy);assert.throws(()=>e.bg3NormalizeRecipes(copy),/accessPolicy|evidence|A11\+A30/,label);}
  const duplicate=plain(payload);duplicate.accessEvidence.push(plain(duplicate.accessEvidence[0]));duplicate.accessPolicyContract.counts.exactFormulaRequired=2;duplicate.accessPolicyContract.counts.evidence=2;duplicate.accessPolicyContract.counts.discoverableSourceUnrestricted=0;duplicate.accessPolicyContract.signature.sha256=sha256Canonical(duplicate.accessEvidence);duplicate.records[2].accessPolicy={...duplicate.records[0].accessPolicy,evidenceIndex:1};duplicate.records[3].accessPolicy=plain(duplicate.records[2].accessPolicy);
