test('BG3 TreasureTable: loot is created only from an explicit player/GM selection', async () => {
  const version='bg3-777-v1',itemId='bg3:item:rt:00000000-0000-0000-0000-000000000071';
  const manifest={catalogVersion:version,contracts:{itemSchemaVersion:6},source:{profiles:{standard:{}}},
    entrypoints:{searchIndex:'search-index.json',recipes:'recipes.json',treasureTables:'treasure-tables.json'}},
    row={id:itemId,statsId:'LOOT_EXACT',names:{ru:'Явный трофей'},type:'equipment',category:'misc',classification:'playable',tags:['bg3'],rarity:'обычный',shard:'aa'},
    index={catalogVersion:version,count:1,items:[row]},shard={catalogVersion:version,shard:'aa',count:1,items:[{id:itemId,n:'Явный трофей',schemaVersion:6,source:{profiles:['standard']}}]},
    recipes={schemaVersion:'bg3-item-combos/1',catalogVersion:version,executionContract:BG3_RECIPE_RUNTIME,records:[],comboCategories:{},counts:{records:0,combinations:0}},treasure={schemaVersion:'bg3-treasure/1',catalogVersion:version,executionContract:BG3_TREASURE_RUNTIME,directStats:{LOOT_EXACT:['TEST_LOOT']},
      objectCategories:{},counts:{definitions:1,directStats:1},definitions:[{id:'bg3:treasure:test-loot',name:'TEST_LOOT',module:'SharedDev',source:'test',line:1,subtables:[{rolls:'1,1',dropCount:{mode:'weighted',raw:'1,1',amount:null,options:[{amount:1,weight:1}],valid:true},entries:[
        {ref:'I_LOOT_EXACT',weights:['1','0','0'],frequency:1,line:2,kind:'stats',statsId:'LOOT_EXACT'}]}]}]};
  const e=loadEngine(()=>{throw new Error('TreasureTable must not call Math.random');},async url=>{
    const body=url.endsWith('/manifest.json')?manifest:url.endsWith('/search-index.json')?index:url.endsWith('/treasure-tables.json')?treasure:
      url.endsWith('/recipes.json')?recipes:url.endsWith('/items/aa.json')?shard:null;
    return body?{ok:true,json:async()=>plain(body)}:{ok:false,status:404,json:async()=>({})};
  });
  const recipient=hero('loot-recipient',{level:1,inventory:[]});e.setState({chars:[recipient],items:[]});e.bg3CatalogUseRefs([{id:'bg3',version,profile:'standard'}]);
  const asset=await e.bg3CatalogEnsureAsset('treasure'),table=asset.tables[0];assert.equal(e.bg3TreasureSearch('явный трофей').length,1,'поиск добычи использует игровое название предмета');for(const technicalQuery of ['test_loot','SharedDev','LOOT_EXACT','I_LOOT_EXACT'])assert.equal(e.bg3TreasureSearch(technicalQuery).length,0,'treasure source field is not a user filter: '+technicalQuery);assert.equal(e.bg3TreasureUserTableCount(asset),1);assert.match(e.bg3RuntimeTabsHTML(),/Таблицы добычи · 1/,'вкладка показывает число пользовательских таблиц, а не исходных записей');assert.equal(e.bg3TreasureSearch(itemId).length,0,'первый relation-query не разворачивает все таблицы синхронно');await e.bg3TreasureRelationsEnsure(asset);assert.deepEqual(plain(e.bg3TreasureSearch(itemId).map(row=>row.id)),[table.id]);for(const technicalQuery of ['test_loot','SharedDev','LOOT_EXACT','I_LOOT_EXACT'])assert.equal(e.bg3TreasureSearch(technicalQuery).length,0,'ready relations do not add raw treasure fields: '+technicalQuery);const panel=e.bg3TreasureTestPanelHTML('',table.id);assert.doesNotMatch(panel,/TEST_LOOT|SharedDev|LOOT_EXACT|I_LOOT_EXACT|DropCount/i,'treasure controls expose only display names and localized odds');const emptyPanel=e.bg3TreasureTestPanelHTML('нет такой таблицы',table.id);assert.match(emptyPanel,/Таблицы не найдены/);assert.doesNotMatch(emptyPanel,/DropCount 1,1/,'фильтр не оставляет stale detail ранее открытой таблицы');
  const rarityBypass=await e.bg3TreasurePlanFor(recipient,table.id,{rarity:'Divine',subtableIndex:0,entryIndex:0,itemId,qty:1});
  assert.equal(rarityBypass.ok,false);assert.match(rarityBypass.reason,/не принимает произвольную rarity/);
  const resultRarityBypass=await e.bg3TreasurePlanFor(recipient,table.id,{subtableIndex:0,dropCountRoll:1,results:[{entryIndex:0,itemId,rarity:'Divine'}]});
  assert.equal(resultRarityBypass.ok,false);assert.equal(resultRarityBypass.manual,true);assert.match(resultRarityBypass.reason,/arbitrary rarity/);
  const implicit=await e.bg3TreasurePlanFor(recipient,table.id,{subtableIndex:0,entryIndex:0,qty:1});
  assert.equal(implicit.ok,false);assert.match(implicit.reason,/явно (?:выбран|введ)/);assert.equal(recipient.inventory.length,0);
  const plan=await e.bg3TreasurePlanFor(recipient,table.id,{subtableIndex:0,entryIndex:0,itemId,qty:1});assert.equal(plan.ok,true);
  assert.equal(recipient.inventory.length,0,'preflight does not create loot');const done=await e.bg3TreasureCommit(plan);
  assert.equal(done.ok,true);assert.equal(e.inventoryItemQty(recipient,itemId),1);
  const replay=await e.bg3TreasureCommit(plan);assert.equal(replay.ok,false);assert.equal(replay.stale,true);
  assert.equal(e.inventoryItemQty(recipient,itemId),1,'one explicit selection can be committed only once');
});

