  const forcePlan=await e.bg3TreasurePlanFor(recipient,force.id,{level:5,subtableIndex:0,results:[{entryIndex:0,itemId:a},{entryIndex:1,itemId:b,categoryRoll:1}]});assert.equal(forcePlan.ok,true);
  assert.equal(forcePlan.evidence.some(row=>row.kind==='subtable'&&row.evidence.some(inner=>inner.kind==='category-roll'&&inner.forcedLevelFallback)),true,'forced DropCount falls back past item level restrictions only when necessary');
  const forceDone=await e.bg3TreasureCommit(forcePlan);assert.equal(forceDone.ok,true);assert.equal(e.inventoryItemQty(recipient,a),2);assert.equal(e.inventoryItemQty(recipient,b),1);
