  assert.equal(e.bg3CatalogUseRefs([{id:'bg3',version:fixture.version,profile:fixture.profile}]),true);await e.bg3CatalogEnsureIndex();const [item]=await e.bg3CatalogHydrate([fixture.itemId]),use=e.itemUseOf(item,fixture.useId),
    compiled=e.bg3RuleProgramCompile(use,fixture.root,[]);assert.equal(compiled.ok,true,e.bg3RuleProgramReport(compiled));e.bg3RuleProgramInstall(use,compiled);
  const ready=await e.bg3BookPrepareProgram(e.bg3RuleProgramPlanOf(use),actor);assert.equal(ready.ok,true,ready.reason);const entry=actor.inventory[0],context=e.bg3StoryCausalItemContext(actor,entry,item,use,'inventory-read');
