test('BG3 status lifecycle unknown aura, passive carrier and instant persistent semantics fail closed before item commit', () => {
  const cases = [
    ['aura', {AuraRadius: '3', AuraStatuses: 'TEST_AURA'}, [{field: 'Boosts', role: 'modifiers', bytecode: [{op: 'modifyArmorClass', executable: true, amount: {kind: 'integer', value: 1}}]}], 2, /aura-spatial-runtime-required/],
    ['passive', {Passives: 'AbilityDeterioration_Strength'}, [{field: 'Boosts', role: 'modifiers', bytecode: [{op: 'modifyArmorClass', executable: true, amount: {kind: 'integer', value: 1}}]}], -1, /passive-carrier-runtime-required/],
    ['instant-tick', {TickType: 'EndTurn'}, [{field: 'TickFunctors', role: 'on-tick', bytecode: [{op: 'dealDamage', executable: true,
      amount: {kind: 'dice', count: 1, sides: 4, modifier: 0}, damageType: {kind: 'symbol', value: 'Slashing'}, target: {kind: 'symbol', value: 'TARGET'}}]}], 0, /instant-status-has-persistent-semantics/],
  ];
  for (const [name, properties, fields, duration, reason] of cases) {const e = loadEngine(), artifact = 'rules/statuses/aa.json', action = bg3TestAction(`status-${name}`, 'bg3RuleProgram', {target: 'self'}),
      built = bg3StatusProgram(action, artifact, `STATUS_${name.toUpperCase()}`, properties, fields, {duration}), item = bg3TestItem(`blocked-${name}`, [action]),
      actor = hero(`blocked-${name}`, {inventory: [{id: `entry-${name}`, itemId: item.id, qty: 1}]}); e.setState({chars: [actor], items: [item]});
    const plan = e.bg3RuleProgramCompile(action, built.root, [{program: built.program, artifact}]);
    if (name === 'instant-tick') {assert.equal(plan.ok, true, e.bg3RuleProgramReport(plan)); e.bg3RuleProgramInstall(action, plan); assert.equal(e.useItemApply(`entry-${name}`, actor.id, `ally:${actor.id}`, null, action.id), false);}
    else {assert.equal(plan.ok, false); assert.match(e.bg3RuleProgramReport(plan), reason); e.bg3RuleProgramInstall(action, plan); assert.equal(e.useItemApply(`entry-${name}`, actor.id, `ally:${actor.id}`, null, action.id), false);}
    assert.equal(actor.inventory[0].qty, 1); assert.equal(actor.activeFx.length, 0);
  }
});

