  assert.equal(delegatedOp.when.condition.name, 'WieldingWeapon', 'the source weapon gate remains attached to its exact consequence');
  const prepared = await e.bg3LifecycleEquipmentBindingsPrepare(delegated.equipmentLifecycleBindings); assert.equal(prepared.ok, true, prepared.reason);
