test('BG3 recipe item actions route only through exact recipe preflight and unlock atomically', async () => {
  const version = 'bg3-891-v1', bookId = 'bg3:item:rt:00000000-0000-0000-0000-000000000091';
  const unlock = {id: 'unlock', label: 'Изучить точный рецепт', cost: 'object', target: 'object', consume: {kind: 'none', amount: 0},
    handler: 'bg3RecipeProgram', program: {id: 'root-unlock', mode: 'typed', commitPolicy: 'item-action-contract-once',
      special: {kind: 'bg3RecipeUnlock', recipeId: 'TEST_UNLOCK'}}, special: {kind: 'bg3RecipeUnlock', recipeId: 'TEST_UNLOCK'}};
  const malformed = {id: 'bad', label: 'Поврежденная ссылка', cost: 'object', target: 'object', consume: {kind: 'none', amount: 0},
    handler: 'bg3RecipeProgram', program: {id: 'root-bad', mode: 'typed', commitPolicy: 'item-action-contract-once', special: {kind: 'bg3Recipe', matchingRecipeIds: []}},
    special: {kind: 'bg3Recipe', matchingRecipeIds: []}};
  const combine = {id: 'combine', label: 'Объединить точно', cost: 'object', target: 'object', consume: {kind: 'none', amount: 0},
    handler: 'bg3RecipeProgram', program: {id: 'root-combine', mode: 'typed', commitPolicy: 'item-action-contract-once',
      special: {kind: 'bg3Recipe', matchingRecipeIds: ['TEST_UNLOCK']}}, special: {kind: 'bg3Recipe', matchingRecipeIds: ['TEST_UNLOCK']}};
  const book = {id: bookId, n: 'Книга точной формулы', type: 'equipment', slot: null, schemaVersion: 6,
    mechanics: bg3TestMechanics({actions: [unlock, malformed, combine], kind: 'lore'}), source: {profiles: ['standard']}};
  const manifest = {catalogVersion: version, contracts: {itemSchemaVersion: 6}, source: {profiles:{standard:{}}},
    entrypoints: {searchIndex: 'search-index.json', recipes: 'recipes.json'}};
  const index = {catalogVersion: version, count: 1, items: [{id: bookId, names: {ru: book.n}, statsId: 'BOOK_TEST', type: 'equipment', category: 'readable',
    classification: 'playable', tags: ['bg3'], rarity: 'обычный', shard: 'aa'}]};
  const recipes = {schemaVersion: 'bg3-item-combos/1', catalogVersion: version, executionContract: BG3_RECIPE_RUNTIME,
    comboCategories:{Any:{profiles:['standard'],standard:[],itemVariantIds:[]}},counts:{records:2,combinations:1},records: [
    {recordType: 'ItemCombination', name: 'TEST_UNLOCK', module: 'Test', source: 'test', line: 1, data: {'Type 1': 'Category', 'Object 1': 'Any', 'Transform 1': 'None'}, resolvedItemReferences: []},
    {recordType: 'ItemCombinationResult', name: 'TEST_UNLOCK_1', module: 'Test', source: 'test', line: 2, data: {'Result 1': 'TEST_RESULT'}, resolvedItemReferences: []},
  ]};
  const e = loadEngine(() => { throw new Error('recipe bridge must not roll'); }, async url => {
    const body = url.endsWith('/manifest.json') ? manifest : url.endsWith('/search-index.json') ? index : url.endsWith('/recipes.json') ? recipes : null;
    return body ? {ok: true, json: async () => plain(body)} : {ok: false, status: 404, json: async () => ({})};
  });
  e.bg3CatalogUseRefs([{id: 'bg3', version, profile: 'standard'}]);
  await e.bg3CatalogEnsureAsset('recipes');
  const reader = hero('recipe-reader', {knownRecipes: [], inventory: [{id: 'formula-book', itemId: bookId, qty: 1}]});
  e.setState({chars: [reader], items: [book], activeCharId: reader.id});

  const actions = e.itemActions(reader, reader.inventory[0], book);
  for (const label of [unlock.label, malformed.label, combine.label]) {
    const action = actions.find(row => row.label === label);assert.ok(action, label);
    assert.match(action.fn, /^bg3RecipeProgramOpen\(/);assert.doesNotMatch(action.fn, /itemCastFx/);
  }
  const before = plain(reader), bad = await e.bg3RecipeProgramPlanFor(reader, 'formula-book', 'bad', {});
  assert.equal(bad.ok, false);assert.deepEqual(plain(reader), before, 'an empty recipe reference cannot fall through or commit');
  assert.equal(e.useItemApply('formula-book',reader.id,'object',null,'bad'),false,'ordinary item commit rejects every recipe handler');
  assert.deepEqual(plain(reader),before,'the rejected ordinary commit has no resource or recipe mutation');
  const wrong = await e.bg3RecipeProgramPlanFor(reader, 'formula-book', 'combine', {recipeId: 'OTHER_RECIPE'});
  assert.equal(wrong.ok, false);assert.match(wrong.reason, /не связан/);assert.deepEqual(plain(reader), before);

  const plan = await e.bg3RecipeProgramPlanFor(reader, 'formula-book', 'unlock', {}), competingPlan = await e.bg3RecipeProgramPlanFor(reader, 'formula-book', 'unlock', {});
  assert.equal(plan.ok, true);assert.equal(competingPlan.ok, true);assert.deepEqual(reader.knownRecipes, [], 'unlock preflight is read-only');
  const raced = await Promise.all([e.bg3RecipeProgramCommit(plan), e.bg3RecipeProgramCommit(competingPlan)]);
  assert.equal(raced.filter(result => result.ok).length, 1, 'two concurrently confirmed plans can learn the same formula only once');
  assert.equal(raced.filter(result => !result.ok).length, 1);
  assert.deepEqual(reader.knownRecipes, ['bg3:recipe:TEST_UNLOCK']);assert.equal(reader.inventory[0].qty, 1, 'non-consuming book stays in inventory');
  const winningPlan=raced[0].ok?plan:competingPlan,replay = await e.bg3RecipeProgramCommit(winningPlan);assert.equal(replay.ok, false);assert.equal(replay.replay, true);
  assert.deepEqual(reader.knownRecipes, ['bg3:recipe:TEST_UNLOCK'], 'replay cannot duplicate the learned formula');
});

test('BG3 lifecycle gates reconcile derived effects, block partial programs and replay-safe on-hit', async () => {
  const version = 'bg3-892-v1', artifact = 'rules/passives.json';
  const ids = {
    main: 'bg3:item:rt:00000000-0000-0000-0000-000000000092', off: 'bg3:item:rt:00000000-0000-0000-0000-000000000093',
    inventory: 'bg3:item:rt:00000000-0000-0000-0000-000000000094', bad: 'bg3:item:rt:00000000-0000-0000-0000-000000000095',
    grant: 'bg3:item:rt:00000000-0000-0000-0000-000000000096',
  };
  const ref = (id, gate, mode = 'typed', bg3Id = id) => ({id: 'ref-' + id, ruleId: 'rule-' + id, bg3Id, kind: 'passive', sourceField: 'Test', gate,
    programId: id, artifact, mode, executionPolicy: 'preflight-fail-closed'});
  const refs = {
    equip: ref('p-equip', 'equipped'), main: ref('p-main', 'equipped-main-hand'), off: ref('p-off', 'equipped-off-hand'),
    inventory: ref('p-inventory', 'inventory'), bad: ref('p-bad', 'inventory', 'mixed'),
    hit: ref('p-hit', 'on-hit'), hitBad: ref('p-hit-bad', 'on-hit', 'mixed'), grant: ref('p-grant', 'granted-action', 'typed', 'TEST_SOURCE_STATUS'),
  };
  const makeItem = (id, n, lifecyclePrograms, slot = null) => ({id, n, type: slot ? 'weapon' : 'equipment', slot, schemaVersion: 6,
    mechanics: bg3TestMechanics({lifecyclePrograms, kind: slot ? 'weapon' : 'misc'}), source: {profiles: ['standard']}});
  const items = [
    makeItem(ids.main, 'Main lifecycle', [refs.equip, refs.main, refs.hit, refs.hitBad], 'MAIN_HAND'),
    makeItem(ids.off, 'Off lifecycle', [refs.off], 'OFF_HAND'), makeItem(ids.inventory, 'Inventory lifecycle', [refs.inventory]),
    makeItem(ids.bad, 'Blocked lifecycle', [refs.bad]), makeItem(ids.grant, 'Grant lifecycle', [refs.grant]),
  ];
  const plainWeapon = makeItem('it_lifecycle_plain', 'Plain control weapon', [], 'MAIN_HAND');items.push(plainWeapon);
  items[0].dmg = '1d6';items[0].dmgType = 'рубящий';items[0].mechanics.profile.weapon = {ranged: false, thrown: false, ammo: false, ammoType: '', loading: false, reach: false,
    finesse: false, light: true, heavy: false, two: false, versatile: null, magic: true, range: '', special: '',
    damage: {cnt: 1, sides: 6, mod: 0, manual: false, type: 'рубящий'}, damageTraits: {magical: true, silvered: false, adamantine: false}, bonus: 0, category: 'simple', bg3Properties: [], bg3Group: ''};
  plainWeapon.dmg = '1d6';plainWeapon.dmgType = 'рубящий';plainWeapon.mechanics.profile.weapon = plain(items[0].mechanics.profile.weapon);
  const programs = [
    bg3TestProgram('p-equip', [{op: 'modifyArmorClass', executable: true, amount: {kind: 'integer', value: 2}}]),
    bg3TestProgram('p-main', [{op: 'modifyInitiative', executable: true, amount: {kind: 'integer', value: 3}}]),
    bg3TestProgram('p-off', [{op: 'modifyArmorClass', executable: true, amount: {kind: 'integer', value: 1}}]),
    bg3TestProgram('p-inventory', [{op: 'modifyInitiative', executable: true, amount: {kind: 'integer', value: 1}}]),
    bg3TestProgram('p-bad', [{op: 'modifyArmorClass', executable: true, amount: {kind: 'integer', value: 99}}, {op: 'manual', executable: false}], {mode: 'mixed'}),
    bg3TestProgram('p-hit', [{op: 'applyStatus', executable: true, target: {kind: 'symbol', value: 'TARGET'}, status: {kind: 'symbol', value: 'TEST_ON_HIT'},
      parameters: [{kind: 'integer', value: 100}, {kind: 'integer', value: 2}]}], {role: 'consequences'}),
    bg3TestProgram('p-hit-bad', [{op: 'applyStatus', executable: true, target: {kind: 'symbol', value: 'TARGET'}, status: {kind: 'symbol', value: 'FORBIDDEN_PARTIAL'}, parameters: []},
      {op: 'manual', executable: false}], {mode: 'mixed', role: 'consequences'}),
    bg3TestProgram('p-grant', [{op: 'unlockSpell', executable: true, spell: {kind: 'symbol', value: 'Target_TestGranted'}}]),
  ];
  const manifest = {catalogVersion: version, contracts: {itemSchemaVersion: 6}, source: {profiles:{standard:{}}},
    entrypoints: {searchIndex: 'search-index.json'}, files: {rules: [{path: `data/bg3/${version}/${artifact}`}]}};
  const index = {catalogVersion: version, count: 0, items: []}, rules = {schemaVersion: 'bg3-rule-definitions/1', catalogVersion: version, kind: 'passive', count: programs.length,
    rules: programs.map((program, i) => ({id: 'rule-' + i, bg3Id: 'TEST_' + i, programs: {standard: program}}))};
  let artifactCalls = 0;
  const e = loadEngine(() => 0, async url => {
    const body = url.endsWith('/manifest.json') ? manifest : url.endsWith('/search-index.json') ? index : url.endsWith('/' + artifact) ? (artifactCalls++, rules) : null;
    return body ? {ok: true, json: async () => plain(body)} : {ok: false, status: 404, json: async () => ({})};
  });
  e.bg3CatalogUseRefs([{id: 'bg3', version, profile: 'standard'}]);await e.bg3CatalogEnsureIndex();
  const foe = plain(e.seedFoesDB()[0]);foe.activeFx = [];
  const spells=e.seedSpellsDB(),classes=e.seedClassesDB(),sacred=spells.find(spell=>spell.id==='sp_sacred_flame');assert.ok(sacred);sacred.cm='В';
  const actor = hero('lifecycle-user', {inventory: [
    {id: 'main-entry', itemId: ids.main, qty: 1}, {id: 'off-entry', itemId: ids.off, qty: 1},
    {id: 'inventory-entry', itemId: ids.inventory, qty: 1}, {id: 'bad-entry', itemId: ids.bad, qty: 1},
    {id: 'plain-entry', itemId: plainWeapon.id, qty: 1},
  ], equipment: {MAIN_HAND: 'main-entry', OFF_HAND: 'off-entry'}, activeFx: [
    {uid: 'grant-status', k: 'bg3-status', id: 'TEST_SOURCE_STATUS', bg3Status: 'TEST_SOURCE_STATUS', sourceItemId: ids.grant, fx: []},
  ],spellbook:[{spellId:sacred.id,prep:true}]});
  e.setState({chars: [actor], items, spells, classes, foes: [foe], activeCharId: actor.id});

  assert.equal(e.combatStart([{kind:'ally',id:actor.id,nat:20},{kind:'foe',id:foe.id,nat:1}],'pending lifecycle'),true);
  assert.equal(e.combatWeapon('plain-entry','melee','attack'),false,'combat cannot open a formula while an active lifecycle modifier is pending');
  assert.equal(e.state().combat.turn.actionsUsed,0);assert.equal(e.combatEnd(true),true);
  const pendingHp = foe.hp, pendingAttack = e.weaponAttackApply('main-entry', actor.id, `foe:${foe.id}`,
    {attackMade: true, hit: false, dmgTotal: 0, dmgRaw: 0, reactionUses: [], consumeCasterFx: [], consumeTargetFx: [], weaponItemTriggers: [], verdict: []});
  assert.equal(pendingAttack, false, 'an immediate attack cannot bypass pending lifecycle artifacts');assert.equal(foe.hp, pendingHp);

  let state = await e.bg3LifecycleReconcile(actor);assert.equal(state.ok, true);assert.equal(artifactCalls, 1, 'one shared lifecycle artifact is loaded once');
  assert.equal(e.fxSum(actor, 'ac'), 3, 'equipped and off-hand effects are both active');assert.equal(e.fxSum(actor, 'init'), 4, 'main-hand and inventory gates are active');
  let audit = e.bg3LifecycleAudit(actor);assert.equal(audit.rows.filter(row => row.status === 'applied').length, 4);
  assert.equal(audit.rows.some(row => row.programId === 'p-bad' && row.status === 'blocked'), true);
  assert.equal(audit.rows.some(row => row.programId === 'p-grant' && row.reason === 'UnlockSpell-has-no-exact-executable-adapter'), true,
    'UnlockSpell is not exposed without an exact executable adapter');
  assert.equal(e.fxSum(actor, 'ac'), 3, 'the typed prefix of the mixed +99 program never leaks into effects');

  const globalBlock=e.bg3LifecycleActionPreflight(actor,'','spell',null);
  assert.equal(globalBlock.ok,false);assert.match(globalBlock.reason,/«Предмет BG3» · Пассивное свойство «Blocked lifecycle»/,'the public audit identifies the safe item/property labels that make actor formulas unsafe');assert.doesNotMatch(globalBlock.reason,/p-bad|→/,'the public lifecycle reason omits internal reference ids');
  const plainMiss={attackMade:true,hit:false,dmgTotal:0,dmgRaw:0,reactionUses:[],consumeCasterFx:[],consumeTargetFx:[],weaponItemTriggers:[],verdict:[]};
  assert.equal(e.weaponAttackApply('plain-entry',actor.id,`foe:${foe.id}`,plainMiss),false,
    'an unsupported active modifier also blocks a non-BG3 weapon formula');
  const spellRolls={dmgRaw:3,dmgTotal:3,dmgType:'излучение',hit:null,saveOk:false,contestWin:null,effectAllowed:true,attackMade:false,
    reactionUses:[],consumeCasterFx:[],consumeTargetFx:[],verdict:[],notes:[]};
  const beforeBlockedSpell=foe.hp;
  assert.equal(e.castSpellApply(sacred.id,actor.id,`foe:${foe.id}`,'',undefined,'0',spellRolls),false,
    'an unsupported active modifier also blocks a core spell before consequences');
  assert.equal(foe.hp,beforeBlockedSpell);

  actor.inventory = actor.inventory.filter(entry => entry.id !== 'bad-entry');await e.bg3LifecycleReconcile(actor);
  const confirmedPlainMiss=productionWeaponConfirmation(e,actor,'plain-entry',`foe:${foe.id}`,freshSpec=>{const attack=freshSpec.rows.find(row=>row.type==='atk');return {[attack.key]:1};},{mode:'melee',within5:true});
  assert.equal(e.weaponAttackApply('plain-entry',actor.id,`foe:${foe.id}`,confirmedPlainMiss.rolls),true,
    'an unrelated blocked on-hit program does not freeze an ordinary confirmed miss');
  assert.equal(e.castSpellApply(sacred.id,actor.id,`foe:${foe.id}`,'',undefined,'0',spellRolls),true,
    'the same core spell proceeds once the unsafe active modifier is removed: '+e.elementText('saveStatus'));
  assert.equal(foe.hp,beforeBlockedSpell-3);
  e.combatStart([{kind: 'ally', id: actor.id, nat: 20}, {kind: 'foe', id: foe.id, nat: 1}], 'BG3 lifecycle boundary');
  const targetKey = `foe:${foe.id}`, blockedHp = foe.hp, hitConfirmation=productionWeaponConfirmation(e,actor,'main-entry',targetKey,freshSpec=>{const attack=freshSpec.rows.find(row=>row.type==='atk'),damage=freshSpec.rows.find(row=>row.type==='dmg');return {[attack.key]:19,[damage.key]:4};},
    {mode:'melee',within5:true,combatCost:'attack',combatActorKey:`ally:${actor.id}`}),hitRolls=hitConfirmation.rolls;
  assert.equal(e.weaponAttackApply('main-entry', actor.id, targetKey, hitRolls), false, 'a blocked on-hit branch aborts before the attack commit');
  assert.equal(foe.hp, blockedHp);assert.equal(e.state().combat.turn.attacksUsed, 0);assert.equal(actor.inventory.find(x => x.id === 'main-entry').qty, 1);
  const missRolls=productionWeaponConfirmation(e,actor,'main-entry',targetKey,freshSpec=>{const attack=freshSpec.rows.find(row=>row.type==='atk');return {[attack.key]:1};},
    {mode:'melee',within5:true,combatCost:'attack',combatActorKey:`ally:${actor.id}`}).rolls;
  assert.equal(e.weaponAttackApply('main-entry', actor.id, targetKey, missRolls), true, 'the same blocked on-hit branch cannot block a confirmed miss');
  assert.equal(foe.hp, blockedHp);assert.equal(e.state().combat.turn.attacksUsed, 1);

  assert.equal(e.combatEnd(true),true);
  items[0].mechanics.lifecyclePrograms = items[0].mechanics.lifecyclePrograms.filter(row => row.programId !== 'p-hit-bad');await e.bg3LifecycleReconcile(actor);
  const miss = e.bg3LifecycleOnHitPlanFor(actor, 'main-entry', targetKey, {attackMade: true, hit: false}, 'miss-event');
  assert.equal(miss.ok, false);assert.equal(miss.notTriggered, true);assert.equal(foe.activeFx.length, 0);
  assert.equal(e.combatStart([{kind:'ally',id:actor.id,nat:20},{kind:'foe',id:foe.id,nat:1}],'BG3 typed on-hit'),true);
  const typedHit=productionWeaponConfirmation(e,actor,'main-entry',targetKey,freshSpec=>{const attack=freshSpec.rows.find(row=>row.type==='atk'),damage=freshSpec.rows.find(row=>row.type==='dmg');return {[attack.key]:19,[damage.key]:4};},
    {mode:'melee',within5:true,combatCost:'attack',combatActorKey:`ally:${actor.id}`}).rolls,
    previewHit=plain(typedHit),hit = e.bg3LifecycleOnHitPlanFor(actor, 'main-entry', targetKey, previewHit, 'hit-event');
  assert.equal(hit.ok, true);assert.equal(foe.activeFx.length, 0, 'on-hit preflight cannot mutate the target');
  const typedHp=foe.hp;
  assert.equal(e.weaponAttackApply('main-entry',actor.id,targetKey,typedHit),true,'the immutable typed on-hit plan commits only after the attack commit');
  assert.equal(foe.hp,typedHp-4);assert.equal(e.state().combat.turn.attacksUsed,1);
  assert.equal(foe.activeFx.filter(x => x.bg3Status === 'TEST_ON_HIT').length, 1);
  assert.equal(foe.activeFx.some(x => x.bg3Status === 'FORBIDDEN_PARTIAL'), false, 'mixed on-hit program is wholly blocked');
  const duplicatePlan=e.bg3LifecycleOnHitPlanFor(actor,'main-entry',targetKey,previewHit,'hit-event-after-private-commit');assert.equal(duplicatePlan.ok,true);
  assert.equal(e.bg3LifecycleOnHitCommit(duplicatePlan).ok,true);assert.equal(e.bg3LifecycleOnHitCommit(duplicatePlan).replay,true);
  assert.equal(foe.activeFx.filter(x => x.bg3Status === 'TEST_ON_HIT').length, 1, 'a separately replayed exact lifecycle plan cannot add a second stacked status');

  delete actor.equipment.OFF_HAND;state = await e.bg3LifecycleReconcile(actor);assert.equal(state.ok, true);
  assert.equal(e.fxSum(actor, 'ac'), 2);assert.equal(e.fxSum(actor, 'init'), 4, 'removing off-hand removes only its derived effect after reconciliation');
  actor.equipment = {OFF_HAND: 'main-entry'};await e.bg3LifecycleReconcile(actor);
  assert.equal(e.fxSum(actor, 'ac'), 2, 'generic equipped gate remains active in off hand');assert.equal(e.fxSum(actor, 'init'), 1, 'main-hand gate is inactive in off hand; inventory gate remains');
  actor.equipment = {};await e.bg3LifecycleReconcile(actor);
  assert.equal(e.fxSum(actor, 'ac'), 0);assert.equal(e.fxSum(actor, 'init'), 1, 'inventory gate survives complete unequip');
});

