    prepared=await e.bg3InterruptPrepare(item,ref,descriptor);assert.equal(prepared.ok,true,prepared.reason);const options=await e.bg3InterruptOptionsFor(actor,event);assert.equal(options.length,1);assert.equal(options[0].icon.src,descriptor.icon.src);
  assert.deepEqual(plain(e.bg3InterruptRuntimeSupport(prepared)),{runtimeSupported:true,sourceBlocked:false,unsupported:[],eventInputs:[`item-resource:${interruptId}`,'player-roll:resource:BardicInspiration']});const bus=await e.bg3InterruptEventBus(event);assert.equal(bus.ok,true);assert.equal(bus.options.length,1);assert.equal(bus.commitPolicy,'explicit-player-choice-only');
