  const plan=e.bg3InterruptPlan(prepared,actor,event,{confirmed:true,entryId:'interrupt-entry','resource:BardicInspiration':4});assert.equal(plan.ok,true,plan.reason);assert.equal(actor.activeFx.some(row=>row.bg3Status==='BARDIC_INSPIRATION_MARKER'),true,'preflight has no consequences');
