test('BG3 spell aggregation includes an extra-target-only prepared interrupt in the source permit', async () => {
  const seed=bg3InterruptTestCatalog({version:'bg3-9111-v1',specs:[]}),symbol=seed.symbol,integer=seed.integer,
    selfGuard={kind:'predicate',name:'Self',args:[symbol('context.Observer'),symbol('context.Target')]},fixture=bg3InterruptTestCatalog({version:'bg3-9111-v1',specs:[
      {id:'ExtraTarget_Adjust',context:'OnPostRoll',guard:selfGuard,ops:[{op:'adjustRoll',args:[integer(4)]}]},
    ]}),e=loadEngine(()=>0.5,fixture.fetch);
  assert.equal(e.bg3CatalogUseRefs([{id:'bg3',version:fixture.version,profile:'standard'}]),true);await e.bg3CatalogEnsureIndex();
  const spell={id:'extra-target-interrupt-spell',n:'Extra target interrupt spell',l:1,s:'Evocation',c:'Жрц',t:'1 действие',r:'18 м',cm:'В',d:'Мгновенная',x:'Targets make a saving throw.',tags:['aoe']},
    caster=hero('extra-target-caster',{slots:{1:{max:1,cur:1}},spellbook:[{spellId:'extra-target-interrupt-spell',prep:true}]}),
    observer=hero('extra-target-observer',{hp:20,hpMax:20,inventory:[{id:'extra-target-carrier',itemId:fixture.item.id,qty:1}],equipment:{HEAD:'extra-target-carrier'}}),
    foe=plain(e.seedFoesDB()[0]),primary=`foe:${foe.id}`,extra=`ally:${observer.id}`;foe.hp=foe.hpMax=30;
  e.setState({chars:[caster,observer],items:[fixture.item],spells:[spell],foes:[foe],activeCharId:caster.id});assert.equal((await e.bg3LifecycleReconcile(observer)).ok,true);
  assert.equal(e.combatStart([{kind:'ally',id:caster.id,nat:20},{kind:'ally',id:observer.id,nat:15},{kind:'foe',id:foe.id,nat:1}],'extra target interrupt aggregation'),true);
  const saveRolls=()=>({notes:[],verdict:[],attackMade:false,saveMade:true,hit:null,saveOk:false,effectAllowed:true,dmgRaw:6,dmgTotal:6,dmgType:'огонь',damageParts:[{raw:6,total:6,type:'огонь',saveGate:'either',saveMode:'zero'}],reactionUses:[],consumeCasterFx:[],consumeTargetFx:[],bg3InterruptFormula:{save:{natural:9,total:13,mod:4,dc:15,success:false,ability:'wis'},damageTags:{magical:true},saveDefaultMode:'zero'}}),
    primaryRolls=saveRolls(),extraRolls=saveRolls(),ctx={kind:'spell',spellId:spell.id,casterId:caster.id,target:primary,primaryTarget:primary,extraTargets:[extra],formulaLvl:1,combatCost:'action',combatActorKey:`ally:${caster.id}`,combatCommitted:false};
  e.setCastContext(ctx);const primarySource=e.bg3InterruptBuildCastSource(primaryRolls,ctx);assert.equal(e.bg3InterruptSourceRows(primarySource,false).filter(row=>row.descriptor.interruptId==='ExtraTarget_Adjust').length,0,'the primary target has no eligible carrier');
  ctx.target=extra;const extraSource=e.bg3InterruptBuildCastSource(extraRolls,ctx),matches=e.bg3InterruptSourceRows(extraSource,false).filter(row=>row.descriptor.interruptId==='ExtraTarget_Adjust');assert.equal(matches.length,1,'the additional target contributes the only exact candidate');
  const decisions=Object.fromEntries(matches.map(row=>[row.key,{}])),composite=await e.bg3InterruptPipelinePrepare(extraSource,{interactive:false,decisions});assert.equal(composite.ok,true,composite.reason);assert.equal(composite.plans.length,1);
  extraRolls.bg3InterruptSource=composite.source;extraRolls.bg3InterruptComposite=composite;ctx.target=primary;e.setCastContext(ctx);const foeHp=foe.hp,observerHp=observer.hp;
  assert.equal(e.castSpellApply(spell.id,caster.id,primary,'',undefined,'1',primaryRolls,[extra],{[extra]:extraRolls}),true,e.elementText('saveStatus')||e.elementText('castErr'));
  assert.equal(foe.hp,foeHp-6,'the primary source branch still commits');assert.equal(extraRolls.saveOk,true,'the extra-target reaction is projected before its source branch');assert.equal(observer.hp,observerHp,'the adjusted successful save suppresses the extra target damage');
  assert.equal(e.state().combat.order.find(row=>row.kind==='ally'&&row.id===observer.id).reactionUsed,true);assert.equal(caster.slots[1].cur,0);assert.equal(e.state().combat.turn.actionsUsed,1);
});

test('multi-target spell aggregates outcome reaction budgets before slot, action or target mutation', () => {
  const e=loadEngine(),reactionAction=bg3TestAction('spell-aggregate-reaction','bg3RuleProgram',{cost:'reaction'}),reactionItem=bg3TestItem('spell-aggregate-reaction',[reactionAction]);reactionItem.mechanics.itemSpec.charges=2;
  const spell={id:'spell-aggregate-budget',n:'Aggregate budget spell',l:1,s:'Evocation',c:'Жрц',t:'1 действие',r:'18 м',cm:'В',d:'Мгновенная',x:'Targets take fire damage.',tags:['aoe']},foes=e.seedFoesDB().slice(0,2).map((foe,index)=>Object.assign(plain(foe),{id:'aggregate-target-'+index,hp:20,hpMax:20})),
    caster=hero('aggregate-caster',{slots:{1:{max:1,cur:1}},spellbook:[{spellId:spell.id,prep:true}],inventory:[{id:'aggregate-reaction-entry',itemId:reactionItem.id,qty:1,ch:{cur:2,max:2}}],equipment:{HEAD:'aggregate-reaction-entry'}}),targets=foes.map(foe=>`foe:${foe.id}`),
    reaction={kind:'item',actorKey:`ally:${caster.id}`,entryId:'aggregate-reaction-entry',itemId:reactionItem.id,useId:reactionAction.id,label:'aggregate reaction'},makeRolls=()=>({dmgRaw:4,dmgTotal:4,dmgType:'огонь',damageParts:[{raw:4,total:4,type:'огонь'}],attackMade:false,saveMade:false,effectAllowed:true,reactionUses:[plain(reaction)],consumeCasterFx:[],consumeTargetFx:[],verdict:[],notes:[]}),primary=makeRolls(),extra=makeRolls();
  e.setState({chars:[caster],items:[reactionItem],spells:[spell],foes,activeCharId:caster.id});assert.equal(e.combatStart([{kind:'ally',id:caster.id,nat:20},...foes.map((foe,index)=>({kind:'foe',id:foe.id,nat:10-index}))],'aggregate reaction budget'),true);
  const ctx={kind:'spell',spellId:spell.id,casterId:caster.id,target:targets[0],primaryTarget:targets[0],extraTargets:[targets[1]],formulaLvl:1,combatCost:'action',combatActorKey:`ally:${caster.id}`,combatCommitted:false};e.setCastContext(ctx);
  assert.equal(e.castSpellApply(spell.id,caster.id,targets[0],'',undefined,'1',primary,[targets[1]],{[targets[1]]:extra}),false,'one reaction cannot be promised to both target carriers');assert.deepEqual(plain(foes.map(foe=>foe.hp)),[20,20]);assert.equal(caster.slots[1].cur,1);assert.equal(e.state().combat.turn.actionsUsed,0);assert.equal(e.state().combat.order[0].reactionUsed,false);assert.equal(caster.inventory[0].ch.cur,2);
  e.applyFxTo(caster.id,{uid:'aggregate-extra-reaction',label:'extra reaction',fx:[{stat:'combat.reaction.max',mode:'add',value:1}]});assert.equal(e.castSpellApply(spell.id,caster.id,targets[0],'',undefined,'1',primary,[targets[1]],{[targets[1]]:extra}),true,e.elementText('saveStatus'));assert.deepEqual(plain(foes.map(foe=>foe.hp)),[16,16]);assert.equal(caster.slots[1].cur,0);assert.equal(e.state().combat.turn.actionsUsed,1);assert.equal(+e.state().combat.order[0].reactionUsed,2);assert.equal(caster.inventory[0].ch.cur,0);
});

