    caster=hero('disabled-only-caster',{slots:{1:{max:1,cur:1}},spellbook:[{spellId:'disabled-only-source-spell',prep:true}],inventory:[{id:'disabled-only-carrier',itemId:fixture.item.id,qty:1}],equipment:{HEAD:'disabled-only-carrier'}}),foe=plain(e.seedFoesDB()[0]),target=`foe:${foe.id}`;foe.hp=foe.hpMax=30;
