  assert.equal(e.combatStart([{kind:'ally',id:caster.id,nat:20},{kind:'foe',id:foe.id,nat:1}],'disabled only spell interrupt'),true);
  const rolls={notes:[],verdict:[],attackMade:false,saveMade:false,hit:null,saveOk:null,effectAllowed:true,dmgRaw:5,dmgTotal:5,dmgType:'огонь',damageParts:[{raw:5,total:5,type:'огонь'}],reactionUses:[],consumeCasterFx:[],consumeTargetFx:[],bg3InterruptFormula:{damageTags:{magical:true},saveDefaultMode:'zero'}},
    ctx={kind:'spell',spellId:spell.id,casterId:caster.id,target,primaryTarget:target,formulaLvl:1,combatCost:'action',combatActorKey:`ally:${caster.id}`,combatCommitted:false};
  e.setCastContext(ctx);const source=e.bg3InterruptBuildCastSource(rolls,ctx);assert.equal(e.bg3InterruptSourceNeedsComposite(source),true,'blocked exact rows still open the decision UI');assert.equal(e.bg3InterruptSourceRequiresExecutable(source),false,'a disabled row is never executable');
