  const optionalState=await e.bg3LifecycleReconcile(actor),optionalRow=optionalState.rows.find(value=>value.refId===optionalRef.id);assert.equal(optionalRow.status,'granted-action-blocked');assert.equal(optionalRow.optionalGrantOnly,true);assert.equal(optionalState.granted.length,0,'the unavailable optional action never creates a button/runtime virtual');
