  positive.cost={declared:true,raw:'ReactionActionPoint:1',entries:[{resource:'ReactionActionPoint',resourceRole:'reaction',amount:{kind:'integer',value:1},qualifiers:[]}],mode:'typed',complete:true};positive.cooldown={declared:false,raw:null,sourceKind:null,kind:'none',itemScoped:false,complete:true};positive.commit={cardinality:'once-after-accepted-choice',consumeOwningItem:null,complete:true};
  const field={field:'Properties',role:'consequences',raw:'AdjustRoll(-1)',ast:{kind:'call',name:'AdjustRoll',args:[{kind:'integer',value:-1}]},bytecode:[{op:'adjustRoll',executable:true,args:[{kind:'integer',value:-1}]}],mode:'typed',counts:{typedOpcodes:1,manualOpcodes:0}};
