  const counterPrepared={ok:true,it:scrollItem,ref:scrollRef,descriptor:counterDescriptor,programs:new Map([['rules/spells/a3.json|'+successProgram,emptyProgram(successProgram)],['rules/spells/a3.json|'+failureProgram,emptyProgram(failureProgram)]])},counterEvent={schemaVersion:'dnd-world-bg3-interrupt-event/1',id:'counter-event',context:'OnSpellCast',scope:'Nearby',observer:`ally:${counterActor.id}`,source:`foe:${counterFoe.id}`,target:`ally:${counterActor.id}`,spell:{id:'Target_Fireball',level:4,isSpell:true},facts:[{predicate:'CounterspellCheck',args:[],value:true}]};
