test('BG3 Periapt of Wound Closure follows the exact DOWNED source graph and stabilizes once at StartTurn', async () => {
  const repo=new URL('..',import.meta.url),readJson=relative=>JSON.parse(fs.readFileSync(new URL(relative,repo),'utf8')),
    sourceVersion=productionBg3Version,version='bg3-24532580-v1',itemId='bg3:item:rt:716e94de-130b-4f54-84d9-a14fc60adcfb:stats:TUFHX1BIQl9QZXJpYXB0b2ZXb3VuZENsb3N1cmVfQW11bGV0',
    sourceItem=productionBg3Item(itemId);
  assert.ok(sourceItem);const artifacts=[...new Set(sourceItem.mechanics.lifecyclePrograms.flatMap(ref=>[ref.artifact]
    .concat((ref.projection&&ref.projection.entrypoints||[]).map(row=>row.artifact),(ref.projection&&ref.projection.transitive||[]).map(row=>row.artifact))).filter(Boolean))],payloads=new Map();
  for(const artifact of artifacts){const payload=readJson(`data/bg3/${sourceVersion}/${artifact}`);payload.catalogVersion=version;payloads.set(artifact,payload);}
  const manifest={catalogVersion:version,contracts:{itemSchemaVersion:6},source:{profiles:{standard:{}}},entrypoints:{searchIndex:'search-index.json'},
      files:{rules:artifacts.map(artifact=>({path:`data/bg3/${version}/${artifact}`}))}},index={catalogVersion:version,count:0,items:[]},
    fetch=async url=>{let body=url.endsWith('/manifest.json')?manifest:url.endsWith('/search-index.json')?index:null;
      if(!body)for(const [artifact,payload] of payloads)if(url.endsWith('/'+artifact)){body=payload;break;}
      return body?{ok:true,json:async()=>plain(body)}:{ok:false,status:404,json:async()=>({})};},e=loadEngine(()=>0.5,fetch);
  e.bg3CatalogUseRefs([{id:'bg3',version,profile:'standard'}]);await e.bg3CatalogEnsureIndex();
  const makeActor=(id,failures=1)=>hero(id,{hp:0,hpMax:20,deaths:{s:0,f:failures},cond:['Бессознательный'],inventory:[{id:id+'-periapt',itemId,qty:1}],
    equipment:{AMULET:id+'-periapt'},activeFx:[{uid:id+'-burning',k:'bg3-status',id:'BURNING',bg3Status:'BURNING',label:'BURNING',fx:[{stat:'bg3.status',mode:'text',value:'BURNING'}]}]});
  const actor=makeActor('periapt-holder'),item=plain(sourceItem);e.setState({chars:[actor],items:[item],activeCharId:actor.id});
  const runtime=await e.bg3LifecycleReconcile(actor);assert.equal(runtime.ok,true);assert.equal(runtime.rows.filter(row=>row.status==='event-ready').length,1,JSON.stringify(runtime.rows));
  assert.equal(runtime.rows.some(row=>row.bg3Id==='MAG_PHB_PeriaptofWoundClosure_Amulet_Maximize_Passive'&&row.status==='applied'),true);
  const ignored=e.bg3LifecycleHolderStatusEventPreflight(actor,'BURNING','periapt-wrong-status');assert.equal(ignored.ok,true);assert.equal(ignored.notTriggered,true);
  assert.equal(actor.activeFx.filter(row=>row.bg3Status==='MAG_WOUND_CLOSURE').length,0);
  const cancelled=e.bg3LifecycleHolderStatusEventPreflight(actor,'DOWNED','periapt-cancelled');assert.equal(cancelled.ok,true);
  assert.equal(actor.activeFx.filter(row=>row.bg3Status==='MAG_WOUND_CLOSURE').length,0,'an uncommitted event plan has no consequence');
  const downed=e.bg3LifecycleHolderStatusEventPreflight(actor,'DOWNED','periapt-downed-1');assert.equal(downed.ok,true);const applied=e.bg3LifecycleHolderStatusEventCommit(downed);
  assert.equal(applied.ok,true,applied.reason);const marker=actor.activeFx.find(row=>row.bg3Status==='MAG_WOUND_CLOSURE');assert.ok(marker);
  assert.equal(marker.durationKind,'targetStart');assert.equal(marker.bg3StatusLifecycle.tickType,'StartTurn');assert.equal(actor.activeFx.some(row=>row.bg3Status==='BURNING'),true);
  const replay=e.bg3LifecycleHolderStatusEventCommit(downed);assert.equal(replay.ok,false);assert.equal(replay.replay,true);
  assert.equal(actor.activeFx.filter(row=>row.bg3Status==='MAG_WOUND_CLOSURE').length,1);
  const turn=e.bg3StatusLifecycleStartTurnPreflight(`ally:${actor.id}`);assert.equal(turn.ok,true);assert.equal(turn.plans.length,1);
  const stabilized=e.bg3StatusLifecycleStartTurnCommit(turn);assert.equal(stabilized.ok,true);assert.deepEqual(plain(actor.deaths),{s:3,f:0});
  assert.equal(actor.activeFx.some(row=>row.bg3Status==='MAG_WOUND_CLOSURE'),false);assert.equal(actor.activeFx.some(row=>row.bg3Status==='BURNING'),true);
  assert.equal(e.bg3StatusLifecycleStartTurnCommit(turn).ok,true,'the committed StartTurn token is replay-safe');assert.deepEqual(plain(actor.deaths),{s:3,f:0});

  const stale=makeActor('periapt-stale');e.setState({chars:[stale],items:[item],activeCharId:stale.id});await e.bg3LifecycleReconcile(stale);
  const stalePlan=e.bg3LifecycleHolderStatusEventPreflight(stale,'DOWNED','periapt-stale-event'),staleBefore=plain(stale.activeFx);delete stale.equipment.AMULET;
  const staleResult=e.bg3LifecycleHolderStatusEventCommit(stalePlan);assert.equal(staleResult.ok,false);assert.equal(staleResult.stale,true);assert.deepEqual(plain(stale.activeFx),staleBefore);
  stale.equipment.AMULET=stale.inventory[0].id;await e.bg3LifecycleReconcile(stale);const tamperPlan=e.bg3LifecycleHolderStatusEventPreflight(stale,'DOWNED','periapt-tamper-event'),
    eventRef=item.mechanics.lifecyclePrograms.find(ref=>ref.bg3Id==='MAG_PHB_PeriaptofWoundClosure_Amulet_Passive'),oldGate=eventRef.gate;eventRef.gate='inventory';
  const tampered=e.bg3LifecycleHolderStatusEventCommit(tamperPlan);assert.equal(tampered.ok,false);assert.equal(tampered.stale,true);assert.equal(stale.activeFx.some(row=>row.bg3Status==='MAG_WOUND_CLOSURE'),false);eventRef.gate=oldGate;
  await e.bg3LifecycleReconcile(stale);const profilePlan=e.bg3LifecycleHolderStatusEventPreflight(stale,'DOWNED','periapt-profile-event');
  assert.equal(e.bg3CatalogUseRefs([]),true);const switched=e.bg3LifecycleHolderStatusEventCommit(profilePlan);assert.equal(switched.ok,false);assert.equal(switched.stale,true);
  assert.equal(stale.activeFx.some(row=>row.bg3Status==='MAG_WOUND_CLOSURE'),false);

  e.bg3CatalogUseRefs([{id:'bg3',version,profile:'standard'}]);await e.bg3CatalogEnsureIndex();const dead=makeActor('periapt-dead',3);e.setState({chars:[dead],items:[item],activeCharId:dead.id});await e.bg3LifecycleReconcile(dead);
  const deadPlan=e.bg3LifecycleHolderStatusEventPreflight(dead,'DOWNED','periapt-dead-event');assert.equal(e.bg3LifecycleHolderStatusEventCommit(deadPlan).ok,true);
  const deadTurn=e.bg3StatusLifecycleStartTurnPreflight(`ally:${dead.id}`);assert.equal(deadTurn.ok,true);assert.equal(e.bg3StatusLifecycleStartTurnCommit(deadTurn).ok,true);
  assert.deepEqual(plain(dead.deaths),{s:0,f:3},'ApplyToDead permits the marker, but Stabilize never revives a truly dead holder');assert.equal(dead.activeFx.some(row=>row.bg3Status==='BURNING'),true);
});

