  for(const row of spec.rows.filter(value=>value.type==='dmg'))values[row.key]=Math.max(1,+row.cnt||1);const built=e.castFormulaRollsBuild(spec,values,e.resolveOutcome(spec,values));assert.equal(built.ok,true,built.reason);assert.equal(built.rolls.hit,true);assert.ok(built.rolls.dmgTotal>0);
  const preProof=e.bg3ElementalInfusionFinalDamageProof(actor,[{target:targetKey,rolls:built.rolls}],'spell');assert.equal(preProof.ok,true,preProof.reason);
  const criticalDescriptor=Object.getOwnPropertyDescriptor(spec.meta,'criticalThreshold'),getterBefore=plain({actor,target});let getterHits=0;Object.defineProperty(spec.meta,'criticalThreshold',{configurable:true,enumerable:true,get(){getterHits++;target.hp=1;return 2;}});assert.equal(e.castSpellApply(spell.id,actor.id,targetKey,'',null,'1',built.rolls,[],{}),false,'a post-build formula getter is rejected before the spell transaction');assert.equal(getterHits,0);assert.deepEqual(plain({actor,target}),getterBefore,'getter rejection preserves HP, slot, charge, and tokens');if(criticalDescriptor)Object.defineProperty(spec.meta,'criticalThreshold',criticalDescriptor);else delete spec.meta.criticalThreshold;
  const before=plain({actor,target}),restore=e.injectBg3StatusTokenCommitThrowOnce('bg3-spell-damage:');assert.equal(e.castSpellApply(spell.id,actor.id,targetKey,'',null,'1',built.rolls,[],{}),false,'injected post-charge token failure aborts the entire cast');restore();
  assert.deepEqual(plain({actor,target}),before,'slot, HP, charge, VFX, and lifecycle tokens restore to the same pre-cast world');assert.equal(e.castSpellApply(spell.id,actor.id,targetKey,'',null,'1',built.rolls,[],{}),true,e.bg3ElementalInfusionTestLastError()+' '+e.elementText('saveStatus')+' '+e.elementText('castErr'));
