  objectWorld.actor.activeFx.push({uid:'independent-fire-grant',fx:[{stat:'bg3.weapon.damage.extra',mode:'grant',value:{amount:{cnt:1,sides:4,mod:0},type:'огонь',entryId:'',when:{attackKind:'weapon'}}}]});
