  const collapseWorld=await elementalInfusionWorld('observer');collapseWorld.actor.activeFx.push({uid:'external-status-observer',bg3StatusLifecycle:{removeEvents:['OnStatusApplied'],removeCondition:{kind:'predicate',name:'ExternalObserver',args:[]}},fx:[]});
