    artifacts=[...new Set([action.program.artifact].concat(action.program.projection.entrypoints,action.program.projection.transitive).map(row=>typeof row==='string'?row:row&&row.artifact).filter(Boolean))],
    sourcePrograms=profile=>artifacts.flatMap(artifact=>readJson(`data/bg3/${version}/${artifact}`).rules.flatMap(rule=>{const program=rule.programs&&rule.programs[profile];if(!program)return [];
      const tagged=plain(program);tagged.bg3SourceRule={kind:String(rule.kind),ruleId:String(rule.id),bg3Id:String(rule.bg3Id),properties:plain(rule.properties||{})};return [{program:tagged,artifact}];})),
    root=roots.find(row=>row.id===action.program.id),e=loadEngine(),speedRule=readJson(`data/bg3/${version}/rules/statuses/27.json`).rules.find(rule=>rule.bg3Id==='POTION_OF_SPEED'),
