  for(const key of ['TickType','TickFunctors','OnApplyFunctors']){delete standardProperties[key];delete standardDirectProperties[key];}
  standardProperties.OnRemoveFunctors='ApplyStatus(HASTE_LETHARGY,100,1)';standardDirectProperties.OnRemoveFunctors='ApplyStatus(HASTE_LETHARGY,100,1)';
  const profiledSpeedRule=Object.assign(plain(speedRule),{standardProperties,standardDirectProperties}),profiledPayload={rules:[profiledSpeedRule]};
  e.bg3CatalogUseRefs([{id:'bg3',version:'bg3-24532580-v1',profile:'standard'}]);const standardTagged=e.bg3RuleArtifactPrograms(profiledPayload)[0];
  assert.equal(standardTagged.bg3SourceRule.sourceProfile,'standard');assert.equal(standardTagged.bg3SourceRule.engineType,'StatusData','source engine type survives artifact program tagging');assert.equal(Object.hasOwn(standardTagged.bg3SourceRule.properties,'TickFunctors'),false);assert.equal(Object.hasOwn(standardTagged.bg3SourceRule.properties,'OnApplyFunctors'),false);
  assert.equal(Object.hasOwn(standardTagged.bg3SourceRule.directProperties,'TickFunctors'),false);
  const exactStandardPrograms=sourcePrograms('standard').map(row=>row.program.bg3SourceRule.bg3Id==='POTION_OF_SPEED'?{program:standardTagged,artifact:row.artifact}:row),standard=e.bg3RuleProgramCompile(action,root,exactStandardPrograms),
    standardSpeedDescriptor=standard.statusLifecycles.find(row=>row.statusId==='POTION_OF_SPEED');
  assert.equal(standard.ok,true,e.bg3RuleProgramReport(standard));assert.deepEqual(plain(standard.statusLifecycles.map(row=>row.statusId).sort()),['HASTE_LETHARGY','POTION_OF_SPEED']);
  assert.equal(standardSpeedDescriptor.tickType,'');assert.equal(Object.hasOwn(standardSpeedDescriptor.sourceProperties,'OnApplyFunctors'),false,'Standard descriptor owns Standard source metadata');

  const actor=hero('speed-standard',{speed:'9 м',inventory:[{id:'speed-entry',itemId,qty:1}]}),foe=plain(e.seedFoesDB()[0]);e.setState({chars:[actor],items:[item],foes:[foe],activeCharId:actor.id});const baseAc=e.acTotal(actor);
  e.bg3RuleProgramInstall(action,standard);assert.equal(e.combatStart([{kind:'ally',id:actor.id,nat:20},{kind:'foe',id:foe.id,nat:1}],'Potion of Speed blocked'),true);
  e.setCastContext({kind:'item',combatCost:'bonus',combatActorKey:`ally:${actor.id}`,combatCommitted:false});
  assert.equal(e.useItemApply('speed-entry',actor.id,`ally:${actor.id}`,null,action.id),true);assert.equal(e.state().combat.turn.bonusUsed,true);assert.equal(actor.inventory.length,0);
  const speed=actor.activeFx.find(row=>row.bg3Status==='POTION_OF_SPEED');assert.ok(speed);assert.equal(speed.durationKind,'rounds');assert.equal(speed.expiresAtRound,4);
  assert.equal(e.state().combat.turn.actionMax,2);assert.equal(e.speedTotal(actor),'18 м');assert.equal(e.acTotal(actor),baseAc+2);assert.equal(e.charFxAll(actor).some(row=>row.stat==='save.dex'&&row.mode==='adv'),true);
  e.state().combat.turn.actionsUsed=1;e.combatSyncActionState();assert.deepEqual([e.state().combat.turn.actionsUsed,e.state().combat.turn.actionMax],[1,2]);
  assert.equal(e.advanceFxRound(3),true);const lethargy=actor.activeFx.find(row=>row.bg3Status==='HASTE_LETHARGY');assert.ok(lethargy);assert.equal(actor.activeFx.some(row=>row.bg3Status==='POTION_OF_SPEED'),false);
  assert.equal(e.state().combat.turn.actionMax,1);assert.equal(e.state().combat.turn.actionsUsed,1,'expiry removes only capacity and does not refund a spent action');
  assert.equal(e.saveConditionMode(e.targetInfoOf(`ally:${actor.id}`),'str',{}).autoFail,true);assert.equal(e.saveConditionMode(e.targetInfoOf(`ally:${actor.id}`),'dex',{}).autoFail,true);
  assert.equal(e.saveConditionMode(e.targetInfoOf(`ally:${actor.id}`),'con',{}).autoFail,false);assert.equal(e.bg3DetectDisturbancesCheck(actor,{kind:'world-noise'}).blocked,true);
  assert.equal(e.charFxAll(actor).some(row=>row.stat==='incoming.attack'&&row.mode==='adv'),true);assert.equal(e.effectiveConditions(actor).includes('Ошеломленный'),true);
  assert.equal(e.combatCanSpend('action',`ally:${actor.id}`,true),false,'SG_Stunned blocks the real combat action gate');assert.equal(e.acTotal(actor),baseAc);
  const unrelated={uid:'unrelated-speed-state',k:'test',id:'unrelated',label:'unrelated',fx:[{stat:'save.con',mode:'adv',value:1}]};actor.activeFx.push(unrelated);
  assert.equal(e.advanceFxRound(1),true);assert.equal(actor.activeFx.some(row=>row.uid===unrelated.uid),true,'lethargy expiry preserves unrelated state');assert.equal(e.bg3DetectDisturbancesCheck(actor).blocked,false);
  assert.equal(e.charFxAll(actor).some(row=>row.stat==='incoming.attack'&&row.mode==='adv'),false);assert.equal(e.effectiveConditions(actor).includes('Ошеломленный'),false);assert.equal(e.saveConditionMode(e.targetInfoOf(`ally:${actor.id}`),'str',{}).autoFail,false);

  const malformedRef={bg3Id:'HASTE_LETHARGY'},symbol=value=>({kind:'symbol',value}),integer=value=>({kind:'integer',value}),compile=op=>e.bg3LifecycleCompileModifier(malformedRef,{op,field:{role:'modifiers'},where:'speed-fixture'},actor,{});
  assert.equal(compile({op:'markAbilityFailedSavingThrow',executable:true,args:[symbol('Luck')]}).ok,false);
  assert.equal(compile({op:'markAbilityFailedSavingThrow',executable:true,args:[symbol('Strength'),symbol('Dexterity')]}).ok,false);
  assert.equal(compile({op:'blockDetectDisturbances',executable:true,args:[symbol('true')]}).ok,false);

  const ref={bg3Id:'POTION_OF_SPEED'},compileCapacity=op=>e.bg3LifecycleCompileModifier(ref,{op,field:{role:'modifiers'},where:'speed-capacity'},actor,{}),
    movement=compileCapacity({op:'modifyResourceCapacity',executable:true,args:[symbol('Movement'),integer(9),integer(0)]}),actionCapacity=compileCapacity({op:'modifyResourceCapacity',executable:true,args:[symbol('ActionPoint'),integer(1),integer(0)]});
  assert.equal(movement.ok,true);assert.deepEqual(plain(movement.fx.map(row=>[row.stat,row.value])),[['speed',9]]);assert.equal(actionCapacity.ok,true);
  assert.deepEqual(plain(actionCapacity.fx.map(row=>[row.stat,row.value])),[['combat.action.max',1]]);
  e.applyFxTo(actor.id,{k:'bg3-status',id:'POTION_OF_SPEED',bg3Status:'POTION_OF_SPEED',fx:actionCapacity.fx});const firstCapacityUid=actor.activeFx.at(-1).uid;e.combatSyncActionState();
  assert.equal(e.state().combat.turn.actionMax,2);e.state().combat.turn.actionsUsed=1;e.combatSyncActionState();assert.equal(e.state().combat.turn.actionsUsed,1);
  e.removeActiveFx(actor.id,firstCapacityUid);e.combatSyncActionState();assert.equal(e.state().combat.turn.actionMax,1);assert.equal(e.state().combat.turn.actionsUsed,1,'removing capacity does not refund the already spent action');
  e.applyFxTo(actor.id,{k:'bg3-status',id:'POTION_OF_SPEED',bg3Status:'POTION_OF_SPEED',fx:actionCapacity.fx});const secondCapacityUid=actor.activeFx.at(-1).uid;e.state().combat.turn.actionsUsed=2;e.combatSyncActionState();
  e.removeActiveFx(actor.id,secondCapacityUid);e.combatSyncActionState();assert.equal(e.state().combat.turn.actionMax,1);assert.equal(e.state().combat.turn.actionsUsed,1,'removal clamps to the reduced capacity without making an action available');
  assert.equal(e.combatCanSpend('action',`ally:${actor.id}`,true),false);

  const surge=e.seedAbilitiesDB().find(row=>row.id==='ab_lg_surge'),surgeActor=hero('speed-surge',{speed:'9 м',abilities:[{abilityId:'ab_lg_surge',cur:1}],inventory:[]});
  e.setState({chars:[surgeActor],abilities:[surge],items:[item],foes:[plain(foe)],activeCharId:surgeActor.id});assert.equal(e.combatStart([{kind:'ally',id:surgeActor.id,nat:20},{kind:'foe',id:foe.id,nat:1}],'Speed plus Action Surge'),true);
  e.applyFxTo(surgeActor.id,{k:'bg3-status',id:'POTION_OF_SPEED',bg3Status:'POTION_OF_SPEED',fx:actionCapacity.fx});const surgeSpeedUid=surgeActor.activeFx.at(-1).uid;e.combatSyncActionState();
  assert.equal(e.useAbilityApply('ab_lg_surge',surgeActor.id,`ally:${surgeActor.id}`,{notes:[],verdict:[]}),true);assert.deepEqual([e.state().combat.turn.actionsUsed,e.state().combat.turn.actionMax],[0,3]);
  e.removeActiveFx(surgeActor.id,surgeSpeedUid);e.combatSyncActionState();assert.equal(e.state().combat.turn.actionMax,2,'removing Haste capacity preserves the independently granted Action Surge slot');

