test('BG3 exact equipped modifiers change criticals, resistance, healing and weapon proficiency causally', () => {
  const e=loadEngine(),ref={bg3Id:'TEST_EXACT_MODIFIER'},compile=op=>{
    const result=e.bg3LifecycleCompileModifier(ref,{op,field:{role:'modifiers'},where:'fixture'},actor,{});
    assert.equal(result.ok,true,result.reason);return result.fx;
  },symbol=value=>({kind:'symbol',value}),integer=value=>({kind:'integer',value});
  const actor=hero('bg3-modifier-actor',{level:5,abilities:[{abilityId:'simple-only'}],inventory:[],equipment:{}}),
    target=hero('bg3-modifier-target',{resist:['рубящий'],hp:7,hpMax:20}),
    simpleOnly={id:'simple-only',n:'Simple training',mode:'passive',schemaVersion:6,mechanics:{schemaVersion:1,mode:'structured',role:'passive',
      proficiencies:{weapons:{simple:true,martial:false,names:[]}}}},
    longsword={id:'bg3-test-longsword',n:'Longsword',type:'weapon',dmg:'1d8',dmgType:'рубящий',slot:'MAIN_HAND',schemaVersion:6,
      source:{statsId:'WPN_Longsword'},mechanics:bg3TestMechanics({kind:'weapon'})};
  longsword.mechanics.profile.weapon={category:'martial',ranged:false,finesse:false,damage:{cnt:1,sides:8,mod:0,type:'рубящий'},damageTraits:{magical:false}};
  e.setState({chars:[actor,target],abilities:[simpleOnly],items:[longsword],activeCharId:actor.id});
  const baseAttack=e.weaponSpecOf(actor,longsword,e.targetInfoOf(`ally:${target.id}`),{}).rows.find(row=>row.type==='atk').mod;
  assert.equal(e.weaponProfHas(actor,longsword),false);

  const fx=[
    ...compile({op:'modifyCriticalThreshold',executable:true,amount:integer(1),args:[integer(1)]}),
    ...compile({op:'ignoreResistance',executable:true,args:[symbol('Slashing'),symbol('Resistant')]}),
    ...compile({op:'grantProficiency',executable:true,args:[symbol('Longswords')]}),
    ...compile({op:'modifyProficiencyBonus',executable:true,args:[symbol('Skill'),symbol('Perception')]}),
    ...compile({op:'modifyProficiencyBonus',executable:true,args:[symbol('SavingThrow'),symbol('Constitution')]}),
  ];
  actor.activeFx=[{uid:'exact-modifiers',k:'bg3-lifecycle',id:'exact-modifiers',label:'Exact BG3 modifiers',fx}];
  e.setState({chars:[actor,target],abilities:[simpleOnly],items:[longsword],activeCharId:actor.id});
  assert.equal(e.weaponProfHas(actor,longsword),true);
  assert.equal(e.fxSum(actor,'skill.Внимательность'),3);assert.equal(e.fxSum(actor,'save.con'),3);
  assert.equal(e.weaponSpecOf(actor,longsword,e.targetInfoOf(`ally:${target.id}`),{}).rows.find(row=>row.type==='atk').mod,
    baseAttack+3,'BG3-granted longsword proficiency adds the level-5 proficiency bonus');
  const attack=e.finalizeRollSpec({rows:[{key:'atk',type:'atk',natural:true,mod:0,required:true},{key:'dmg',type:'dmg',cnt:1,sides:8,mod:0,dmgType:'рубящий',required:true,requiredOnHit:true}],
    meta:{caster:actor,target:e.targetInfoOf(`ally:${target.id}`),dmgType:'рубящий',damageTags:{magical:false}}},{kind:'weapon',id:'fixture'});
  assert.equal(attack.meta.criticalThreshold,19);
  const hit=e.resolveOutcome(attack,{atk:19,dmg:6});assert.equal(hit.crit,true);assert.equal(hit.hit,true);
  assert.equal(hit.dmgTotal,6,'exact IgnoreResistance bypasses resistance but not the whole damage pipeline');

  const healingFx=compile({op:'maximizeHealing',executable:true,args:[symbol('Incoming')]});
  target.activeFx=[{uid:'maximize-healing',k:'bg3-lifecycle',id:'maximize-healing',label:'Periapt',fx:healingFx}];
  e.setState({chars:[actor,target],abilities:[simpleOnly],items:[longsword],activeCharId:actor.id});
  const healing=e.finalizeRollSpec({rows:[{key:'heal',type:'heal',cnt:2,sides:4,mod:2,required:true}],meta:{caster:actor,target:e.targetInfoOf(`ally:${target.id}`)}},{kind:'spell',id:'healing-fixture'}),
    healRow=healing.rows[0];
  assert.equal(healRow.fixed,true);assert.equal(healRow.maximized,true);assert.equal(healRow.mod,10);
  const healed=e.resolveOutcome(healing,{});assert.equal(healed.healTotal,10);
  assert.equal(e.validateFormulaValues(healing,{},healed).ok,true,'deterministically maximized healing asks for no fabricated die result');

  actor.activeFx=[];target.activeFx=[];e.setState({chars:[actor,target],abilities:[simpleOnly],items:[longsword],activeCharId:actor.id});
  const ordinary=e.finalizeRollSpec({rows:[{key:'atk',type:'atk',natural:true,mod:0,required:true},{key:'dmg',type:'dmg',cnt:1,sides:8,mod:0,dmgType:'рубящий',required:true,requiredOnHit:true}],
    meta:{caster:actor,target:e.targetInfoOf(`ally:${target.id}`),dmgType:'рубящий',damageTags:{magical:false}}},{kind:'weapon',id:'ordinary'}),ordinaryHit=e.resolveOutcome(ordinary,{atk:19,dmg:6});
  assert.equal(ordinary.meta.criticalThreshold,20);assert.equal(ordinaryHit.crit,false);assert.equal(ordinaryHit.dmgTotal,3);
});

test('BG3 real lifecycle catalog is exhaustively classified by the fail-closed runtime', () => {
  const repo=new URL('..',import.meta.url),readJson=relative=>JSON.parse(fs.readFileSync(new URL(relative,repo),'utf8')),
    current=selectedBg3Catalog.current,manifest=selectedBg3Catalog.manifest,items=[],programs=new Map();
  for(const shard of manifest.files.items)items.push(...readJson(shard.path).items);
  for(const shard of manifest.files.rules)for(const rule of readJson(shard.path).rules||[]){const program=rule.programs&&rule.programs[current.defaultRulesProfile];if(program){assert.equal(program.sourceProfile,current.defaultRulesProfile);programs.set(program.id,program);}}
  const refs=[];for(const item of items)for(const ref of item.mechanics&&item.mechanics.lifecyclePrograms||[])refs.push({item,ref});
  assert.equal(refs.length,manifest.counts.itemLifecyclePrograms.programs);
  const e=loadEngine(),runtimePrograms=e.bg3LifecycleProgramsMap([...programs]),coverage={total:refs.length,applied:0,eventReady:0,grantedReady:0,interruptReady:0,readyEmpty:0,blocked:0,byGate:{},statusByGate:{},blockedByReason:{},emptySamples:[]};
  for(const {item,ref} of refs){
    coverage.byGate[ref.gate]=(coverage.byGate[ref.gate]||0)+1;
    const gate=coverage.statusByGate[ref.gate]||(coverage.statusByGate[ref.gate]={applied:0,eventReady:0,grantedReady:0,interruptReady:0,readyEmpty:0,blocked:0});
    const compiled=e.bg3LifecycleCompileRow({it:item,ref},runtimePrograms);
    if(!compiled.ok){coverage.blocked++;gate.blocked++;coverage.blockedByReason[compiled.reason]=(coverage.blockedByReason[compiled.reason]||0)+1;continue;}
    if(compiled.fx&&compiled.fx.length){coverage.applied++;gate.applied++;}
    else if(compiled.granted&&compiled.granted.length){coverage.grantedReady++;gate.grantedReady++;}
    else if(compiled.interrupts&&compiled.interrupts.length){coverage.interruptReady++;gate.interruptReady++;}
    else if(ref.gate==='on-hit'){coverage.eventReady++;gate.eventReady++;}
    else if(ref.gate==='granted-action'){coverage.grantedReady++;gate.grantedReady++;}
    else{coverage.readyEmpty++;gate.readyEmpty++;if(coverage.emptySamples.length<20)coverage.emptySamples.push({itemId:item.id,refId:ref.id,gate:ref.gate,sourceField:ref.sourceField,opcodes:compiled.opcodes||[],projected:compiled.projected});}
  }
  assert.equal(coverage.applied+coverage.eventReady+coverage.grantedReady+coverage.interruptReady+coverage.readyEmpty+coverage.blocked,coverage.total);
  if(process.env.BG3_LIFECYCLE_COVERAGE==='1')console.log('BG3_LIFECYCLE_COVERAGE '+JSON.stringify(coverage));
  assert.equal(coverage.readyEmpty,0,'an active lifecycle ref is never silently accepted without an effect/event/action');
  const projectedRefs=refs.filter(({ref})=>!!ref.projection).length;
  if(projectedRefs===0)assert.deepEqual({total:coverage.total,applied:coverage.applied,eventReady:coverage.eventReady,
    grantedReady:coverage.grantedReady,interruptReady:coverage.interruptReady,readyEmpty:coverage.readyEmpty,blocked:coverage.blocked},
    {total:2777,applied:149,eventReady:0,grantedReady:0,interruptReady:98,readyEmpty:0,blocked:2530},
    'pre-projection catalog baseline stays exact until the atomic compiler rebuild publishes the lifecycle contract');
  else assert.ok(projectedRefs<=coverage.total,'projected lifecycle references remain exhaustively accounted');
});

test('BG3 real status-application actions are exhaustively compiled with exact lifecycle descriptors', () => {
  const repo=new URL('..',import.meta.url),readJson=relative=>JSON.parse(fs.readFileSync(new URL(relative,repo),'utf8')),
    current=selectedBg3Catalog.current,manifest=selectedBg3Catalog.manifest,
    prefix=`data/bg3/${current.catalogVersion}/`,items=[],roots=new Map(),programsByArtifact=new Map(),e=loadEngine();
  for(const shard of manifest.files.items)items.push(...readJson(shard.path).items);
  for(const shard of manifest.files.rootTemplatePrograms)for(const program of readJson(shard.path).programs||[])roots.set(program.id,program);
  for(const shard of manifest.files.rules){
    const artifact=String(shard.path).startsWith(prefix)?String(shard.path).slice(prefix.length):String(shard.path),
      tagged=e.bg3RuleArtifactPrograms(readJson(shard.path)).map(program=>({program,artifact}));
    programsByArtifact.set(artifact,tagged);
  }
  const rows=[];for(const item of items)for(const action of item.mechanics&&item.mechanics.actions||[])
    if(action&&action.handler==='bg3RuleProgram'&&action.program&&action.program.statusApplication)rows.push({item,action});
  const lifecycleRoles=new Set(['on-apply','modifiers','aura','aura-consequences','remove-guard','on-remove','on-tick']),
    coverage={catalogVersion:current.catalogVersion,manifestSha256:current.manifestSha256,total:rows.length,ready:0,blocked:0,
      withLifecycleSource:0,readyWithLifecycle:0,blockedWithLifecycle:0,descriptorActions:0,descriptors:0,
      byCategory:{},bySourceRole:{},byDescriptorRole:{},blockedByReason:{},blockedSamples:[]};
  for(const {item,action} of rows){
    const contract=action.program,projection=contract.projection||{},refs=[].concat(projection.entrypoints||[],projection.transitive||[]),
      statusRefs=refs.filter(ref=>ref&&ref.kind==='status'),artifacts=new Set(),addArtifact=value=>{if(value)artifacts.add(String(value));};
    addArtifact(contract.artifact);addArtifact(contract.statusApplication&&contract.statusApplication.artifact);addArtifact(contract.projectile&&contract.projectile.artifact);
    refs.forEach(ref=>addArtifact(ref&&ref.artifact));(contract.bg3LifecycleBindings||[]).forEach(binding=>{
      addArtifact(binding&&binding.sourceApplication&&binding.sourceApplication.artifact);addArtifact(binding&&binding.targetProgram&&binding.targetProgram.artifact);
      addArtifact(binding&&binding.projectionRef&&binding.projectionRef.artifact);
    });
    const root=roots.get(contract.id);for(const op of root&&root.consequences||[])if(op&&['invokeRuleProgram','invokeStatusProgram'].includes(op.op))addArtifact(op.artifact);
    const rulePrograms=[...artifacts].flatMap(artifact=>programsByArtifact.get(artifact)||[]),plan=e.bg3RuleProgramCompile(action,root,rulePrograms),
      category=String(item.source&&item.source.category||item.mechanics&&item.mechanics.profile&&item.mechanics.profile.kind||'unknown'),
      sourceRoles=[...new Set(statusRefs.flatMap(ref=>ref.roles||[]).filter(role=>lifecycleRoles.has(role)))],hasLifecycle=sourceRoles.length>0;
    const categoryBucket=coverage.byCategory[category]||(coverage.byCategory[category]={total:0,ready:0,blocked:0});categoryBucket.total++;
    sourceRoles.forEach(role=>coverage.bySourceRole[role]=(coverage.bySourceRole[role]||0)+1);
    if(hasLifecycle)coverage.withLifecycleSource++;
    if(plan.ok){
      coverage.ready++;categoryBucket.ready++;if(hasLifecycle)coverage.readyWithLifecycle++;
      if((plan.statusLifecycles||[]).length){coverage.descriptorActions++;coverage.descriptors+=plan.statusLifecycles.length;}
      const descriptorRoles=new Set();for(const descriptor of plan.statusLifecycles||[]){
        for(const [role,entries] of Object.entries(descriptor.fields||{}))if(Array.isArray(entries)&&entries.length)descriptorRoles.add(role);
        if((descriptor.statusPropertyFlags||[]).length)descriptorRoles.add('statusPropertyFlags');
        if(descriptor.stackId)descriptorRoles.add('stackId');if(descriptor.removeEvents)descriptorRoles.add('removeEvents');
        if(descriptor.tickType)descriptorRoles.add('tickType');if(descriptor.aura)descriptorRoles.add('aura');
      }
      descriptorRoles.forEach(role=>coverage.byDescriptorRole[role]=(coverage.byDescriptorRole[role]||0)+1);
    } else {
      coverage.blocked++;categoryBucket.blocked++;if(hasLifecycle)coverage.blockedWithLifecycle++;
      const reasons=[...new Set((plan.issues||[]).map(issue=>String(issue.reason||'unknown')))];
      reasons.forEach(reason=>coverage.blockedByReason[reason]=(coverage.blockedByReason[reason]||0)+1);
      if(coverage.blockedSamples.length<40)coverage.blockedSamples.push({itemId:item.id,actionId:action.id,statusId:contract.statusApplication.statusId,
        category,reasons,sourceRoles});
    }
  }
  assert.ok(coverage.total>0,'the active atomic catalog exposes status-application actions to the exhaustive audit');
  assert.equal(coverage.ready+coverage.blocked,coverage.total);
  assert.equal(coverage.readyWithLifecycle+coverage.blockedWithLifecycle,coverage.withLifecycleSource);
  assert.ok(coverage.descriptorActions>0,'source-backed lifecycle semantics compile into runtime descriptors');
  if(process.env.BG3_STATUS_LIFECYCLE_COVERAGE==='1')console.log('BG3_STATUS_LIFECYCLE_COVERAGE '+JSON.stringify(coverage));
});

test('BG3: every catalog variant passes actual engine contracts and weapon uses only player-entered results', () => {
  const repo = new URL('..', import.meta.url);
  const readJson = relative => JSON.parse(fs.readFileSync(new URL(relative, repo), 'utf8'));
  const current = selectedBg3Catalog.current;
  const manifest = selectedBg3Catalog.manifest;
  const items = [];

  for (const shard of manifest.files.items) {
    const payload = readJson(shard.path);
    assert.equal(payload.catalogVersion, current.catalogVersion, shard.path);
    assert.equal(payload.count, payload.items.length, shard.path);
    items.push(...payload.items);
  }
  assert.equal(items.length, manifest.counts.items);
  assert.equal(new Set(items.map(item => item.id)).size, items.length);

  const e = loadEngine();
  for (const item of items) {
    const m = item.mechanics;
    assert.deepEqual(plain(e.mechanicsErrors(m, 'item')), [], `${item.id}: mechanics`);
    assert.deepEqual(plain(e.itemUseSchemaErrors(m.actions, m.resource)), [], `${item.id}: actions`);
    assert.deepEqual(plain(e.itemInteractionSchemaErrors(m.interactions)), [], `${item.id}: interactions`);
    assert.deepEqual(plain(e.itemResourceSchemaErrors(m.resource)), [], `${item.id}: resource`);
    assert.deepEqual(plain(e.itemCampaignRuleSchemaErrors(m.campaignRules)), [], `${item.id}: campaign rules`);
  }

  /* Profile/mode/classification signatures ensure upgradeItem sees diverse external records. */
  const representatives = [], signatures = new Set();
  for (const item of items) {
    const m = item.mechanics || {}, source = item.source || {};
    const signature = [m.mode, m.profile && m.profile.kind, source.classification, !!(m.actions || []).length,
      !!(m.interactions || []).length, !!m.resource].join('|');
    if (!signatures.has(signature)) {
      signatures.add(signature);
      representatives.push(item);
    }
    if (representatives.length === 24) break;
  }
  for (const item of items) {
    if (representatives.length === 24) break;
    if (!representatives.includes(item)) representatives.push(item);
  }
  assert.equal(representatives.length, 24);
  for (const raw of representatives) {
    const cloned = plain(raw), before = plain(cloned.mechanics);
    e.upgradeItem(cloned);
    assert.equal(cloned.schemaVersion, 6, `${raw.id}: item schema`);
    assert.equal(cloned.mechanics.origin, 'explicit', `${raw.id}: explicit mechanics`);
    assert.equal(cloned.mechanics.schemaVersion, 1, `${raw.id}: mechanics schema`);
    assert.deepEqual(plain(cloned.mechanics.profile), before.profile, `${raw.id}: profile must not be recompiled`);
  }

  const weapon = items.find(item => item.source && item.source.rootTemplateUuid === '00353281-1abb-4de6-893b-d6bf7f748da8'
      && !(item.mechanics&&item.mechanics.lifecyclePrograms||[]).length)
    || items.find(item => item.mechanics && item.mechanics.profile && item.mechanics.profile.kind === 'weapon'
      && item.mechanics.profile.weapon && item.mechanics.profile.weapon.damage.sides > 0
      && !(item.mechanics.lifecyclePrograms||[]).length);
  assert.ok(weapon, 'the catalog must contain a BG3 weapon with a damage roll');
  const target = plain(e.seedFoesDB().find(foe => foe.id === 'foe_goblin_scout'));
  target.hp = target.hpMax = 40;
  const actor = hero('bg3-weapon-user', {
    level: 5,
    ab: {str: 16, dex: 14, con: 10, int: 10, wis: 10, cha: 10},
    inventory: [{id: 'bg3-weapon-entry', itemId: weapon.id, qty: 1}],
    equipment: {MAIN_HAND: 'bg3-weapon-entry'},
  });
  e.setState({chars: [actor], items: [weapon], foes: [target], activeCharId: actor.id});
  const targetKey = `foe:${target.id}`;
  const spec = e.weaponSpecOf(actor, weapon, e.targetInfoOf(targetKey), {entryId: 'bg3-weapon-entry', mode: 'melee'});
  const damageRow = spec.rows.find(row => row.key === 'dmg');
  assert.ok(damageRow, 'the BG3 weapon profile must produce a structured damage row');
  const hpBeforeMiss = target.hp, qtyBeforeMiss = actor.inventory[0].qty;
  const miss = productionWeaponConfirmation(e,actor,'bg3-weapon-entry',targetKey,freshSpec=>{const attack=freshSpec.rows.find(row=>row.type==='atk'),damage=freshSpec.rows.find(row=>row.type==='dmg');return {[attack.key]:1,[damage.key]:Math.max(1,damage.cnt||1)};},{mode:'melee',within5:true}).rolls;
  assert.equal(miss.hit, false);
  assert.equal(e.weaponAttackApply('bg3-weapon-entry', actor.id, targetKey, miss), true);
  assert.equal(target.hp, hpBeforeMiss, 'a miss deals no damage');
  assert.equal(actor.inventory[0].qty, qtyBeforeMiss, 'a miss consumes no invalid weapon resource');

  const hpBeforeHit = target.hp;
  const hit = productionWeaponConfirmation(e,actor,'bg3-weapon-entry',targetKey,freshSpec=>{const attack=freshSpec.rows.find(row=>row.type==='atk'),damage=freshSpec.rows.find(row=>row.type==='dmg');return {[attack.key]:19,[damage.key]:Math.max(1,damage.cnt||1)};},{mode:'melee',within5:true}).rolls;
  assert.equal(hit.hit, true);
  assert.ok(hit.dmgTotal > 0);
  assert.equal(e.weaponAttackApply('bg3-weapon-entry', actor.id, targetKey, hit), true);
  assert.equal(target.hp, hpBeforeHit - hit.dmgTotal, 'a hit applies the entered structured damage');
});

