  assert.equal(state.bg3TadpoleState.facts.tadpoleTreeEnabled,true);assert.equal(state.bg3TadpoleState.globalFlags['GLO_Tadpole_State_TreeUnlocked_f7691d3d-345b-4984-8eed-6f238a9f84be'],true);
