function installTransmuterCase({family='ACID',profile='standard',qty=1,actorId='transmuter-source',recipient=true,serial='stone'}={}) {
  const e=loadEngine(),item=transmuterItem(family,profile,serial),entry={id:`entry-${serial}`,itemId:item.id,qty,notes:'exact concrete instance',att:true},source=hero(actorId,{inventory:[entry],equipment:{MAIN_HAND:entry.id}}),other=recipient?hero(`${actorId}-recipient`):null;
  e.setState({chars:other?[source,other]:[source],activeCharId:source.id});e.bg3InventoryStatusTransitionTestInstall([item],profile);return {e,item,entry,source,recipient:other};
}
function gmTransitionSelections(cause,overrides={}) {return {cause,qty:1,gmConfirmed:true,evidence:'GM witnessed the exact campaign inventory cause',transactionId:`tx-${cause}-${overrides.suffix||'one'}`,...overrides};}

test('Transmuter Stone: all seven exact Standard status families validate without changing sourceBlocked catalog truth', () => {
  for(const profile of ['standard']){
    const items=TRANSMUTER_STATUS_FAMILIES.map((family,index)=>transmuterItem(family,profile,`${profile}-${family}-${index}`)),e=loadEngine(),actor=hero(`all-${profile}`,{inventory:items.map((item,index)=>({id:`row-${index}`,itemId:item.id,qty:1}))});e.setState({chars:[actor]});e.bg3InventoryStatusTransitionTestInstall(items,profile);
    for(let index=0;index<items.length;index++){const item=items[index],family=TRANSMUTER_STATUS_FAMILIES[index],rows=e.bg3InventoryStatusTransitionRowsOf(item);assert.equal(rows.length,1);const checked=e.bg3InventoryStatusTransitionDescriptorCheck(item,rows[0].ref,rows[0].descriptor);assert.equal(checked.ok,true,`${profile}/${family}: ${checked.reason}`);assert.equal(checked.structurallyExact,true);assert.equal(checked.sourceBlocked,true);assert.equal(checked.automaticLifecycle,false);assert.equal(checked.gmCauseRequired,true);assert.equal(checked.gmReady,family!=='DARKNESS');assert.equal(rows[0].descriptor.runtimeReady,false);assert.equal(rows[0].descriptor.executable,false);assert.deepEqual(plain(rows[0].descriptor.triggerBinding.inventoryMutationKinds),[]);}
  }
  const e=loadEngine(),constitution=transmuterItem('ACID','standard','constitution');constitution.mechanics.lifecyclePrograms[0].bg3Id='TRANSMUTERS_STONE_CONSTITUTION';delete constitution.mechanics.lifecyclePrograms[0].inventoryTransition;const actor=hero('constitution',{inventory:[{id:'constitution-entry',itemId:constitution.id,qty:1}]});e.setState({chars:[actor]});e.bg3InventoryStatusTransitionTestInstall([constitution]);assert.equal(e.bg3InventoryStatusTransitionRowsOf(constitution).length,0);assert.equal(e.bg3InventoryStatusTransitionCarrier(actor,actor.inventory[0]),null);assert.equal(e.bg3InventoryMutationGuard(actor,[{entryId:'constitution-entry',qty:1}],{context:'constitution'}).ok,true,'Constitution has no fabricated removal edge');
});

test('Transmuter Stone: exact GM removal commits once, persists evidence, and its hidden priority-10 marker expires after one round', async () => {
  for(const family of TRANSMUTER_STATUS_FAMILIES.filter(value=>value!=='DARKNESS')){const {e,source,entry}=installTransmuterCase({family,recipient:false,serial:`remove-${family}`}),plan=e.bg3InventoryStatusTransitionPlanFor(source.id,entry.id,gmTransitionSelections('campaign-inventory-removal',{suffix:family}));assert.equal(plan.ok,true,`${family}: ${plan.reason}`);assert.equal(plan.triggered,true);assert.equal(plan.sourceEvidence.runtimeReady,false);assert.equal(plan.sourceEvidence.sourceBlocked,true);assert.equal(plan.causeEvidence.notBg3OnDestroy,true);const done=await e.bg3InventoryStatusTransitionCommit(plan);assert.equal(done.ok,true,`${family}: ${done.reason}`);assert.equal(source.inventory.length,0);assert.equal(source.equipment.MAIN_HAND,undefined);assert.equal(done.marker.bg3Status,`TRANSMUTERS_STONE_${family}_TECHNICAL`);assert.equal(done.marker.bg3StackId,`TRANSMUTERS_STONE_${family}`);assert.equal(done.marker.bg3StackPriority,10);assert.equal(done.marker.bg3HiddenStatus,true);assert.deepEqual(plain(done.marker.bg3StatusPropertyFlags),['DisableOverhead','DisableCombatlog','DisablePortraitIndicator']);assert.equal(source.bg3InventoryStatusTransitionHistory.length,1);assert.equal(source.bg3InventoryStatusTransitionHistory[0].manifestSha256,'a'.repeat(64));assert.equal(source.bg3InventoryStatusTransitionHistory[0].sourceBuildId,'test-build');assert.match(source.bg3InventoryStatusTransitionHistory[0].artifactEvidence.sha256,/^[0-9a-f]{64}$/);assert.equal(source.bg3InventoryStatusTransitionHistory[0].artifactEvidence.onRemoveRaw,plan.sourceEvidence.onRemoveRaw);assert.equal((await e.bg3InventoryStatusTransitionCommit(plan)).replay,true);assert.equal(e.advanceFxRound(1),true);assert.equal(source.activeFx.some(row=>row.bg3Status===`TRANSMUTERS_STONE_${family}_TECHNICAL`),false,'technical marker must actually expire, not merely carry metadata');}
  const dark=installTransmuterCase({family:'DARKNESS',recipient:false,serial:'darkness-block'}),blocked=dark.e.bg3InventoryStatusTransitionPlanFor(dark.source.id,dark.entry.id,gmTransitionSelections('campaign-inventory-removal',{suffix:'dark'}));assert.equal(blocked.ok,false);assert.equal(blocked.structurallyExact,true);assert.equal(blocked.gmCauseRequired,true);assert.equal(blocked.reason,'inventory-static-modifiers-not-runtime-ready');assert.deepEqual(plain(blocked.blockers),['unsupported-functor:DarkvisionRangeMin','unsupported-functor:ActiveCharacterLight']);assert.equal(dark.source.inventory[0].qty,1);
});

test('Transmuter Stone: partial stacks and duplicate carriers keep status; only final qualifying loss applies the former-holder marker', async () => {
  const partial=installTransmuterCase({family:'FIRE',qty:2,serial:'partial'}),p1=partial.e.bg3InventoryStatusTransitionPlanFor(partial.source.id,partial.entry.id,gmTransitionSelections('exact-actor-transfer',{recipientId:partial.recipient.id,suffix:'partial',qty:1}));assert.equal(p1.ok,true,p1.reason);assert.equal(p1.triggered,false);const first=await partial.e.bg3InventoryStatusTransitionCommit(p1);assert.equal(first.ok,true);assert.equal(first.triggered,false);assert.equal(partial.source.inventory[0].qty,1);assert.equal(partial.recipient.inventory[0].qty,1);assert.equal(partial.source.activeFx.length,0);assert.notEqual(partial.recipient.inventory[0],partial.entry,'split recipient entry is a deep concrete clone');assert.equal(partial.e.bg3LifecycleRows(partial.recipient)[0].active,true,'recipient gets an ordinary active direct inventory carrier');
  const p2=partial.e.bg3InventoryStatusTransitionPlanFor(partial.source.id,partial.entry.id,gmTransitionSelections('campaign-inventory-removal',{suffix:'partial-final'}));assert.equal(p2.triggered,true);assert.equal((await partial.e.bg3InventoryStatusTransitionCommit(p2)).ok,true);assert.ok(partial.source.activeFx.some(row=>row.bg3Status==='TRANSMUTERS_STONE_FIRE_TECHNICAL'));
  const e=loadEngine(),a=transmuterItem('COLD','standard','duplicate-a'),b=transmuterItem('COLD','standard','duplicate-b'),source=hero('duplicates',{inventory:[{id:'dup-a',itemId:a.id,qty:1},{id:'dup-b',itemId:b.id,qty:1}]});e.setState({chars:[source]});e.bg3InventoryStatusTransitionTestInstall([a,b]);const duplicatePlan=e.bg3InventoryStatusTransitionPlanFor(source.id,'dup-a',gmTransitionSelections('campaign-inventory-removal',{suffix:'duplicate'}));assert.equal(duplicatePlan.ok,true);assert.equal(duplicatePlan.triggered,false);assert.equal((await e.bg3InventoryStatusTransitionCommit(duplicatePlan)).ok,true);assert.equal(source.inventory[0].id,'dup-b');assert.equal(source.activeFx.length,0);
});

test('Transmuter Stone: exact actor transfer is one atomic world transaction with independent entry identity and former-holder-only marker', async () => {
  const {e,source,recipient,entry}=installTransmuterCase({family:'LIGHTNING',serial:'transfer'}),plan=e.bg3InventoryStatusTransitionPlanFor(source.id,entry.id,gmTransitionSelections('exact-actor-transfer',{recipientId:recipient.id,suffix:'transfer'}));assert.equal(plan.ok,true,plan.reason);const done=await e.bg3InventoryStatusTransitionCommit(plan);assert.equal(done.ok,true,done.reason);assert.equal(source.inventory.length,0);assert.equal(source.equipment.MAIN_HAND,undefined);assert.equal(recipient.inventory.length,1);assert.equal(recipient.inventory[0].id,entry.id);assert.equal(recipient.inventory[0].itemId,entry.itemId);assert.notEqual(recipient.inventory[0],entry);recipient.inventory[0].notes='recipient changed';assert.equal(entry.notes,'exact concrete instance','recipient clone shares no mutable object with former holder');assert.equal(e.bg3InventoryStatusTransitionCarrier(recipient,recipient.inventory[0]).check.ok,true);assert.equal(e.bg3LifecycleRows(recipient)[0].active,true);assert.equal(e.bg3LifecycleFxSources(recipient).length,1,'recipient static carrier is reachable synchronously before commit returns ok');assert.ok(source.activeFx.some(row=>row.bg3Status==='TRANSMUTERS_STONE_LIGHTNING_TECHNICAL'));assert.equal(recipient.activeFx.length,0);assert.equal(done.lifecycle.length,2);assert.equal(done.lifecycle[0].expectedCarrierQty,0);assert.equal(done.lifecycle[1].rows[0].status,'applied');assert.deepEqual(plain(source.bg3InventoryStatusTransitionHistory.map(row=>row.role)),['former-holder']);assert.deepEqual(plain(recipient.bg3InventoryStatusTransitionHistory.map(row=>row.role)),['recipient']);assert.equal(recipient.bg3InventoryStatusTransitionHistory[0].lifecycleEvidence.rows[0].status,'applied');
});

