test('BG3 granted weapon actions: attack and damage outcomes are recomputed only from the exact player-entered formula ledger', () => {
  const e=loadEngine(),world=grantedWeaponRuntimeWorld(e,'Target_OpeningAttack');world.actor.activeFx.push({uid:'exact-attack-adv-source',k:'test',id:'attack-adv',label:'exact attack advantage',fx:[{stat:'attack',mode:'adv',value:1,consume:'roll'}]});e.bg3GrantedWeaponTestInvalidateFx();assert.equal(e.combatStart([{kind:'ally',id:world.actor.id,nat:20},{kind:'ally',id:world.target.id,nat:10},{kind:'foe',id:world.dummy.id,nat:1}],'granted resolution proof'),true);const prepared=grantedWeaponRolls(e,world,{saveD20:20,damage:4}),input=prepared.rolls.bg3GrantedResolutionInput,atk=prepared.spec.rows.find(row=>row.type==='atk'),dmg=prepared.spec.rows.find(row=>row.type==='dmg');assert.equal(atk.adv,1);assert.equal(input.entered[atk.key],12);assert.equal(input.entered[atk.key+'_2'],12);assert.equal(input.entered[dmg.key],4);{const plan=e.bg3GrantedWeaponPlan(world.actor,world.virtual,world.targetKey,prepared.rolls);assert.equal(plan.ok,true,plan.reason);}
  for(const mutate of [
    rolls=>delete rolls.bg3GrantedResolutionInput,
    rolls=>{rolls.bg3GrantedResolutionInput.formulaSha256='0'.repeat(64);},
    rolls=>delete rolls.bg3GrantedResolutionInput.entered[atk.key+'_2'],
    rolls=>{rolls.bg3GrantedResolutionInput.entered.unknownDie=1;},
    rolls=>{rolls.bg3GrantedResolutionInput.entered[dmg.key]=5;},
    rolls=>{rolls.hit=!rolls.hit;},
    rolls=>{rolls.dmgTotal++;},
    rolls=>{rolls.damageParts[0].total++;}
  ]){const tampered=plain(prepared.rolls);mutate(tampered);assert.equal(e.bg3GrantedWeaponPlan(world.actor,world.virtual,world.targetKey,tampered).ok,false);}
});

