test('BG3 exact lesser SpellSaveDC lifecycle stacks equipped Standard variants and feeds real spell saves only', async () => {
  for(const profile of ['standard']){
    const fixture=lesserSpellSaveDcCatalog(profile),e=loadEngine(()=>0,fixture.fetch);e.bg3CatalogUseRefs([{id:'bg3',version:fixture.version,profile}]);await e.bg3CatalogEnsureIndex();
    const spells=e.seedSpellsDB(),sacred=spells.find(spell=>spell.id==='sp_sacred_flame'),bolt=spells.find(spell=>spell.id==='sp_guiding_bolt'),foe=plain(e.seedFoesDB()[0]),
      actor=hero(`lesser-spell-dc-${profile}`,{spellAb:'wis',inventory:fixture.items.map((item,index)=>({id:`dc-entry-${index}`,itemId:item.id,qty:1})),equipment:{HEAD:'dc-entry-0',BODY:'dc-entry-1'}});
    assert.ok(sacred);assert.ok(bolt);e.setState({chars:[actor],items:fixture.items,spells,foes:[foe],activeCharId:actor.id});const baseDc=8+3+3,baseAtk=3+3;
    let state=await e.bg3LifecycleReconcile(actor);assert.equal(state.ok,true,state.reason);assert.equal(state.rows.filter(row=>row.status==='applied').length,2);assert.equal(state.rows.filter(row=>row.status==='inactive').length,1);
    assert.equal(e.fxSum(actor,'spell.dc'),2);assert.equal(e.spellDC(actor),baseDc+2);assert.equal(e.spellAtk(actor),baseAtk,'SpellSaveDC never leaks into spell attack');
    const target=e.targetInfoOf(`foe:${foe.id}`),saveSpec=e.rollSpecOf(sacred,{caster:actor,kind:'spell',target}),saveRow=saveSpec.rows.find(row=>row.type==='save'),attackSpec=e.rollSpecOf(bolt,{caster:actor,kind:'spell',target}),attackRow=attackSpec.rows.find(row=>row.type==='atk');
    assert.ok(saveRow,'seeded Sacred Flame produces a real save row');assert.equal(saveRow.dc,baseDc+2);assert.equal(saveSpec.meta.dc,baseDc+2);assert.ok(attackRow,'seeded Guiding Bolt produces a real spell attack');assert.equal(attackRow.mod,baseAtk);
    const fixedUse={id:`fixed-dc-${profile}`,handler:'bg3RuleProgram',program:{id:`fixed-dc-program-${profile}`}},dynamicUse={id:`dynamic-dc-${profile}`,handler:'bg3RuleProgram',program:{id:`dynamic-dc-program-${profile}`}};
    e.bg3RuleProgramInstall(fixedUse,{ok:true,resolution:{kind:'save',ability:'dex',dc:{kind:'fixed',value:17}},damage:[]});e.bg3RuleProgramInstall(dynamicUse,{ok:true,resolution:{kind:'save',ability:'dex',dc:{kind:'spell'}},damage:[]});
    assert.equal(e.bg3RuleProgramEffectiveUse(fixedUse,actor,target,{}).save.dc,17,'an explicitly fixed BG3 DC is never modified');assert.equal(e.bg3RuleProgramEffectiveUse(dynamicUse,actor,target,{}).save.dc,baseDc+2,'a source spell DC uses the central spellDC function');
    delete actor.equipment.BODY;state=await e.bg3LifecycleReconcile(actor);assert.equal(state.ok,true);assert.equal(e.fxSum(actor,'spell.dc'),1);assert.equal(e.spellDC(actor),baseDc+1);assert.equal(e.spellAtk(actor),baseAtk);
    actor.equipment={};state=await e.bg3LifecycleReconcile(actor);assert.equal(state.ok,true);assert.equal(e.fxSum(actor,'spell.dc'),0);assert.equal(e.spellDC(actor),baseDc);assert.equal(e.spellAtk(actor),baseAtk);
  }
});

test('BG3 lesser SpellSaveDC adapter rejects wrong authority, profile, source AST and every non-exact amount', () => {
  const e=loadEngine(),actor=hero('lesser-spell-dc-validation',{spellAb:'wis'});assert.equal(e.bg3CatalogUseRefs([{id:'bg3',version:'bg3-894-v1',profile:'standard'}]),true);e.setState({chars:[actor],activeCharId:actor.id});
  const build=()=>{const program=lesserSpellSaveDcProgram('standard'),field=program.fields[0],ref=lesserSpellSaveDcRef('standard','validation');return {ref,program,field,row:{program,field,op:field.bytecode[0],where:'Boosts[0]'}};},
    compile=mutate=>{const fixture=build();if(mutate)mutate(fixture);return e.bg3LifecycleCompileModifier(fixture.ref,fixture.row,actor,{c:actor});};
  const exact=compile();assert.equal(exact.ok,true,exact.reason);assert.deepEqual(plain(exact.fx),[{stat:'spell.dc',mode:'add',value:1,note:`BG3 ${LESSER_SPELL_SAVE_DC_SOURCE.bg3Id}`}]);
  const rejected=[
    fixture=>{fixture.ref.bg3Id='MAG_SpellSaveDC_Enchantment_Passive';},
    fixture=>{fixture.ref.sourceProfile='honour';},
    fixture=>{fixture.program.sourceProfile='honour';},
    fixture=>{fixture.program.bg3SourceRule.sourceProfile='honour';},
    fixture=>{fixture.program.bg3SourceRule.ruleId='forged-rule';},
    fixture=>{fixture.program.bg3SourceRule.properties.Boosts='SpellSaveDC(2)';},
    fixture=>{fixture.program.bg3SourceRule.directProperties.Boosts='SpellSaveDC(2)';},
    fixture=>{fixture.field.raw='SpellSaveDC(2)';},
    fixture=>{fixture.field.ast.args[0].value=2;},
    fixture=>{fixture.row.op.bg3Functor='GenericSaveDC';},
    fixture=>{fixture.row.op.phase='validation';},
    fixture=>{fixture.row.op.args=[];},
    fixture=>{fixture.row.op.args=[{kind:'integer',value:1},{kind:'integer',value:1}];},
    fixture=>{fixture.row.op.args=[{kind:'integer',value:2}];},
    fixture=>{fixture.row.op.args=[{kind:'integer',value:'1'}];},
    fixture=>{fixture.row.op.args=[{kind:'number',value:1}];},
    fixture=>{fixture.row.op.args=[{kind:'symbol',value:'SpellCastingAbilityModifier'}];},
    fixture=>{fixture.row.op.amount={kind:'integer',value:1};}
  ];
  for(const mutate of rejected){const result=compile(mutate);assert.equal(result.ok,false);assert.equal(result.fx,undefined,'a rejected SpellSaveDC opcode never leaks a partial modifier');}
  assert.match(compile(rejected[0]).reason,/source-not-authorized/);assert.match(compile(rejected[12]).reason,/exact-signature-mismatch/);
});

