function selectedBg3FileFetch(manifestRawOverride=''){
  const selectedManifestUrl=`data/bg3/${selectedBg3Catalog.current.catalogVersion}/manifest.json`;
  return async url=>{
    const relative=String(url||'').replace(/\\/g,'/').replace(/^\.\//,'');if(!relative.startsWith('data/bg3/')||relative.includes('..'))return {ok:false,status:404,text:async()=>'',json:async()=>({})};
    try{
      const raw=manifestRawOverride&&relative===selectedManifestUrl?manifestRawOverride:fs.readFileSync(new URL('../'+relative,import.meta.url),'utf8');
      return {ok:true,status:200,text:async()=>raw,json:async()=>JSON.parse(raw)};
    }catch(_error){return {ok:false,status:404,text:async()=>'',json:async()=>({})};}
  };
}

