function productionBg3ItemPresentationObservedFetch(options={}){
  const base=selectedBg3FileFetch(),calls=[];let enteredResolve,releaseResolve,released=false,tamperRemaining=options.tamperOnce?1:Number.POSITIVE_INFINITY;
  const entered=new Promise(resolve=>{enteredResolve=resolve;}),gate=new Promise(resolve=>{releaseResolve=resolve;});
  const fetch=async url=>{const relative=String(url||'').replace(/\\/g,'/').replace(/^\.\//,'');calls.push(relative);
    if(options.gatePath&&relative.endsWith(options.gatePath)){enteredResolve(relative);await gate;}
    const response=await base(url);if(!response.ok||!options.tamperPath||!relative.endsWith(options.tamperPath)||tamperRemaining<=0)return response;
    tamperRemaining--;const payload=JSON.parse(await response.text());if(typeof options.tamper==='function')options.tamper(payload,relative);else payload.__tampered=true;const raw=JSON.stringify(payload);
    return {ok:true,status:200,text:async()=>raw,json:async()=>JSON.parse(raw)};
  };
  return {fetch,calls,entered,release(){if(!released){released=true;releaseResolve();}}};
}
async function productionBg3ItemPresentationWorld(observed=productionBg3ItemPresentationObservedFetch(),profile='standard',engineOptions={}){
  const e=loadEngine(()=>0,observed.fetch,null,null,engineOptions),actor=hero('production-item-presentation-'+profile,{inventory:[]});e.setState({chars:[actor],items:e.seedItemsDB(),activeCharId:actor.id});
  assert.equal(e.bg3CatalogUseRefs([{id:'bg3',version:selectedBg3Catalog.current.catalogVersion,profile,manifestSha256:selectedBg3Catalog.current.manifestSha256}]),true);await e.bg3CatalogEnsureIndex();return {e,actor,observed,profile};
}

