test('real Greater Health effects follow the NECK equipment lifecycle and fully roll back on removal',async()=>{
  const {e,actor}=await productionBg3ItemPresentationWorld();await e.bg3CatalogHydrate([BG3_GREATER_HEALTH_AMULET]);const amulet=e.bg3LearnSpellTestCatalogItem(BG3_GREATER_HEALTH_AMULET),entry={id:'greater-health-runtime-entry',itemId:BG3_GREATER_HEALTH_AMULET,qty:1};assert.ok(amulet);assert.equal(amulet.slot,'NECK');actor.ab.con=10;actor.inventory=[entry];actor.equipment={};e.setState({chars:[actor],items:[amulet],activeCharId:actor.id});
  const conEffects=()=>e.charFxAll(actor).filter(effect=>effect.stat==='ab.con'||effect.stat==='save.con');

  assert.equal(e.eAb(actor,'con'),10,'carrying the amulet does not apply wearable effects');assert.equal(conEffects().some(effect=>effect.stat==='save.con'&&effect.mode==='adv'),false);
  e.invEquipToggle(entry.id);assert.equal(actor.equipment.NECK,entry.id);assert.equal(e.eAb(actor,'con'),23,'equipping the exact NECK entry applies AbilityOverrideMinimum(Constitution, 23)');let effects=conEffects();assert.equal(effects.filter(effect=>effect.stat==='ab.con'&&effect.mode==='min'&&effect.value===23).length,1);assert.equal(effects.filter(effect=>effect.stat==='save.con'&&effect.mode==='adv').length,1,'the saved BG3 Boosts advantage is active while worn');
  e.invEquipToggle(entry.id);assert.equal(actor.equipment.NECK,undefined);assert.equal(e.eAb(actor,'con'),10,'removing the amulet restores the underlying ability score');effects=conEffects();assert.equal(effects.some(effect=>effect.stat==='ab.con'),false);assert.equal(effects.some(effect=>effect.stat==='save.con'&&effect.mode==='adv'),false,'removal leaves no stale saving-throw advantage');
});

