async function realBg3ArrowPrepareProgram(world){const {e,useId}=world;await e.bg3CatalogEnsureIndex();await e.bg3CatalogHydrate([REAL_BG3_ARROW_MANY_TARGETS.itemId]);const item=e.bg3LearnSpellTestCatalogItem(REAL_BG3_ARROW_MANY_TARGETS.itemId),use=e.itemUseOf(item,useId);assert.ok(item&&use);assert.ok(await e.bg3RuleProgramPrepare(use));await realBg3ArrowQuiesce(world);return {item,use};}
function realBg3ArrowSelect(world){const {e,actor,ally,foes,weaponEntry}=world;e.setElementValue('castTarget','ally:'+ally.id);e.setElementValue('castWeapon',weaponEntry.id);for(let i=0;i<3;i++)e.setElementValue('castBg3ArrowExtra'+(i+1),'foe:'+foes[i].id);assert.equal(e.castConfirm(),true,JSON.stringify({audit:e.bg3ItemArrowAudit(),error:e.elementText('castErr'),status:e.elementText('status')}));return ['ally:'+ally.id,...foes.map(foe=>'foe:'+foe.id)];}
function realBg3ArrowEnterFour(world,{naturals=[19,19,19,19],damageResults=null,elementalInfusionResults=null,capture=true,onSpec=null}={}){const {e}=world,targetOrder=realBg3ArrowSelect(world);for(let order=0;order<4;order++){e.castDistanceSet('far');const spec=e.castState().spec,natural=naturals[order],values={};assert.ok(spec,'shot '+order+' formula');assert.equal(spec.meta.bg3ArrowOrder,order);if(onSpec)onSpec(spec,order);for(const row of spec.rows)if(row.required){if(row.type==='atk')values[row.key]=natural;else if(natural===1&&row.requiredOnHit)values[row.key]=null;else if(row.key==='bg3_elemental_infusion'&&elementalInfusionResults)values[row.key]=elementalInfusionResults[order];else if(row.type==='dmg'&&damageResults)values[row.key]=damageResults[order];else values[row.key]=row.natural?10:Math.max(1,(+row.cnt||1)*(natural===20&&row.type==='dmg'?2:1));}e.bg3ItemFormulaSetValues(values);if(capture&&order===3)e.bg3ItemFormulaCaptureNextDispatch(true);const result=e.castFormulaConfirm();assert.equal(result,order<3,JSON.stringify({order,natural,audit:e.bg3ItemArrowAudit(),error:e.elementText('castErr')}));}return {targetOrder,args:e.bg3ItemFormulaLastDispatch(),audit:e.bg3ItemArrowAudit()};}
function assertBg3ArrowLifecycleRuntimeSame(before,after,label){for(const key of ['byChar','pendingMap','state','pending','equipmentBindings','hitTokens','hitTokenOrder','statusTokens','statusTokenOrder','grantedLocks','githbornTokens','githbornTokenOrder','githbornLocks'])assert.equal(after[key],before[key],label+' '+key+' identity');for(const key of ['equipmentBindingsSize','hitTokensSize','statusTokensSize','grantedLocksSize','githbornTokensSize','githbornLocksSize'])assert.equal(after[key],before[key],label+' '+key);for(const key of ['hitTokenOrderValues','statusTokenOrderValues','githbornTokenOrderValues'])assert.deepEqual(Array.from(after[key]),Array.from(before[key]),label+' '+key);}
async function realBg3ArrowQuiesce(world){const before=world.e.bg3ItemArrowTestLifecycleRuntimeSnapshot(world.actor),pending=before.pending;if(pending)await pending;await Promise.resolve();const after=world.e.bg3ItemArrowTestLifecycleRuntimeSnapshot(world.actor);assert.equal(after.pending,null,'Arrow private open requires a quiescent lifecycle runtime');return after;}
async function realBg3ArrowElementalWorld({profile='standard',charged=false}={}){const ringEntry={id:'real-bg3-arrow-elemental-ring',itemId:ELEMENTAL_INFUSION_TEST.itemId,qty:1},world=await realBg3ArrowPhaseOneWorld({profile,extraInventory:[ringEntry],extraEquipment:{RING_L:ringEntry.id},includeFireBolt:true}),{e,actor,ally,spells}=world;await e.bg3CatalogEnsureIndex();await e.bg3CatalogHydrate([REAL_BG3_ARROW_MANY_TARGETS.itemId,ELEMENTAL_INFUSION_TEST.itemId]);let runtime=await e.bg3LifecycleReconcile(actor);assert.equal(runtime.ok,true,runtime.reason);assert.equal(runtime.rows.length,1,JSON.stringify(runtime.rows));assert.equal(runtime.rows[0].itemId,ELEMENTAL_INFUSION_TEST.itemId);assert.equal(runtime.rows[0].status,'event-ready',runtime.rows[0].reason);if(charged){const spell=spells[0],plan=e.bg3ElementalInfusionTestSpellPlan(actor,spell,[{target:'ally:'+ally.id,rolls:elementalDamage('огонь',5)}],'private-arrow-elemental-'+profile);assert.equal(plan.ok,true,plan.reason);const applied=e.bg3LifecycleSpellDamageCommit(plan);assert.equal(applied.ok,true,applied.reason);runtime=await e.bg3LifecycleReconcile(actor);assert.equal(runtime.ok,true,runtime.reason);assert.equal(actor.activeFx.filter(row=>row.bg3Status===ELEMENTAL_INFUSION_TEST.energy.fire).length,1);assert.equal(actor.activeFx.filter(row=>row.bg3Status===ELEMENTAL_INFUSION_TEST.vfx.fire).length,1);}return Object.assign(world,{ringEntry,runtime});}

