function realBg3DethroneIssue(world,{distance='30',save=1,dice=40,capture=true,targetKey=''}={}){const {e,actor,target,entry,useId}=world;assert.equal(e.combatUseItem(entry.id,useId),true,JSON.stringify({audit:e.bg3ItemDethroneAudit(),error:e.elementText('castErr'),status:e.elementText('status')}));e.setElementValue('castTarget',targetKey||'ally:'+target.id);e.setElementValue('castDethroneDistance',distance);assert.equal(e.castConfirm(),true,JSON.stringify({audit:e.bg3ItemDethroneAudit(),error:e.elementText('castErr')}));e.bg3ItemFormulaSetValues({dethroneSave:save,dethroneDice:dice});if(capture)e.bg3ItemFormulaCaptureNextDispatch(true);const result=e.castFormulaConfirm();assert.equal(result,false,JSON.stringify({audit:e.bg3ItemDethroneAudit(),error:e.elementText('castErr')}));const args=e.bg3ItemFormulaLastDispatch();if(capture){assert.ok(args);assert.equal(args.length,5);}return {args,audit:e.bg3ItemDethroneAudit(),turn:e.state().combat.turn};}

function realBg3HealingPotionSourceContract(use){
  const program=use&&use.program||{},source=program.sourceAction&&program.sourceAction.primary,attributes=source&&source.attributes||{},application=program.statusApplication,projection=program.projection;
  return !!(use&&use.handler==='bg3RuleProgram'&&use.rollPolicy==='player-input-required'&&use.target==='self'&&use.consume&&use.consume.kind==='item'&&+use.consume.amount===1
    &&source&&source.actionType===7&&source.index===0&&source.trigger==='OnUsePeaceActions'&&attributes.ActionType==='7'&&attributes.Conditions===''&&attributes.Consume==='True'&&attributes.StatsId==='POTION_OF_HEALING'&&attributes.StatusDuration==='0'
    &&application&&application.schemaVersion==='bg3-status-application/1'&&application.statusId==='POTION_OF_HEALING'&&application.target==='SELF'&&application.instant===true
    &&application.applicationKind==='status'&&application.sourceActionType===7&&application.duration&&application.duration.kind==='source'&&application.duration.value===0&&application.duration.raw==='0'
    &&projection&&projection.schemaVersion==='bg3-action-rule-projection/1'&&projection.mode==='typed'&&projection.complete===true&&projection.executionPolicy==='all-reachable-opcodes-or-fail-closed'
    &&(!Array.isArray(projection.unresolved)||projection.unresolved.length===0));
}

function realBg3HealingPotionManifestRows(){
  const repo=new URL('..',import.meta.url),rows=[];
  for(const descriptor of selectedBg3Catalog.manifest.files.items){
    const payload=JSON.parse(fs.readFileSync(new URL(descriptor.path,repo),'utf8'));
    for(const item of payload.items||[])for(const [profile,mechanics] of [['standard',item.mechanics]]){
      for(const use of mechanics&&mechanics.actions||[])if(realBg3HealingPotionSourceContract(use))rows.push({profile,itemId:item.id,useId:use.id,name:item.i18n&&item.i18n.en&&item.i18n.en.name,shard:descriptor.path});
    }
  }
  return rows;
}

