async function realBg3RecipeWorld(fixture,{sourceQty=1}={}){
  let randomCalls=0;const e=loadEngine(()=>{randomCalls++;return .5;},selectedBg3FileFetch()),entryId='real-recipe-source',actor=hero('real-recipe-actor',{knownRecipes:[],inventory:[{id:entryId,itemId:fixture.itemId,qty:sourceQty}],equipment:{}});e.setState({chars:[actor],activeCharId:actor.id});
  assert.equal(e.bg3CatalogUseRefs([{id:'bg3',version:selectedBg3Catalog.current.catalogVersion,profile:fixture.profile,manifestSha256:selectedBg3Catalog.current.manifestSha256}]),true);await e.bg3CatalogEnsureIndex();await e.bg3CatalogHydrate([fixture.itemId]);const asset=await e.bg3CatalogEnsureAsset('recipes'),recipe=asset.byId.get(fixture.recipeId);assert.ok(recipe,fixture.recipeId);if(recipe.accessPolicy&&recipe.accessPolicy.mode==='exact-formula-required')actor.knownRecipes.push(recipe.id);
  const selections={inputs:{},entries:{}},counts=new Map(),pickedBySlot=new Map(),ids=new Set([fixture.itemId]);for(const input of recipe.inputs){const candidates=e.bg3AvailableIds(input.candidateIds),picked=candidates[0];assert.ok(picked,recipe.id+' input '+input.slot);selections.inputs[input.slot]=picked;pickedBySlot.set(input.slot,picked);counts.set(picked,(counts.get(picked)||0)+1);ids.add(picked);}if(!recipe.dye){const results=e.bg3AvailableIds(recipe.result.candidateIds);assert.ok(results.length,recipe.id+' result');selections.result=results[0];ids.add(results[0]);}await e.bg3CatalogHydrate([...ids]);
  for(const [itemId,qty] of counts){let entry=actor.inventory.find(row=>row.itemId===itemId);if(entry)entry.qty=Math.max(+entry.qty||0,qty);else{entry={id:'real-recipe-input-'+actor.inventory.length,itemId,qty};actor.inventory.push(entry);}}
  for(const input of recipe.inputs)if(input.transform==='Transform'||input.transform==='Dye'){const target=actor.inventory.find(row=>row.itemId===pickedBySlot.get(input.slot));assert.ok(target);selections.entries[input.slot]=target.id;}
  randomCalls=0;return {e,actor,entryId,asset,recipe,selections,fixture,randomCalls:()=>randomCalls};
}

