  const active=Object.getOwnPropertyDescriptor(e.state().combat,'active');let combatHits=0;Object.defineProperty(e.state().combat,'active',{configurable:active.configurable,enumerable:active.enumerable,get(){combatHits++;return active.value;}});assert.equal((await e.bg3RecipeProgramCommit(plan)).ok,false);assert.equal(combatHits,0);Object.defineProperty(e.state().combat,'active',active);
