  const detached=plain(plan),detachedDone=await e.bg3LearnSpellCommit(detached);assert.equal(detachedDone.ok,false);assert.equal(detachedDone.reason,'private-learn-spell-plan-proof-required');assert.deepEqual(snapshot(),initial);assert.deepEqual(plain(e.bg3LearnSpellCommitAudit()),{phase:'rejected',itemId:'',useId:'',resourceTransactions:0});
  const tampered=await e.bg3LearnSpellPlanFor(actor,entryId,row.useId);tampered.fingerprint+=':tampered';assert.equal((await e.bg3LearnSpellCommit(tampered)).ok,false);assert.deepEqual(snapshot(),initial);
  const cross=await e.bg3LearnSpellPlanFor(actor,entryId,row.useId);cross.caster=other;assert.equal((await e.bg3LearnSpellCommit(cross)).ok,false);assert.deepEqual(snapshot(),initial,'a cross-caster transplant is rejected before any resource change');
  const victim=e.bg3LearnSpellTestCatalogItem(row.itemId),foreign=e.bg3LearnSpellTestCatalogItem(otherRow.itemId);e.bg3LearnSpellTestCatalogRebind(row.itemId,foreign);assert.equal((await e.bg3LearnSpellCommit(plan)).ok,false,'a foreign canonical scroll cannot be rebound under the victim id');assert.deepEqual(snapshot(),initial);e.bg3LearnSpellTestCatalogRebind(row.itemId,victim);
  const catalogAccessor=e.bg3RecipeTestCatalogAccessor('current',actor);try{assert.equal((await e.bg3LearnSpellCommit(plan)).ok,false);assert.equal(catalogAccessor.hits(),0);assert.equal(actor.notes,'catalog sentinel');}finally{catalogAccessor.restore();}assert.deepEqual(snapshot(),initial,'catalog accessor rejection mutates no resource');
  for(const key of ['JSON','Object','Array']){const poison=e.bg3RecipeTestGlobalAccessor(key,actor);let rejected;try{rejected=await e.bg3LearnSpellCommit(plan);}finally{poison.restore();}assert.equal(rejected.ok,false,key);assert.equal(poison.hits(),0,key+' LearnSpell global binding accessor');assert.equal(actor.notes,'catalog sentinel',key);assert.deepEqual(snapshot(),initial,key+' LearnSpell global accessor mutation');}
  const restoreCatalog=e.bg3LearnSpellTestCatalogCurrentSwap({manifestSha256:'f'.repeat(64)});try{assert.equal((await e.bg3LearnSpellCommit(plan)).ok,false);}finally{restoreCatalog();}assert.deepEqual(snapshot(),initial,'catalog-root drift spends nothing and leaves the exact plan retryable');
  const inventoryRef=actor.inventory,entryRef=actor.inventory[0],equipmentRef=actor.equipment,coinsRef=actor.coins,learnedRef=actor.bg3LearnedSpells;e.bg3LearnSpellTestInjectLateFailureOnce();const failed=await e.bg3LearnSpellCommit(plan);assert.equal(failed.ok,false);assert.match(failed.reason,/injected-late-failure/);assert.deepEqual(snapshot(),initial);assert.equal(actor.inventory,inventoryRef);assert.equal(actor.inventory[0],entryRef);assert.equal(actor.equipment,equipmentRef);assert.equal(actor.coins,coinsRef);assert.equal(actor.bg3LearnedSpells,learnedRef);assert.deepEqual(plain(e.bg3LearnSpellCommitAudit()),{phase:'rolled-back',itemId:row.itemId,useId:row.useId,resourceTransactions:0});
  const learned=await e.bg3LearnSpellCommit(plan);assert.equal(learned.ok,true,learned.reason);assert.equal(actor.inventory[0].qty,1);assert.equal(actor.bg3LearnedSpells.length,1);const learnedRow=actor.bg3LearnedSpells[0];assert.deepEqual(plain({spellId:learnedRow.spellId,ruleId:learnedRow.ruleId,programId:learnedRow.programId,artifact:learnedRow.artifact,learnedFrom:learnedRow.learnedFrom}),{spellId:row.spellId,ruleId:row.ruleId,programId:row.programId,artifact:row.ruleArtifact,learnedFrom:{itemId:row.itemId,entryId,useId:row.useId,rootProgramId:row.rootId,rootArtifact:row.rootArtifact}});assert.equal(e.bg3LearnSpellCommitAudit().resourceTransactions,1,'scroll, gold and learned consequence share one private transaction');const committed=snapshot();
  for(let i=0;i<2;i++){const replay=await e.bg3LearnSpellCommit(plan);assert.equal(replay.ok,false);assert.equal(replay.replay,true);assert.deepEqual(snapshot(),committed);assert.equal(e.bg3LearnSpellCommitAudit().phase,'replay-rejected');}
