  const world=await realBg3DethroneWorld(),{e,actor,target,entry,randomCalls,randomStacks}=world;await realBg3DethronePrepare(world);const turn=await realBg3DethroneStartCombat(world,'Dethrone deferred presentation failure'),{args}=realBg3DethroneIssue(world,{distance:'30',save:1,dice:40}),probe=e.bg3ItemDethroneTestInjectPresentationFailureOnce();assert.equal(e.bg3ItemFormulaApplyArgs(args),true);const committed=plain({qty:entry.qty,targetHp:target.hp,actionsUsed:turn.actionsUsed,actionUsed:turn.actionUsed,bonusUsed:turn.bonusUsed,slots:actor.slots});assert.equal(e.bg3ItemDethroneAudit().phase,'used');assert.equal(e.bg3ItemDethroneAudit().resourceTransactions,1);await Promise.resolve();await Promise.resolve();assert.equal(probe.hits(),1);assert.equal(e.bg3ItemFormulaApplyArgs(args),false);assert.equal(e.bg3ItemDethroneAudit().phase,'replay-rejected');assert.deepEqual(plain({qty:entry.qty,targetHp:target.hp,actionsUsed:turn.actionsUsed,actionUsed:turn.actionUsed,bonusUsed:turn.bonusUsed,slots:actor.slots}),committed);assert.equal(randomCalls(),0,'Dethrone deferred presentation and replay never roll\n'+randomStacks.join('\n---\n'));
