test('BG3 Arrow phase two B releases its lock after cyclic and BigInt stale-proof rejection',async()=>{
  const world=await realBg3ArrowPhaseOneWorld(),{e,actor,ally,foes,arrowEntry,useId,randomCalls,randomStacks}=world;await realBg3ArrowPrepareProgram(world);assert.equal(e.combatStart([{kind:'ally',id:actor.id,nat:20},{kind:'foe',id:foes[0].id,nat:1}],'Arrow throwing verification release'),true);await realBg3ArrowQuiesce(world);const randomBefore=randomCalls();assert.equal(e.combatUseItem(arrowEntry.id,useId),true);const {args}=realBg3ArrowEnterFour(world,{damageResults:[6,6,6,6]}),turn=e.state().combat.turn,before=plain({qty:arrowEntry.qty,allyHp:ally.hp,foeHp:foes.map(foe=>foe.hp),actionsUsed:turn.actionsUsed,actionUsed:turn.actionUsed,bonusUsed:turn.bonusUsed});for(const variant of ['cycle','bigint']){if(variant==='cycle')ally.extra=ally;else ally.extra=1n;let result;try{result=e.bg3ItemFormulaApplyArgs(args);}catch(error){assert.fail(variant+' stale verification leaked: '+String(error&&error.stack||error));}assert.equal(result,false,variant);const audit=e.bg3ItemArrowAudit();assert.equal(audit.phase,'proof-rejected',variant);assert.equal(audit.resourceTransactions,0,variant);assert.equal(audit.commitEnabled,true,variant);delete ally.extra;assert.deepEqual(plain({qty:arrowEntry.qty,allyHp:ally.hp,foeHp:foes.map(foe=>foe.hp),actionsUsed:turn.actionsUsed,actionUsed:turn.actionUsed,bonusUsed:turn.bonusUsed}),before,variant+' rejects without payment or consequences');}assert.equal(e.bg3ItemFormulaApplyArgs(args),true,'the same proof commits after both stale fields are removed');assert.equal(e.bg3ItemArrowAudit().phase,'used');assert.equal(e.bg3ItemArrowAudit().resourceTransactions,1);assert.equal(e.bg3ItemFormulaApplyArgs(args),false,'the committed proof remains terminal');assert.equal(e.bg3ItemArrowAudit().phase,'replay-rejected');assert.equal(randomCalls(),randomBefore,'throwing verification rejection, retry, and replay never roll\n'+randomStacks.slice(randomBefore).join('\n---\n'));
});

