test('BG3 Arrow phase two A requires lifecycle quiescence at open and precommit and survives canonical rebind restoration',async()=>{
  const pendingWorld=await realBg3ArrowPhaseOneWorld(),{e:pendingEngine,actor:pendingActor,arrowEntry:pendingArrow,useId:pendingUse}=pendingWorld,pendingBefore=pendingEngine.bg3ItemArrowTestLifecycleRuntimeSnapshot(pendingActor),never=new Promise(()=>{}),clearOpenPending=pendingEngine.bg3ItemArrowTestLifecyclePendingSet(pendingActor,never);try{assert.equal(await pendingEngine.bg3ItemProgramOpen(pendingArrow.id,pendingActor.id,pendingUse),false);assert.equal(pendingEngine.elementText('castErr'),PRIVATE_ITEM_SAFE_PUBLIC_ERROR);assert.equal(pendingEngine.bg3ItemArrowAudit(),null);}finally{clearOpenPending();}assertBg3ArrowLifecycleRuntimeSame(pendingBefore,pendingEngine.bg3ItemArrowTestLifecycleRuntimeSnapshot(pendingActor),'pending open restore');assert.equal(await pendingEngine.bg3ItemProgramOpen(pendingArrow.id,pendingActor.id,pendingUse),true,'the authentic open retries after pending clears');
  const world=await realBg3ArrowPhaseOneWorld(),{e,actor,ally,foes,arrowEntry,weaponEntry,useId}=world;await realBg3ArrowPrepareProgram(world);assert.equal(e.combatStart([{kind:'ally',id:actor.id,nat:20},{kind:'foe',id:foes[0].id,nat:1}],'Arrow lifecycle precommit'),true);await realBg3ArrowQuiesce(world);assert.equal(e.combatUseItem(arrowEntry.id,useId),true);e.setElementValue('castTarget','ally:'+ally.id);e.setElementValue('castWeapon',weaponEntry.id);for(let i=0;i<3;i++)e.setElementValue('castBg3ArrowExtra'+(i+1),'foe:'+foes[i].id);const original=e.bg3LearnSpellTestCatalogItem(REAL_BG3_ARROW_MANY_TARGETS.itemId),clone=plain(original);e.bg3LearnSpellTestCatalogRebind(REAL_BG3_ARROW_MANY_TARGETS.itemId,clone);try{assert.equal(e.castConfirm(),false);assert.equal(e.elementText('castErr'),PRIVATE_ITEM_SAFE_PUBLIC_ERROR);assert.ok(['private-item-arrow-canonical-catalog-definition-required','private-item-arrow-definition-membership-changed'].includes(e.bg3ItemArrowAudit().reason),e.bg3ItemArrowAudit().reason);}finally{e.bg3LearnSpellTestCatalogRebind(REAL_BG3_ARROW_MANY_TARGETS.itemId,original);}assert.equal(e.castConfirm(),true,'same unopened selection resumes after canonical map restoration');for(let order=0;order<4;order++){e.castDistanceSet('far');const spec=e.castState().spec,values={};for(const row of spec.rows)if(row.required)values[row.key]=row.type==='atk'?19:Math.max(1,+row.cnt||1);e.bg3ItemFormulaSetValues(values);if(order===3)e.bg3ItemFormulaCaptureNextDispatch(true);assert.equal(e.castFormulaConfirm(),order<3);}const args=e.bg3ItemFormulaLastDispatch(),runtimeBefore=e.bg3ItemArrowTestLifecycleRuntimeSnapshot(actor),clearPrecommit=e.bg3ItemArrowTestLifecyclePendingSet(actor,never);try{assert.equal(e.bg3ItemFormulaApplyArgs(args),false);assert.equal(e.bg3ItemArrowAudit().phase,'proof-rejected');assert.equal(e.bg3ItemArrowAudit().reason,'private-item-arrow-lifecycle-runtime-state-changed');}finally{clearPrecommit();}assertBg3ArrowLifecycleRuntimeSame(runtimeBefore,e.bg3ItemArrowTestLifecycleRuntimeSnapshot(actor),'pending precommit restore');assert.equal(e.bg3ItemFormulaApplyArgs(args),true);assert.equal(e.bg3ItemArrowAudit().phase,'used');assert.equal(e.bg3ItemArrowAudit().resourceTransactions,1);
});

test('BG3 Arrow phase two A fails closed on a natural twenty against exact top-level critical immunity',async()=>{
  const world=await realBg3ArrowPhaseOneWorld(),{e,actor,ally,foes,arrowEntry,weaponEntry,useId,randomCalls,randomStacks}=world;foes[0].criticalHitImmune=true;foes[0].mechanics.defenses.criticalHitImmune=true;const before=plain({actor,ally,foes,combat:e.state().combat,qty:arrowEntry.qty});assert.equal(await e.bg3ItemProgramOpen(arrowEntry.id,actor.id,useId),true);e.setElementValue('castTarget','ally:'+ally.id);e.setElementValue('castWeapon',weaponEntry.id);for(let i=0;i<3;i++)e.setElementValue('castBg3ArrowExtra'+(i+1),'foe:'+foes[i].id);assert.equal(e.castConfirm(),true);e.castDistanceSet('far');let spec=e.castState().spec,values={};for(const row of spec.rows)if(row.required)values[row.key]=row.type==='atk'?19:Math.max(1,+row.cnt||1);e.bg3ItemFormulaSetValues(values);assert.equal(e.castFormulaConfirm(),true);e.castDistanceSet('far');spec=e.castState().spec;assert.equal(spec.meta.criticalHitImmune,true);values={};for(const row of spec.rows)if(row.required)values[row.key]=row.type==='atk'?20:(+row.cnt||1)*2;e.bg3ItemFormulaSetValues(values);assert.equal(e.castFormulaConfirm(),false,'immune target cannot mint a doubled-dice private receipt');assert.equal(e.bg3ItemArrowAudit().reason,'private-item-arrow-critical-immunity-fail-closed');assert.equal(e.bg3ItemArrowAudit().receiptCount,1);assert.equal(e.bg3ItemArrowAudit().masterProofIssued,undefined);assert.deepEqual(plain({actor,ally,foes,combat:e.state().combat,qty:arrowEntry.qty}),before);assert.equal(randomCalls(),0,'critical immunity preflight never rolls\n'+randomStacks.join('\n---\n'));
  const normal=await realBg3ArrowPhaseOneWorld(),{e:normalEngine,actor:normalActor,ally:normalAlly,foes:normalFoes,arrowEntry:normalArrow,weaponEntry:normalWeapon,useId:normalUse}=normal;assert.equal(await normalEngine.bg3ItemProgramOpen(normalArrow.id,normalActor.id,normalUse),true);normalEngine.setElementValue('castTarget','ally:'+normalAlly.id);normalEngine.setElementValue('castWeapon',normalWeapon.id);for(let i=0;i<3;i++)normalEngine.setElementValue('castBg3ArrowExtra'+(i+1),'foe:'+normalFoes[i].id);assert.equal(normalEngine.castConfirm(),true);normalEngine.castDistanceSet('far');const normalSpec=normalEngine.castState().spec;assert.equal(normalSpec.meta.criticalHitImmune,false);const normalValues={};for(const row of normalSpec.rows)if(row.required)normalValues[row.key]=row.type==='atk'?20:(+row.cnt||1)*2;normalEngine.bg3ItemFormulaSetValues(normalValues);assert.equal(normalEngine.castFormulaConfirm(),true);assert.equal(normalEngine.bg3ItemArrowAudit().receiptCount,1);
});

test('BG3 Arrow phase two A fails closed before proof for attack removals, legacy invisibility, grants, and modal active effects',async()=>{
  const cases=[
    {label:'legacy breakOn string',fx:{uid:'arrow-break-string',breakOn:'attack,spell'},reason:'private-item-arrow-attack-trigger-removal-fail-closed'},
    {label:'legacy invisibility',fx:{uid:'arrow-invisibility',id:'«НЕВИДИМОСТЬ»'},reason:'private-item-arrow-attack-trigger-removal-fail-closed'},
    {label:'hit point grant',fx:{uid:'arrow-hp-grant',hpGrant:5},reason:'private-item-arrow-attack-trigger-grant-removal-fail-closed'},
    {label:'concentration oil',fx:{uid:'arrow-modal-effect',conc:true,itemTrigger:'oil'},reason:'private-item-arrow-modal-active-effect-fail-closed'}
  ];
  for(const row of cases){const world=await realBg3ArrowPhaseOneWorld(),{e,actor,ally,foes,arrowEntry,weaponEntry,useId,randomCalls,randomStacks}=world;actor.activeFx=[row.fx];const before=plain({actor,ally,foes,combat:e.state().combat,qty:arrowEntry.qty});assert.equal(await e.bg3ItemProgramOpen(arrowEntry.id,actor.id,useId),true,row.label);e.setElementValue('castTarget','ally:'+ally.id);e.setElementValue('castWeapon',weaponEntry.id);for(let i=0;i<3;i++)e.setElementValue('castBg3ArrowExtra'+(i+1),'foe:'+foes[i].id);assert.equal(e.castConfirm(),false,row.label);const audit=e.bg3ItemArrowAudit();assert.equal(audit.phase,'rejected',row.label);assert.equal(audit.reason,row.reason,row.label);assert.equal(audit.receiptCount,0,row.label);assert.equal(audit.masterProofIssued,undefined,row.label);assert.equal(audit.resourceTransactions,0,row.label);assert.deepEqual(plain({actor,ally,foes,combat:e.state().combat,qty:arrowEntry.qty}),before,row.label);assert.equal(randomCalls(),0,row.label+' never rolls\n'+randomStacks.join('\n---\n'));}
});

test('BG3 Arrow phase one binds an honest offhand selection to a private bonus-action receipt without spending it',async()=>{
  const world=await realBg3ArrowPhaseOneWorld({weaponItemId:'it_ручной_арбалет',equipmentSlot:'OFF_HAND'}),{e,actor,ally,foes,arrowEntry,weaponEntry,useId,randomCalls,randomStacks}=world;await e.bg3CatalogEnsureIndex();await e.bg3CatalogHydrate([REAL_BG3_ARROW_MANY_TARGETS.itemId]);const item=e.bg3LearnSpellTestCatalogItem(REAL_BG3_ARROW_MANY_TARGETS.itemId),use=e.itemUseOf(item,useId);assert.ok(await e.bg3RuleProgramPrepare(use));await realBg3ArrowQuiesce(world);assert.equal(e.combatStart([{kind:'ally',id:actor.id,nat:20},{kind:'foe',id:foes[0].id,nat:1}],'Arrow offhand phase one'),true);await realBg3ArrowQuiesce(world);const randomBefore=randomCalls(),turn=e.state().combat.turn;turn.actionMax=1;turn.actionsUsed=1;turn.actionUsed=true;turn.bonusUsed=false;const before=plain({actor,foes,turn});assert.equal(e.combatUseItem(arrowEntry.id,useId),true,JSON.stringify({audit:e.bg3ItemArrowAudit(),error:e.elementText('castErr'),status:e.elementText('status')}));const ctx=e.castState().ctx;assert.equal(Object.prototype.hasOwnProperty.call(ctx,'combatCost'),false,'public cast context never supplies the selected-slot cost');assert.equal(Object.prototype.hasOwnProperty.call(ctx,'combatActorKey'),false);
  e.setElementValue('castTarget','ally:'+ally.id);e.setElementValue('castWeapon',weaponEntry.id);for(let i=0;i<3;i++)e.setElementValue('castBg3ArrowExtra'+(i+1),'foe:'+foes[i].id);assert.equal(e.castConfirm(),true,JSON.stringify({audit:e.bg3ItemArrowAudit(),error:e.elementText('castErr')}));const audit=e.bg3ItemArrowAudit();assert.deepEqual(plain(audit.weapon),{entryId:weaponEntry.id,itemId:weaponEntry.itemId,slot:'offhand',offhand:true,cost:'bonus'});assert.deepEqual(plain({actor,foes,turn}),before,'phase-one offhand receipt spends neither action nor bonus action');assert.equal(turn.actionsUsed,1);assert.equal(turn.bonusUsed,false);assert.equal(arrowEntry.qty,2);assert.equal(randomCalls(),randomBefore,'offhand preflight never rolls\n'+randomStacks.slice(randomBefore).join('\n---\n'));
});

