test('BG3 Arrow phase one invokes neither hostile FreshFx nor PlanOf globals and resumes the authentic context',async()=>{
  const world=await realBg3ArrowPhaseOneWorld(),{e,actor,ally,foes,arrowEntry,weaponEntry,useId}=world;assert.equal(await e.bg3ItemProgramOpen(arrowEntry.id,actor.id,useId),true);e.setElementValue('castTarget','ally:'+ally.id);e.setElementValue('castWeapon',weaponEntry.id);for(let i=0;i<3;i++)e.setElementValue('castBg3ArrowExtra'+(i+1),'foe:'+foes[i].id);
  const freshPoison=e.bg3RecipeTestGlobalAccessor('bg3GithbornMindcrusherWithFreshFx',actor);let blocked;try{blocked=e.castConfirm();}finally{freshPoison.restore();}assert.equal(blocked,false);assert.equal(freshPoison.hits(),0,'changed FreshFx binding is rejected descriptor-first');assert.notEqual(actor.notes,'global-accessor-fired');
  const planPoison=e.bg3RecipeTestGlobalAccessor('bg3RuleProgramPlanOf',actor);try{assert.equal(e.castConfirm(),true,JSON.stringify({audit:e.bg3ItemArrowAudit(),error:e.elementText('castErr')}));e.castDistanceSet('far');const values={};for(const row of e.castState().spec.rows)if(row.required)values[row.key]=row.type==='atk'?19:(row.natural?10:Math.max(1,+row.cnt||1));e.bg3ItemFormulaSetValues(values);assert.equal(e.castFormulaConfirm(),true);}finally{planPoison.restore();}assert.equal(planPoison.hits(),0,'private source-derived formula never consults ambient PlanOf');assert.notEqual(actor.notes,'global-accessor-fired');assert.equal(e.bg3ItemArrowAudit().receiptCount,1);assert.equal(arrowEntry.qty,2);
});

test('BG3 Arrow phase one privately seals spatial and damage rows, rejects a public spec mutation, and resumes under hostile digest globals',async()=>{
  const world=await realBg3ArrowPhaseOneWorld(),{e,actor,ally,foes,arrowEntry,weaponEntry,useId}=world;actor.notes='arrow canonical sentinel';assert.equal(await e.bg3ItemProgramOpen(arrowEntry.id,actor.id,useId),true);e.setElementValue('castTarget','ally:'+ally.id);e.setElementValue('castWeapon',weaponEntry.id);for(let i=0;i<3;i++)e.setElementValue('castBg3ArrowExtra'+(i+1),'foe:'+foes[i].id);assert.equal(e.castConfirm(),true);e.castDistanceSet('far');const spec=e.castState().spec,damage=spec.rows.find(row=>row.type==='dmg'&&row.key==='dmg');assert.ok(damage);assert.equal(spec.meta.weapon,true);const originalMultiplier=damage.multiplier,values={};for(const row of spec.rows)if(row.required)values[row.key]=row.type==='atk'?19:(row.natural?10:Math.max(1,+row.cnt||1));e.bg3ItemFormulaSetValues(values);const before=plain({actor,ally,foes,combat:e.state().combat}),poisons=['bg3Sha256Sync','bg3CanonicalJSON','bg3InterruptStableState'].map(key=>({key,poison:e.bg3RecipeTestGlobalAccessor(key,actor)}));try{damage.multiplier=originalMultiplier+1;assert.equal(e.castFormulaConfirm(),false,'a public damage multiplier cannot satisfy the private formula receipt');damage.multiplier=originalMultiplier;assert.equal(e.castFormulaConfirm(),false,'changed legacy digest authority is rejected before formula evaluation');assert.deepEqual(plain({actor,ally,foes,combat:e.state().combat}),before);}finally{for(let i=poisons.length-1;i>=0;i--)poisons[i].poison.restore();}
  for(const {key,poison} of poisons)assert.equal(poison.hits(),0,key+' must not be resolved by the private Arrow receipt');assert.equal(actor.notes,'arrow canonical sentinel');assert.equal(e.castFormulaConfirm(),true,JSON.stringify({audit:e.bg3ItemArrowAudit(),error:e.elementText('castErr')}));e.castDistanceSet('far');assert.equal(e.castState().spec.meta.bg3ArrowOrder,1,'the authentic context continues with the next explicit spatial receipt');assert.equal(e.castState().spec.meta.weapon,true);const audit=e.bg3ItemArrowAudit();assert.equal(audit.phase,'collecting');assert.equal(audit.receiptCount,1);assert.match(audit.receipts[0].specSha256,/^[0-9a-f]{64}$/);assert.match(audit.receipts[0].spatialSha256,/^[0-9a-f]{64}$/);assert.equal(audit.receipts[0].damageScale,'1/1');assert.equal(arrowEntry.qty,2);assert.equal(audit.resourceTransactions,0);
});

