test('BG3 summon replaces only an exact nonempty same-caster stack and never an empty sibling stack',async()=>{
  const casterId='real-bg3-summon-user',stack='bg3-summon:IntellectDevourStack',same={uid:'summon-stack-same',k:'bg3-summon',id:'old-same',casterId,stackKey:stack,fx:[],mechanicsVersion:1,effectSchemaVersion:1},foreign={uid:'summon-stack-foreign',k:'bg3-summon',id:'old-foreign',casterId:'another-caster',stackKey:stack,fx:[],mechanicsVersion:1,effectSchemaVersion:1},empty={uid:'summon-stack-empty',k:'bg3-summon',id:'old-empty',casterId,stackKey:'',fx:[],mechanicsVersion:1,effectSchemaVersion:1},different={uid:'summon-stack-different',k:'bg3-summon',id:'old-different',casterId,stackKey:'bg3-summon:OtherStack',fx:[],mechanicsVersion:1,effectSchemaVersion:1},world=await realBg3SummonWorld({row:REAL_BG3_SUMMON_ROWS[3],activeFx:[same,foreign,empty,different]}),{e,actor}=world,opened=await realBg3SummonOpen(world,{position:'stack-world,1,2,3',canStand:true});assert.equal(opened.opened,true);assert.equal(e.castConfirm(),true,JSON.stringify(e.bg3ItemSummonAudit()));const uids=new Set(actor.activeFx.map(effect=>effect.uid));assert.equal(uids.has(same.uid),false);for(const effect of [foreign,empty,different])assert.equal(uids.has(effect.uid),true,effect.uid);assert.equal(actor.activeFx.filter(effect=>effect.k==='bg3-summon'&&effect.id===REAL_BG3_SUMMON_ROWS[3].spellId).length,1);assert.equal(actor.inventory[0].qty,2,'the exact non-consuming carrier remains in inventory');
  const emptySibling={uid:'summon-empty-light-sibling',k:'bg3-summon',id:'another-empty-source',casterId,stackKey:'',fx:[],mechanicsVersion:1,effectSchemaVersion:1},light=await realBg3SummonWorld({activeFx:[emptySibling]}),liveEmptySibling=light.actor.activeFx[0],lightOpen=await realBg3SummonOpen(light,{position:'empty-stack-world,1,2,3'});assert.equal(lightOpen.opened,true);assert.equal(light.e.castConfirm(),true);assert.equal(light.actor.activeFx.includes(liveEmptySibling),true,'an empty source stack never authorizes sibling replacement');assert.equal(light.actor.activeFx.filter(effect=>effect.k==='bg3-summon').length,2);
});

