test('BG3 summon proof rejects detached inputs and hostile post-open roots without invoking accessors',async()=>{
  const world=await realBg3SummonWorld(),{e,actor,entryId,useId,randomCalls,randomStacks}=world,other=hero('summon-proof-other'),opened=await realBg3SummonOpen(world,{position:'proof-world,1,2,3'});e.state().chars.push(other);assert.equal(opened.opened,true);e.bg3ItemFormulaCaptureNextDispatch(true);assert.equal(e.castConfirm(),false);const args=e.bg3ItemFormulaLastDispatch(),carrier=args&&args[3],before=plain({actor,other,combat:e.state().combat});assert.ok(carrier);assert.equal(e.bg3ItemSummonAudit().phase,'issued');
  assert.equal(e.bg3ItemFormulaApplyArgs(['wrong-entry',args[1],args[2],carrier,args[4]]),false);assert.equal(e.bg3ItemFormulaApplyArgs([args[0],'wrong-caster',args[2],carrier,args[4]]),false);assert.equal(e.bg3ItemFormulaApplyArgs([args[0],args[1],'ally:'+other.id,carrier,args[4]]),false);assert.equal(e.bg3ItemFormulaApplyArgs([args[0],args[1],args[2],carrier,'wrong-use']),false);assert.equal(e.bg3ItemFormulaApplyArgs([args[0],args[1],args[2],Object.assign({},carrier),args[4]]),false);
  let carrierHits=0;const carrierProxy=new Proxy(carrier,{get(){carrierHits++;throw new Error('detached carrier getter');},getOwnPropertyDescriptor(){carrierHits++;throw new Error('detached carrier descriptor');},ownKeys(){carrierHits++;throw new Error('detached carrier ownKeys');}});assert.equal(e.bg3ItemFormulaApplyArgs([args[0],args[1],args[2],carrierProxy,args[4]]),false);assert.equal(carrierHits,0);let optsHits=0;const optsProxy=new Proxy({},{get(){optsHits++;throw new Error('public opts getter');},ownKeys(){optsHits++;throw new Error('public opts ownKeys');}});assert.equal(e.bg3ItemFormulaApplyArgs([...args,optsProxy]),false);assert.equal(optsHits,0);
  actor.hp++;assert.equal(e.bg3ItemFormulaApplyArgs(args),false,'stale world data must reject before mutation');actor.hp--;for(const key of ['active','turn','log']){const combat=e.state().combat,descriptor=Object.getOwnPropertyDescriptor(combat,key);let hits=0;Object.defineProperty(combat,key,{configurable:true,enumerable:descriptor.enumerable,get(){hits++;throw new Error('combat '+key+' getter');}});try{assert.equal(e.bg3ItemFormulaApplyArgs(args),false,key);}finally{Object.defineProperty(combat,key,descriptor);}assert.equal(hits,0,key+' accessor must not run');}
  const fxDescriptor=Object.getOwnPropertyDescriptor(actor,'__fxC');let fxHits=0;Object.defineProperty(actor,'__fxC',{configurable:true,get(){fxHits++;throw new Error('forged derived cache getter');}});try{assert.equal(e.bg3ItemFormulaApplyArgs(args),false);}finally{if(fxDescriptor)Object.defineProperty(actor,'__fxC',fxDescriptor);else delete actor.__fxC;}assert.equal(fxHits,0,'forged __fxC is never authority or executable input');
  for(const key of ['bg3Array','bg3WizardProfileBinding','bg3GithbornMindcrusherWithFreshFx']){const poison=e.bg3RecipeTestGlobalAccessor(key,actor);let rejected;try{rejected=e.bg3ItemFormulaApplyArgs(args);}finally{poison.restore();}assert.equal(rejected,false,key);assert.equal(poison.hits(),0,key+' authority accessor must not run');assert.notEqual(actor.notes,'global-accessor-fired');}
  {const poison=e.bg3RecipeTestGlobalAccessor('useItemApply',actor);let rejected;try{rejected=e.castConfirm();}finally{poison.restore();}assert.equal(rejected,false);assert.equal(poison.hits(),0,'the UI dispatch resolves the sealed wrapper descriptor-first');assert.notEqual(actor.notes,'global-accessor-fired');}
  assert.deepEqual(plain({actor,other,combat:e.state().combat}),before);const randomBefore=randomCalls(),irrelevant=['Math','Date','fxUid','castUid','combatCostLabel','bg3RuleProgramPreflight','bg3CatalogLoadArtifact','itemSpendOne','commitItemUseResource','bg3InterruptCastFinish','fxInvalidate','renderChars','renderFoes','renderCombat','setStatus'],poisons=[];let committedResult=false;try{for(const key of irrelevant)poisons.push({key,poison:e.bg3RecipeTestGlobalAccessor(key,actor)});committedResult=e.bg3ItemFormulaApplyArgs(args);}finally{for(let i=poisons.length-1;i>=0;i--)poisons[i].poison.restore();}assert.equal(committedResult,true,JSON.stringify({audit:e.bg3ItemSummonAudit(),error:e.elementText('castErr'),status:e.elementText('status')}));for(const {key,poison} of poisons)assert.equal(poison.hits(),0,key+' unused/captured global accessor must not run');assert.notEqual(actor.notes,'global-accessor-fired');assert.equal(actor.inventory[0].qty,1);assert.equal(actor.activeFx.filter(effect=>effect.k==='bg3-summon').length,1);const committed=plain({actor,other,combat:e.state().combat});assert.equal(e.bg3ItemFormulaApplyArgs(args),false);assert.deepEqual(plain({actor,other,combat:e.state().combat}),committed);assert.equal(randomCalls(),randomBefore,'tamper rejection and restored commit never roll\n'+randomStacks.slice(randomBefore).join('\n---\n'));
});

