    ref={id:`${itemId}:lifecycle:${profile}:0`,ruleId:source.ruleId,bg3Id:source.bg3Id,kind:'passive',sourceField:'PassivesOnEquip',gate:'equipped',programId,sourceProfile:profile,
      artifact:source.artifact,mode:manual?'manual':'typed',executionPolicy:'preflight-fail-closed',ownsReferencedProgram:true,projection,projectionMode:manual?'manual':'typed',sourceRuleReferences},
    mechanics=bg3TestMechanics({kind:'weapon',lifecyclePrograms:[ref]}),compiled=arcaneEnchantmentRule(profile,source,{manual});
