test('BG3 Arcane Enchantment Lesser whole field gives real melee/ranged spell attacks and spell DC only +1 per equipped carrier', async () => {
  for(const profile of ['standard']){
    const fixtures=[arcaneEnchantmentFixture(profile,profile==='standard'?701:711),arcaneEnchantmentFixture(profile,profile==='standard'?702:712),arcaneEnchantmentFixture(profile,profile==='standard'?703:713)],
      e=loadEngine(),spells=e.seedSpellsDB(),foe=plain(e.seedFoesDB()[0]),actor=hero(`arcane-lesser-${profile}`,{inventory:fixtures.map((fixture,index)=>({id:`arcane-entry-${index}`,itemId:fixture.item.id,qty:1})),
        equipment:{HEAD:'arcane-entry-0',BODY:'arcane-entry-1'}});
    e.setState({chars:[actor],items:fixtures.map(fixture=>fixture.item),spells,foes:[foe],activeCharId:actor.id});e.bg3ArcaneEnchantmentLesserTestInstall(fixtures.map(fixture=>fixture.item),fixtures[0].rule,profile);
    assert.equal(e.bg3ArcaneEnchantmentLesserRuntimeCapabilityCheck(),true,`${profile}: exact synthetic manifest capability`);let state=await e.bg3LifecycleReconcile(actor);
    assert.equal(state.rows.filter(row=>row.status==='applied').length,2);assert.equal(state.rows.filter(row=>row.status==='inactive').length,1);assert.equal(state.sources.length,2);
    assert.equal(e.fxSum(actor,'spell.dc'),2);assert.equal(e.fxSum(actor,'spell.atk'),2,'two source selectors become one unified +1 per carrier, never +2 per carrier');
    assert.equal(e.spellDC(actor),16);assert.equal(e.spellAtk(actor),8);
    const target=e.targetInfoOf(`foe:${foe.id}`),melee=spells.find(spell=>e.currentMechanics(spell,'spell')?.resolution?.attack?.mode==='melee'),
      ranged=spells.find(spell=>e.currentMechanics(spell,'spell')?.resolution?.attack?.mode==='ranged'),saveSpell=spells.find(spell=>e.currentMechanics(spell,'spell')?.resolution?.save);
    assert.ok(melee,`${profile}: a seeded real melee spell attack exists`);assert.ok(ranged,`${profile}: a seeded real ranged spell attack exists`);assert.ok(saveSpell,`${profile}: a seeded real save spell exists`);
    const meleeSpec=e.rollSpecOf(melee,{caster:actor,kind:'spell',target}),rangedSpec=e.rollSpecOf(ranged,{caster:actor,kind:'spell',target}),saveSpec=e.rollSpecOf(saveSpell,{caster:actor,kind:'spell',target});
    assert.equal(meleeSpec.meta.attackMode,'melee');assert.equal(meleeSpec.rows.find(row=>row.type==='atk').mod,8);assert.equal(rangedSpec.meta.attackMode,'ranged');assert.equal(rangedSpec.rows.find(row=>row.type==='atk').mod,8);
    assert.equal(saveSpec.rows.find(row=>row.type==='save').dc,16);assert.equal(e.bg3LifecycleActionPreflight(actor,'ordinary-entry','spell',null).ok,true);
    delete actor.equipment.BODY;state=await e.bg3LifecycleReconcile(actor);assert.equal(state.rows.filter(row=>row.status==='applied').length,1);assert.equal(e.fxSum(actor,'spell.dc'),1);assert.equal(e.fxSum(actor,'spell.atk'),1);
    actor.equipment={};state=await e.bg3LifecycleReconcile(actor);assert.equal(state.rows.every(row=>row.status==='inactive'),true);assert.equal(e.fxSum(actor,'spell.dc'),0);assert.equal(e.fxSum(actor,'spell.atk'),0);
  }
});

