  const e=loadEngine(),world=grantedWeaponRuntimeWorld(e,'Target_OpeningAttack'),{actor,target,targetKey,state}=world;assert.equal(e.combatStart([{kind:'ally',id:actor.id,nat:20},{kind:'ally',id:target.id,nat:10},{kind:'foe',id:world.dummy.id,nat:1}],'private virtual identity'),true);const confirmed=grantedWeaponRolls(e,world,{hit:true,damage:3}),token=confirmed.rolls.bg3GithbornMindcrusherOrigin.actionToken;let traps=0;
  const touch=()=>{traps++;actor.notes='PWNED-BY-VIRTUAL-'+traps;},clone=Object.assign({},world.virtual,{use:Object.assign({},world.virtual.use,{label:'forged duplicate'})}),proxy=new Proxy(clone,{get(target,key,receiver){touch();return Reflect.get(target,key,receiver);},getOwnPropertyDescriptor(target,key){touch();return Reflect.getOwnPropertyDescriptor(target,key);},ownKeys(target){touch();return Reflect.ownKeys(target);},getPrototypeOf(target){touch();return Reflect.getPrototypeOf(target);}}),before=plain({actor,target});state.virtuals.unshift(proxy);grantedWeaponCast(e,world);
  assert.equal(e.bg3LifecycleGrantedApply(actor.id,world.virtual.id,targetKey,confirmed.rolls),false);assert.equal(traps,0,'membership identity must fail before inspecting the Proxy');assert.equal(actor.notes,undefined);assert.deepEqual(plain({actor,target}),before);assert.deepEqual(plain(e.bg3GithbornMindcrusherTestTokenState(token)),{used:false,locked:false});
  assert.equal(state.virtuals.shift(),proxy);grantedWeaponCast(e,world);assert.equal(e.bg3LifecycleGrantedApply(actor.id,world.virtual.id,targetKey,confirmed.rolls),true,e.elementText('saveStatus')+' '+e.elementText('castErr'));assert.equal(traps,0);assert.equal(target.hp,27);assert.deepEqual(plain(e.bg3GithbornMindcrusherTestTokenState(token)),{used:true,locked:false});
