test('BG3 private world identity rejects post-confirm duplicate reorder and clone swaps without burning the proof', async () => {
  for(const variant of ['duplicate-actor','duplicate-target','duplicate-entry','duplicate-item','reorder-chars','reorder-inventory','clone-entry-swap','clone-item-swap']){
    const world=await githbornWorld(),{e,actor,target,targetKey,sword}=world,confirmed=githbornConfirmedWeaponRolls(world),token=confirmed.rolls.bg3GithbornMindcrusherProof.actionToken,state=e.state(),undo=[];let injected;
    if(variant==='duplicate-actor'){injected=Object.assign({},actor);state.chars.push(injected);undo.push(()=>assert.equal(state.chars.pop(),injected));}
    if(variant==='duplicate-target'){injected=Object.assign({},target);state.chars.push(injected);undo.push(()=>assert.equal(state.chars.pop(),injected));}
    if(variant==='duplicate-entry'){injected=Object.assign({},actor.inventory.find(row=>row.id==='githborn-sword'));actor.inventory.push(injected);undo.push(()=>assert.equal(actor.inventory.pop(),injected));}
    if(variant==='duplicate-item'){injected=Object.assign({},sword);state.itemsDB.push(injected);undo.push(()=>assert.equal(state.itemsDB.pop(),injected));}
    if(variant==='reorder-chars'){state.chars.reverse();undo.push(()=>state.chars.reverse());}
    if(variant==='reorder-inventory'){actor.inventory.reverse();undo.push(()=>actor.inventory.reverse());}
    if(variant==='clone-entry-swap'){const index=actor.inventory.findIndex(row=>row.id==='githborn-sword'),exact=actor.inventory[index];injected=Object.assign({},exact);actor.inventory[index]=injected;undo.push(()=>{assert.equal(actor.inventory[index],injected);actor.inventory[index]=exact;});}
    if(variant==='clone-item-swap'){const index=state.itemsDB.indexOf(sword),exact=state.itemsDB[index];injected=Object.assign({},exact);state.itemsDB[index]=injected;undo.push(()=>{assert.equal(state.itemsDB[index],injected);state.itemsDB[index]=exact;});}
    const beforeHp=target.hp;assert.equal(e.weaponAttackApply('githborn-sword',actor.id,targetKey,confirmed.rolls),false,variant);assert.equal(target.hp,beforeHp,variant);assert.deepEqual(plain(e.bg3GithbornMindcrusherTestTokenState(token)),{used:false,locked:false},variant);for(const restore of undo.reverse())restore();
    assert.equal(e.weaponAttackApply('githborn-sword',actor.id,targetKey,confirmed.rolls),true,variant+': '+e.elementText('saveStatus'));assert.equal(target.hp,beforeHp-7,variant);assert.deepEqual(plain(e.bg3GithbornMindcrusherTestTokenState(token)),{used:true,locked:false},variant);
  }
});

